        wrap_pytest_function_for_tracing(pyfuncitem)

def setup(self, f, tb):
    """Suspend on setup().

                Needed after do_continue resumed, and entering another
                breakpoint again.
                """
    ret = super().setup(f, tb)
    if not ret and self._continued:
        if self._pytest_capman:
            self._pytest_capman.suspend_global_capture(in_=True)
    return ret

@contextmanager
def _patch_unwrap_mock_aware() -> Generator[None]:
    """Context manager which replaces ``inspect.unwrap`` with a version
    that's aware of mock objects and doesn't recurse into them."""
    real_unwrap = inspect.unwrap

    def _mock_aware_unwrap(func: Callable[..., Any], *, stop: Callable[[Any], Any] | None=None) -> Any:
        try:
            if stop is None or stop is _is_mocked:
                return real_unwrap(func, stop=_is_mocked)
            _stop = stop
            return real_unwrap(func, stop=lambda obj: _is_mocked(obj) or _stop(func))
        except Exception as e:
            warnings.warn(f"Got {e!r} when unwrapping {func!r}.  This is usually caused by a violation of Python's object protocol; see e.g. https://github.com/pytest-dev/pytest/issues/5080", PytestWarning)
            raise
    inspect.unwrap = _mock_aware_unwrap
    try:
        yield
    finally:
        inspect.unwrap = real_unwrap

