@abc.abstractmethod
def addfinalizer(self, finalizer: Callable[[], object]) -> None:
    """Add finalizer/teardown function to be called without arguments after
        the last test within the requesting test context finished execution."""
    raise NotImplementedError()

def execute(self, request: SubRequest) -> FixtureValue:
    """Return the value of this fixture, executing it if not cached."""
    requested_fixtures_that_should_finalize_us = []
    for argname in self.argnames:
        fixturedef = request._get_active_fixturedef(argname)
        requested_fixtures_that_should_finalize_us.append(fixturedef)
    if self.cached_result is not None:
        request_cache_key = self.cache_key(request)
        cache_key = self.cached_result[1]
        try:
            cache_hit = bool(request_cache_key == cache_key)
        except (ValueError, RuntimeError):
            cache_hit = request_cache_key is cache_key
        if cache_hit:
            if self.cached_result[2] is not None:
                exc, exc_tb = self.cached_result[2]
                raise exc.with_traceback(exc_tb)
            else:
                return self.cached_result[0]
        self.finish(request)
        assert self.cached_result is None
    finalizer = functools.partial(self.finish, request=request)
    for parent_fixture in requested_fixtures_that_should_finalize_us:
        parent_fixture.addfinalizer(finalizer)
    assert not self._finalizers
    self.addfinalizer(lambda: request.node.ihook.pytest_fixture_post_finalizer(fixturedef=self, request=request))
    ihook = request.node.ihook
    try:
        result: FixtureValue = ihook.pytest_fixture_setup(fixturedef=self, request=request)
    finally:
        request.node.addfinalizer(finalizer)
    return result

