def _finalize(self) -> None:
    """Finalize the fixture.

        This restores the log levels and the disabled logging levels changed by :meth:`set_level`.
        """
    if self._initial_handler_level is not None:
        self.handler.setLevel(self._initial_handler_level)
    for logger_name, level in self._initial_logger_levels.items():
        logger = logging.getLogger(logger_name)
        logger.setLevel(level)
    if self._initial_disabled_logging_level is not None:
        logging.disable(self._initial_disabled_logging_level)
        self._initial_disabled_logging_level = None

def clear(self) -> None:
    """Reset the list of log records and the captured log text."""
    self.handler.clear()

def reset(self) -> None:
    """Reset the handler; should be called before the start of each test."""
    self._first_record_emitted = False

def _main(config: Config, session: Session) -> int | ExitCode | None:
    """Default command line protocol for initialization, session,
    running tests and reporting."""
    config.hook.pytest_collection(session=session)
    config.hook.pytest_runtestloop(session=session)
    if session.testsfailed:
        return ExitCode.TESTS_FAILED
    elif session.testscollected == 0:
        return ExitCode.NO_TESTS_COLLECTED
    return None

def _in_venv(path: Path) -> bool:
    """Attempt to detect if ``path`` is the root of a Virtual Environment by
    checking for the existence of the pyvenv.cfg file.

    [https://peps.python.org/pep-0405/]

    For regression protection we also check for conda environments that do not include pyenv.cfg yet --
    https://github.com/conda/conda/issues/13337 is the conda issue tracking adding pyenv.cfg.

    Checking for the `conda-meta/history` file per https://github.com/pytest-dev/pytest/issues/12652#issuecomment-2246336902.

    """
    try:
        return path.joinpath('pyvenv.cfg').is_file() or path.joinpath('conda-meta', 'history').is_file()
    except OSError:
        return False

def search_pypath(module_name: str, *, consider_namespace_packages: bool=False) -> str | None:
    """Search sys.path for the given a dotted module name, and return its file
    system path if found."""
    try:
        spec = importlib.util.find_spec(module_name)
    except (AttributeError, ImportError, ValueError):
        return None
    if spec is None:
        return None
    if spec.submodule_search_locations is None or len(spec.submodule_search_locations) == 0:
        return spec.origin
    if consider_namespace_packages:
        return spec.submodule_search_locations[0]
    if spec.origin is None:
        return None
    return os.path.dirname(spec.origin)

@classmethod
def from_parent(cls, parent: nodes.Collector, *, path: Path) -> Self:
    """The public constructor.

        :param parent: The parent collector of this Dir.
        :param path: The directory's path.
        :type path: pathlib.Path
        """
    return super().from_parent(parent=parent, path=path)

@property
def startpath(self) -> Path:
    """The path from which pytest was invoked.

        .. versionadded:: 7.0.0
        """
    return self.config.invocation_params.dir

def delattr(self, target: object | str, name: str | NotSetType=NOTSET, raising: bool=True) -> None:
    """Delete attribute ``name`` from ``target``.

        If no ``name`` is specified and ``target`` is a string
        it will be interpreted as a dotted import path with the
        last part being the attribute name.

        Raises AttributeError it the attribute does not exist, unless
        ``raising`` is set to False.
        """
    __tracebackhide__ = True
    import inspect
    if name is NOTSET:
        if not isinstance(target, str):
            raise TypeError('use delattr(target, name) or delattr(target) with target being a dotted import string')
        name, target = derive_importpath(target, raising)
    if not hasattr(target, name):
        if raising:
            raise AttributeError(name)
    else:
        oldval = getattr(target, name, NOTSET)
        if inspect.isclass(target):
            oldval = target.__dict__.get(name, NOTSET)
        self._setattr.append((target, name, oldval))
        delattr(target, name)

def delitem(self, dic: Mapping[K, V], name: K, raising: bool=True) -> None:
    """Delete ``name`` from dict.

        Raises ``KeyError`` if it doesn't exist, unless ``raising`` is set to
        False.
        """
    if name not in dic:
        if raising:
            raise KeyError(name)
    else:
        self._setitem.append((dic, name, dic.get(name, NOTSET)))
        del dic[name]

def undo(self) -> None:
    """Undo previous changes.

        This call consumes the undo stack. Calling it a second time has no
        effect unless you do more monkeypatching after the undo call.

        There is generally no need to call `undo()`, since it is
        called automatically during tear-down.

        .. note::
            The same `monkeypatch` fixture is used across a
            single test function invocation. If `monkeypatch` is used both by
            the test function itself and one of the test fixtures,
            calling `undo()` will undo all of the changes made in
            both functions.

            Prefer to use :meth:`context() <pytest.MonkeyPatch.context>` instead.
        """
    for obj, name, value in reversed(self._setattr):
        if value is not NOTSET:
            setattr(obj, name, value)
        else:
            delattr(obj, name)
    self._setattr[:] = []
    for dictionary, key, value in reversed(self._setitem):
        if value is NOTSET:
            try:
                del dictionary[key]
            except KeyError:
                pass
        else:
            dictionary[key] = value
    self._setitem[:] = []
    if self._savesyspath is not None:
        sys.path[:] = self._savesyspath
        self._savesyspath = None
    if self._cwd is not None:
        os.chdir(self._cwd)
        self._cwd = None

def get_fslocation_from_item(node: Node) -> tuple[str | Path, int | None]:
    """Try to extract the actual location from a node, depending on available attributes:

    * "location": a pair (path, lineno)
    * "obj": a Python object that the node wraps.
    * "path": just a path

    :rtype: A tuple of (str|Path, int) with filename and 0-based line number.
    """
    location: tuple[str, int | None, str] | None = getattr(node, 'location', None)
    if location is not None:
        return location[:2]
    obj = getattr(node, 'obj', None)
    if obj is not None:
        return getfslineno(obj)
    return (getattr(node, 'path', 'unknown location'), -1)

@classmethod
def from_parent(cls, parent: Node, **kw) -> Self:
    """Public constructor for Nodes.

        This indirection got introduced in order to enable removing
        the fragile logic from the node constructors.

        Subclasses can use ``super().from_parent(...)`` when overriding the
        construction.

        :param parent: The parent node of this Node.
        """
    if 'config' in kw:
        raise TypeError('config is not a valid argument for from_parent')
    if 'session' in kw:
        raise TypeError('session is not a valid argument for from_parent')
    return cls._create(parent=parent, **kw)

def add_marker(self, marker: str | MarkDecorator, append: bool=True) -> None:
    """Dynamically add a marker object to the node.

        :param marker:
            The marker.
        :param append:
            Whether to append the marker, or prepend it.
        """
    from _pytest.mark import MARK_GEN
    if isinstance(marker, MarkDecorator):
        marker_ = marker
    elif isinstance(marker, str):
        marker_ = getattr(MARK_GEN, marker)
    else:
        raise ValueError('is not a string or pytest.mark.* Marker')
    self.keywords[marker_.name] = marker_
    if append:
        self.own_markers.append(marker_.mark)
    else:
        self.own_markers.insert(0, marker_.mark)

def iter_markers(self, name: str | None=None) -> Iterator[Mark]:
    """Iterate over all markers of the node.

        :param name: If given, filter the results by the name attribute.
        :returns: An iterator of the markers of the node.
        """
    return (x[1] for x in self.iter_markers_with_node(name=name))

def iter_markers_with_node(self, name: str | None=None) -> Iterator[tuple[Node, Mark]]:
    """Iterate over all markers of the node.

        :param name: If given, filter the results by the name attribute.
        :returns: An iterator of (node, mark) tuples.
        """
    for node in self.iter_parents():
        for mark in node.own_markers:
            if name is None or getattr(mark, 'name', None) == name:
                yield (node, mark)

def listextrakeywords(self) -> set[str]:
    """Return a set of all extra keywords in self and any parents."""
    extra_keywords: set[str] = set()
    for item in self.listchain():
        extra_keywords.update(item.extra_keyword_matches)
    return extra_keywords

def getparent(self, cls: type[_NodeType]) -> _NodeType | None:
    """Get the closest parent node (including self) which is an instance of
        the given class.

        :param cls: The node class to search for.
        :returns: The node, if found.
        """
    for node in self.iter_parents():
        if isinstance(node, cls):
            return node
    return None

def repr_failure(self, excinfo: ExceptionInfo[BaseException], style: TracebackStyle | None=None) -> str | TerminalRepr:
    """Return a representation of a collection or test failure.

        .. seealso:: :ref:`non-python tests`

        :param excinfo: Exception information for the failure.
        """
    return self._repr_failure_py(excinfo, style)

def repr_failure(self, excinfo: ExceptionInfo[BaseException]) -> str | TerminalRepr:
    """Return a representation of a collection failure.

        :param excinfo: Exception information for the failure.
        """
    if isinstance(excinfo.value, self.CollectError) and (not self.config.getoption('fulltrace', False)):
        exc = excinfo.value
        return str(exc.args[0])
    tbstyle = self.config.getoption('tbstyle', 'auto')
    if tbstyle == 'auto':
        tbstyle = 'short'
    return self._repr_failure_py(excinfo, style=tbstyle)

def create_new_paste(contents: str | bytes) -> str:
    """Create a new paste using the bpaste.net service.

    :contents: Paste contents string.
    :returns: URL to the pasted contents, or an error message.
    """
    import re
    from urllib.error import HTTPError
    from urllib.parse import urlencode
    from urllib.request import urlopen
    params = {'code': contents, 'lexer': 'text', 'expiry': '1week'}
    url = 'https://bpa.st'
    try:
        response: str = urlopen(url, data=urlencode(params).encode('ascii')).read().decode('utf-8')
    except HTTPError as e:
        with e:
            return f'bad response: {e}'
    except OSError as e:
        return f'bad response: {e}'
    m = re.search('href="/raw/(\\w+)"', response)
    if m:
        return f'{url}/show/{m.group(1)}'
    else:
        return "bad response: invalid format ('" + response + "')"

def on_rm_rf_error(func: Callable[..., Any] | None, path: str, excinfo: BaseException | tuple[type[BaseException], BaseException, types.TracebackType | None], *, start_path: Path) -> bool:
    """Handle known read-only errors during rmtree.

    The returned value is used only by our own tests.
    """
    if isinstance(excinfo, BaseException):
        exc = excinfo
    else:
        exc = excinfo[1]
    if isinstance(exc, FileNotFoundError):
        return False
    if not isinstance(exc, PermissionError):
        warnings.warn(PytestWarning(f'(rm_rf) error removing {path}\n{type(exc)}: {exc}'))
        return False
    p = Path(path)
    if func in (os.open, os.scandir):
        parent_changed = False
        parent = p.parent
        if parent not in (p, start_path):
            parent_changed = _chmod_rwx(str(parent))
        path_changed = _chmod_rwx(str(p))
        if not (parent_changed or path_changed):
            return False
        if p.is_dir():
            rm_rf(p)
        else:
            try:
                os.unlink(str(p))
            except OSError:
                return False
        return True
    if func not in (os.rmdir, os.remove, os.unlink):
        warnings.warn(PytestWarning(f'(rm_rf) unknown function {func} when removing {path}:\n{type(exc)}: {exc}'))
        return False
    if p.is_file():
        for parent in p.parents:
            _chmod_rwx(str(parent))
            if parent == start_path:
                break
    _chmod_rwx(str(path))
    func(path)
    return True

def rm_rf(path: Path) -> None:
    """Remove the path contents recursively, even if some elements
    are read-only."""
    path = ensure_extended_length_path(path)
    onerror = partial(on_rm_rf_error, start_path=path)
    if sys.version_info >= (3, 12):
        shutil.rmtree(str(path), onexc=onerror)
    else:
        shutil.rmtree(str(path), onerror=onerror)

def find_prefixed(root: Path, prefix: str) -> Iterator[os.DirEntry[str]]:
    """Find all elements in root that begin with the prefix, case-insensitive."""
    l_prefix = prefix.lower()
    for x in os.scandir(root):
        if x.name.lower().startswith(l_prefix):
            yield x

def _force_symlink(root: Path, target: str | PurePath, link_to: str | Path) -> None:
    """Helper to create the current symlink.

    It's full of race conditions that are reasonably OK to ignore
    for the context of best effort linking to the latest test run.

    The presumption being that in case of much parallelism
    the inaccuracy is going to be acceptable.
    """
    current_symlink = root.joinpath(target)
    try:
        current_symlink.unlink()
    except OSError:
        pass
    try:
        current_symlink.symlink_to(link_to)
    except Exception:
        pass

def make_numbered_dir(root: Path, prefix: str, mode: int=448) -> Path:
    """Create a directory with an increased number as suffix for the given prefix."""
    for i in range(10):
        max_existing = max(map(parse_num, find_suffixes(root, prefix)), default=-1)
        new_number = max_existing + 1
        new_path = root.joinpath(f'{prefix}{new_number}')
        try:
            new_path.mkdir(mode=mode)
        except Exception:
            pass
        else:
            _force_symlink(root, prefix + 'current', new_path)
            return new_path
    else:
        raise OSError(f'could not create numbered dir with prefix {prefix} in {root} after 10 tries')

def maybe_delete_a_numbered_dir(path: Path) -> None:
    """Remove a numbered directory if its lock can be obtained and it does
    not seem to be in use."""
    path = ensure_extended_length_path(path)
    lock_path = None
    try:
        lock_path = create_cleanup_lock(path)
        parent = path.parent
        garbage = parent.joinpath(f'garbage-{uuid.uuid4()}')
        path.rename(garbage)
        rm_rf(garbage)
    except OSError:
        return
    finally:
        if lock_path is not None:
            try:
                lock_path.unlink()
            except OSError:
                pass

def ensure_deletable(path: Path, consider_lock_dead_if_created_before: float) -> bool:
    """Check if `path` is deletable based on whether the lock file is expired."""
    if path.is_symlink():
        return False
    lock = get_lock_path(path)
    try:
        if not lock.is_file():
            return True
    except OSError:
        return False
    try:
        lock_time = lock.stat().st_mtime
    except Exception:
        return False
    else:
        if lock_time < consider_lock_dead_if_created_before:
            with contextlib.suppress(OSError):
                lock.unlink()
                return True
        return False

def try_cleanup(path: Path, consider_lock_dead_if_created_before: float) -> None:
    """Try to cleanup a directory if we can ensure it's deletable."""
    if ensure_deletable(path, consider_lock_dead_if_created_before):
        maybe_delete_a_numbered_dir(path)

def cleanup_candidates(root: Path, prefix: str, keep: int) -> Iterator[Path]:
    """List candidates for numbered directories to be removed - follows py.path."""
    max_existing = max(map(parse_num, find_suffixes(root, prefix)), default=-1)
    max_delete = max_existing - keep
    entries = find_prefixed(root, prefix)
    entries, entries2 = itertools.tee(entries)
    numbers = map(parse_num, extract_suffixes(entries2, prefix))
    for entry, number in zip(entries, numbers, strict=True):
        if number <= max_delete:
            yield Path(entry)

def symlink_or_skip(src: os.PathLike[str] | str, dst: os.PathLike[str] | str, **kwargs: Any) -> None:
    """Make a symlink, or skip the test in case symlinks are not supported."""
    try:
        os.symlink(src, dst, **kwargs)
    except OSError as e:
        skip(f'symlinks not supported: {e}')

def spec_matches_module_path(module_spec: ModuleSpec | None, module_path: Path) -> bool:
    """Return true if the given ModuleSpec can be used to import the given module path."""
    if module_spec is None:
        return False
    if module_spec.origin:
        return Path(module_spec.origin) == module_path
    if module_spec.submodule_search_locations:
        for path in module_spec.submodule_search_locations:
            if Path(path) == module_path:
                return True
    return False

def module_name_from_path(path: Path, root: Path) -> str:
    """
    Return a dotted module name based on the given path, anchored on root.

    For example: path="projects/src/tests/test_foo.py" and root="/projects", the
    resulting module name will be "src.tests.test_foo".
    """
    path = path.with_suffix('')
    try:
        relative_path = path.relative_to(root)
    except ValueError:
        path_parts = path.parts[1:]
    else:
        path_parts = relative_path.parts
    if len(path_parts) >= 2 and path_parts[-1] == '__init__':
        path_parts = path_parts[:-1]
    path_parts = tuple((x.replace('.', '_') for x in path_parts))
    return '.'.join(path_parts)

def insert_missing_modules(modules: dict[str, ModuleType], module_name: str) -> None:
    """
    Used by ``import_path`` to create intermediate modules when using mode=importlib.

    When we want to import a module as "src.tests.test_foo" for example, we need
    to create empty modules "src" and "src.tests" after inserting "src.tests.test_foo",
    otherwise "src.tests.test_foo" is not importable by ``__import__``.
    """
    module_parts = module_name.split('.')
    while module_name:
        parent_module_name, _, child_name = module_name.rpartition('.')
        if parent_module_name:
            parent_module = modules.get(parent_module_name)
            if parent_module is None:
                try:
                    if not sys.meta_path:
                        raise ModuleNotFoundError
                    parent_module = importlib.import_module(parent_module_name)
                except ModuleNotFoundError:
                    parent_module = ModuleType(module_name, doc="Empty module created by pytest's importmode=importlib.")
                modules[parent_module_name] = parent_module
            if not hasattr(parent_module, child_name):
                setattr(parent_module, child_name, modules[module_name])
        module_parts.pop(-1)
        module_name = '.'.join(module_parts)

def resolve_package_path(path: Path) -> Path | None:
    """Return the Python package path by looking for the last
    directory upwards which still contains an __init__.py.

    Returns None if it cannot be determined.
    """
    result = None
    for parent in itertools.chain((path,), path.parents):
        if parent.is_dir():
            if not (parent / '__init__.py').is_file():
                break
            if not parent.name.isidentifier():
                break
            result = parent
    return result

def compute_module_name(root: Path, module_path: Path) -> str | None:
    """Compute a module name based on a path and a root anchor."""
    try:
        path_without_suffix = module_path.with_suffix('')
    except ValueError:
        return None
    try:
        relative = path_without_suffix.relative_to(root)
    except ValueError:
        return None
    names = list(relative.parts)
    if not names:
        return None
    if names[-1] == '__init__':
        names.pop()
    return '.'.join(names)

def scandir(path: str | os.PathLike[str], sort_key: Callable[[os.DirEntry[str]], object]=lambda entry: entry.name) -> list[os.DirEntry[str]]:
    """Scan a directory recursively, in breadth-first order.

    The returned entries are sorted according to the given key.
    The default is to sort by name.
    If the directory does not exist, return an empty list.
    """
    entries = []
    try:
        scandir_iter = os.scandir(path)
    except FileNotFoundError:
        return []
    with scandir_iter as s:
        for entry in s:
            try:
                entry.is_file()
            except OSError as err:
                if _ignore_error(err):
                    continue
                raise
            entries.append(entry)
    entries.sort(key=sort_key)
    return entries

def visit(path: str | os.PathLike[str], recurse: Callable[[os.DirEntry[str]], bool]) -> Iterator[os.DirEntry[str]]:
    """Walk a directory recursively, in breadth-first order.

    The `recurse` predicate determines whether a directory is recursed.

    Entries at each directory level are sorted.
    """
    entries = scandir(path)
    yield from entries
    for entry in entries:
        if entry.is_dir() and recurse(entry):
            yield from visit(entry.path, recurse)

def absolutepath(path: str | os.PathLike[str]) -> Path:
    """Convert a path to an absolute path using os.path.abspath.

    Prefer this over Path.resolve() (see #6523).
    Prefer this over Path.absolute() (not public, doesn't normalize).
    """
    return Path(os.path.abspath(path))

def commonpath(path1: Path, path2: Path) -> Path | None:
    """Return the common part shared with the other path, or None if there is
    no common part.

    If one path is relative and one is absolute, returns None.
    """
    try:
        return Path(os.path.commonpath((str(path1), str(path2))))
    except ValueError:
        return None

def bestrelpath(directory: Path, dest: Path) -> str:
    """Return a string which is a relative path from directory to dest such
    that directory/bestrelpath == dest.

    The paths must be either both absolute or both relative.

    If no such path can be determined, returns dest.
    """
    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    base = commonpath(directory, dest)
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(*[os.pardir] * len(reldirectory.parts), *reldest.parts)

def safe_exists(p: Path) -> bool:
    """Like Path.exists(), but account for input arguments that might be too long (#11394)."""
    try:
        return p.exists()
    except (ValueError, OSError):
        return False

def samefile_nofollow(p1: Path, p2: Path) -> bool:
    """Test whether two paths reference the same actual file or directory.

    Unlike Path.samefile(), does not resolve symlinks.
    """
    return os.path.samestat(p1.lstat(), p2.lstat())

