def copy_example(self, name: str | None=None) -> Path:
    """Copy file from project's directory into the testdir.

        :param name:
            The name of the file to copy.
        :return:
            Path to the copied directory (inside ``self.path``).
        :rtype: pathlib.Path
        """
    example_dir_ = self._request.config.getini('pytester_example_dir')
    if example_dir_ is None:
        raise ValueError("pytester_example_dir is unset, can't copy examples")
    example_dir: Path = self._request.config.rootpath / example_dir_
    for extra_element in self._request.node.iter_markers('pytester_example_path'):
        assert extra_element.args
        example_dir = example_dir.joinpath(*extra_element.args)
    if name is None:
        func_name = self._name
        maybe_dir = example_dir / func_name
        maybe_file = example_dir / (func_name + '.py')
        if maybe_dir.is_dir():
            example_path = maybe_dir
        elif maybe_file.is_file():
            example_path = maybe_file
        else:
            raise LookupError(f"{func_name} can't be found as module or package in {example_dir}")
    else:
        example_path = example_dir.joinpath(name)
    if example_path.is_dir() and (not example_path.joinpath('__init__.py').is_file()):
        shutil.copytree(example_path, self.path, symlinks=True, dirs_exist_ok=True)
        return self.path
    elif example_path.is_file():
        result = self.path.joinpath(example_path.name)
        shutil.copy(example_path, result)
        return result
    else:
        raise LookupError(f'example "{example_path}" is not found as a file or directory')

def runpytest_inprocess(self, *args: str | os.PathLike[str], **kwargs: Any) -> RunResult:
    """Return result of running pytest in-process, providing a similar
        interface to what self.runpytest() provides."""
    syspathinsert = kwargs.pop('syspathinsert', False)
    if syspathinsert:
        self.syspathinsert()
    instant = timing.Instant()
    capture = _get_multicapture('sys')
    capture.start_capturing()
    try:
        try:
            reprec = self.inline_run(*args, **kwargs)
        except SystemExit as e:
            ret = e.args[0]
            try:
                ret = ExitCode(e.args[0])
            except ValueError:
                pass

            class reprec:
                ret = ret
        except Exception:
            traceback.print_exc()

            class reprec:
                ret = ExitCode(3)
    finally:
        out, err = capture.readouterr()
        capture.stop_capturing()
        sys.stdout.write(out)
        sys.stderr.write(err)
    assert reprec.ret is not None
    res = RunResult(reprec.ret, out.splitlines(), err.splitlines(), instant.elapsed().seconds)
    res.reprec = reprec
    return res

def runpytest(self, *args: str | os.PathLike[str], **kwargs: Any) -> RunResult:
    """Run pytest inline or in a subprocess, depending on the command line
        option "--runpytest" and return a :py:class:`~pytest.RunResult`."""
    new_args = self._ensure_basetemp(args)
    if self._method == 'inprocess':
        return self.runpytest_inprocess(*new_args, **kwargs)
    elif self._method == 'subprocess':
        return self.runpytest_subprocess(*new_args, **kwargs)
    raise RuntimeError(f'Unrecognized runpytest option: {self._method}')

def collect_by_name(self, modcol: Collector, name: str) -> Item | Collector | None:
    """Return the collection node for name from the module collection.

        Searches a module collection node for a collection node matching the
        given name.

        :param modcol: A module collection node; see :py:meth:`getmodulecol`.
        :param name: The name of the node to return.
        """
    if modcol not in self._mod_collections:
        self._mod_collections[modcol] = list(modcol.collect())
    for colitem in self._mod_collections[modcol]:
        if colitem.name == name:
            return colitem
    return None

def __str__(self) -> str:
    """Return the entire original text.

        .. versionadded:: 6.2
            You can use :meth:`str` in older versions.
        """
    return '\n'.join(self.lines)

def get_lines_after(self, fnline: str) -> Sequence[str]:
    """Return all lines following the given line in the text.

        The given line can contain glob wildcards.
        """
    for i, line in enumerate(self.lines):
        if fnline == line or fnmatch(line, fnline):
            return self.lines[i + 1:]
    raise ValueError(f'line {fnline!r} not found in output')

def assert_outcomes(outcomes: dict[str, int], passed: int=0, skipped: int=0, failed: int=0, errors: int=0, xpassed: int=0, xfailed: int=0, warnings: int | None=None, deselected: int | None=None) -> None:
    """Assert that the specified outcomes appear with the respective
    numbers (0 means it didn't occur) in the text output from a test run."""
    __tracebackhide__ = True
    obtained = {'passed': outcomes.get('passed', 0), 'skipped': outcomes.get('skipped', 0), 'failed': outcomes.get('failed', 0), 'errors': outcomes.get('errors', 0), 'xpassed': outcomes.get('xpassed', 0), 'xfailed': outcomes.get('xfailed', 0)}
    expected = {'passed': passed, 'skipped': skipped, 'failed': failed, 'errors': errors, 'xpassed': xpassed, 'xfailed': xfailed}
    if warnings is not None:
        obtained['warnings'] = outcomes.get('warnings', 0)
        expected['warnings'] = warnings
    if deselected is not None:
        obtained['deselected'] = outcomes.get('deselected', 0)
        expected['deselected'] = deselected
    assert obtained == expected

def path_matches_patterns(path: Path, patterns: Iterable[str]) -> bool:
    """Return whether path matches any of the patterns in the list of globs given."""
    return any((fnmatch_ex(pattern, path) for pattern in patterns))

def _call_with_optional_argument(func, arg) -> None:
    """Call the given function with the given argument if func accepts one argument, otherwise
    calls func without arguments."""
    arg_count = func.__code__.co_argcount
    if inspect.ismethod(func):
        arg_count -= 1
    if arg_count:
        func(arg)
    else:
        func()

def _get_first_non_fixture_func(obj: object, names: Iterable[str]) -> object | None:
    """Return the attribute from the given object to be used as a setup/teardown
    xunit-style function, but only if not marked as a fixture to avoid calling it twice.
    """
    for name in names:
        meth: object | None = getattr(obj, name, None)
        if meth is not None and fixtures.getfixturemarker(meth) is None:
            return meth
    return None

def _infer_parametrize_scope(argnames: Sequence[str], arg2fixturedefs: Mapping[str, Sequence[fixtures.FixtureDef[object]]], indirect: bool | Sequence[str]) -> Scope:
    """Infer the most appropriate scope for a parametrize() call based on its
    arguments, for when the scope is not explicitly specified.

    When there's at least one direct argument, always use "function" scope.

    When a test function is parametrized and all its arguments are indirect
    (e.g. fixtures), return the most narrow scope based on the fixtures used.

    Related to issue #1832, based on code posted by @Kingdread.
    """
    if isinstance(indirect, Sequence):
        all_arguments_are_fixtures = len(indirect) == len(argnames)
    else:
        all_arguments_are_fixtures = bool(indirect)
    if all_arguments_are_fixtures:
        used_scopes = (arg2fixturedefs[argname][-1]._scope for argname in argnames if argname in arg2fixturedefs)
        return min(used_scopes, default=Scope.Function)
    return Scope.Function

@property
def module(self):
    """Python module object this node was collected from (can be None)."""
    node = self.getparent(Module)
    return node.obj if node is not None else None

@property
def cls(self):
    """Python class object this node was collected from (can be None)."""
    node = self.getparent(Class)
    return node.obj if node is not None else None

def _getobj(self):
    """Get the underlying Python object. May be overwritten by subclasses."""
    assert self.parent is not None
    obj = self.parent.obj
    return getattr(obj, self.name)

def isnosetest(self, obj: object) -> bool:
    """Look for the __test__ attribute, which is applied by the
        @nose.tools.istest decorator.
        """
    return safe_getattr(obj, '__test__', False) is True

def _matches_prefix_or_glob_option(self, option_name: str, name: str) -> bool:
    """Check if the given name matches the prefix or glob-pattern defined
        in configuration."""
    for option in self.config.getini(option_name):
        if name.startswith(option):
            return True
        elif ('*' in option or '?' in option or '[' in option) and fnmatch.fnmatch(name, option):
            return True
    return False

def _register_setup_class_fixture(self) -> None:
    """Register an autouse, class scoped fixture into the collected class object
        that invokes setup_class/teardown_class if either or both are available.

        Using a fixture to invoke this methods ensures we play nicely and unsurprisingly with
        other fixtures (#517).
        """
    setup_class = _get_first_non_fixture_func(self.obj, ('setup_class',))
    teardown_class = _get_first_non_fixture_func(self.obj, ('teardown_class',))
    if setup_class is None and teardown_class is None:
        return

    def xunit_setup_class_fixture(request) -> Generator[None]:
        cls = request.cls
        if setup_class is not None:
            func = getimfunc(setup_class)
            _call_with_optional_argument(func, cls)
        yield
        if teardown_class is not None:
            func = getimfunc(teardown_class)
            _call_with_optional_argument(func, cls)
    fixtures.register_fixture(name=f'_xunit_setup_class_fixture_{self.obj.__qualname__}', func=xunit_setup_class_fixture, node=self, scope='class', autouse=True)

def _register_setup_method_fixture(self) -> None:
    """Register an autouse, function scoped fixture into the collected class object
        that invokes setup_method/teardown_method if either or both are available.

        Using a fixture to invoke these methods ensures we play nicely and unsurprisingly with
        other fixtures (#517).
        """
    setup_name = 'setup_method'
    setup_method = _get_first_non_fixture_func(self.obj, (setup_name,))
    teardown_name = 'teardown_method'
    teardown_method = _get_first_non_fixture_func(self.obj, (teardown_name,))
    if setup_method is None and teardown_method is None:
        return

    def xunit_setup_method_fixture(request) -> Generator[None]:
        instance = request.instance
        method = request.function
        if setup_method is not None:
            func = getattr(instance, setup_name)
            _call_with_optional_argument(func, method)
        yield
        if teardown_method is not None:
            func = getattr(instance, teardown_name)
            _call_with_optional_argument(func, method)
    fixtures.register_fixture(name=f'_xunit_setup_method_fixture_{self.obj.__qualname__}', func=xunit_setup_method_fixture, node=self, scope='function', autouse=True)

def _idval_from_function(self, val: object, argname: str, idx: int) -> str | None:
    """Try to make an ID for a parameter in a ParameterSet using the
        user-provided id callable, if given."""
    if self.idfn is None:
        return None
    try:
        id = self.idfn(val)
    except Exception as e:
        prefix = f'{self.nodeid}: ' if self.nodeid is not None else ''
        msg = "error raised while trying to determine id of parameter '{}' at position {}"
        msg = prefix + msg.format(argname, idx)
        raise ValueError(msg) from e
    if id is None:
        return None
    return self._idval_from_value(id)

def _idval_from_value(self, val: object) -> str | None:
    """Try to make an ID for a parameter in a ParameterSet from its value,
        if the value type is supported."""
    if isinstance(val, str | bytes):
        return _ascii_escaped_by_config(val, self.config)
    elif val is None or isinstance(val, float | int | bool | complex):
        return str(val)
    elif isinstance(val, re.Pattern):
        return ascii_escaped(val.pattern)
    elif val is NOTSET:
        pass
    elif isinstance(val, enum.Enum):
        return str(val)
    elif isinstance(getattr(val, '__name__', None), str):
        name: str = getattr(val, '__name__')
        return name
    return None

@staticmethod
def _idval_from_argname(argname: str, idx: int) -> str:
    """Make an ID for a parameter in a ParameterSet from the argument name
        and the index of the ParameterSet."""
    return str(argname) + str(idx)

def _validate_if_using_arg_names(self, argnames: Sequence[str], indirect: bool | Sequence[str]) -> None:
    """Check if all argnames are being used, by default values, or directly/indirectly.

        :param List[str] argnames: List of argument names passed to ``parametrize()``.
        :param indirect: Same as the ``indirect`` parameter of ``parametrize()``.
        :raises ValueError: If validation fails.
        """
    default_arg_names = set(get_default_arg_names(self.function))
    nodeid = self.definition.nodeid
    for arg in argnames:
        if arg not in self.fixturenames:
            if arg in default_arg_names:
                fail(f"In {nodeid}: function already takes an argument '{arg}' with a default value", pytrace=False)
            else:
                if isinstance(indirect, Sequence):
                    name = 'fixture' if arg in indirect else 'argument'
                else:
                    name = 'fixture' if indirect else 'argument'
                fail(f"In {nodeid}: function uses no {name} '{arg}'", pytrace=False)

def _match_pattern(match: Pattern[str]) -> str | Pattern[str]:
    """Helper function to remove redundant `re.compile` calls when printing regex"""
    return match.pattern if match.flags == _REGEX_NO_FLAGS else match

def repr_callable(fun: Callable[[BaseExcT_1], bool]) -> str:
    """Get the repr of a ``check`` parameter.

    Split out so it can be monkeypatched (e.g. by hypothesis)
    """
    return repr(fun)

@property
def fail_reason(self) -> str | None:
    """Set after a call to :meth:`matches` to give a human-readable reason for why the match failed.
        When used as a context manager the string will be printed as the reason for the
        test failing."""
    return self._fail_reason

@abstractmethod
def matches(self: AbstractRaises[BaseExcT_1], exception: BaseException) -> TypeGuard[BaseExcT_1]:
    """Check if an exception matches the requirements of this AbstractRaises.
        If it fails, :meth:`AbstractRaises.fail_reason` should be set.
        """

@staticmethod
def _check_expected(expected_type: type[BaseException] | RaisesExc[BaseException] | RaisesGroup[BaseException], exception: BaseException) -> str | None:
    """Helper method for `RaisesGroup.matches` and `RaisesGroup._check_exceptions`
        to check one of potentially several expected exceptions."""
    if isinstance(expected_type, type):
        return _check_raw_type(expected_type, exception)
    res = expected_type.matches(exception)
    if res:
        return None
    assert expected_type.fail_reason is not None
    if expected_type.fail_reason.startswith('\n'):
        return f"\n{expected_type!r}: {indent(expected_type.fail_reason, '  ')}"
    return f'{expected_type!r}: {expected_type.fail_reason}'

@staticmethod
def _repr_expected(e: type[BaseException] | AbstractRaises[BaseException]) -> str:
    """Get the repr of an expected type/RaisesExc/RaisesGroup, but we only want
        the name if it's a type"""
    if isinstance(e, type):
        return _exception_type_name(e)
    return repr(e)

def _check_exceptions(self, _exception: BaseException, actual_exceptions: Sequence[BaseException]) -> bool:
    """Helper method for RaisesGroup.matches that attempts to pair up expected and actual exceptions"""
    results = ResultHolder(self.expected_exceptions, actual_exceptions)
    remaining_actual = list(range(len(actual_exceptions)))
    failed_expected: list[int] = []
    matches: dict[int, int] = {}
    for i_exp, expected in enumerate(self.expected_exceptions):
        for i_rem in remaining_actual:
            res = self._check_expected(expected, actual_exceptions[i_rem])
            results.set_result(i_exp, i_rem, res)
            if res is None:
                remaining_actual.remove(i_rem)
                matches[i_exp] = i_rem
                break
        else:
            failed_expected.append(i_exp)
    if not remaining_actual and (not failed_expected):
        return True
    if 1 == len(actual_exceptions) == len(self.expected_exceptions):
        assert not matches
        self._fail_reason = res
        return False
    for i_exp, expected in enumerate(self.expected_exceptions):
        for i_actual, actual in enumerate(actual_exceptions):
            if results.has_result(i_exp, i_actual):
                continue
            results.set_result(i_exp, i_actual, self._check_expected(expected, actual))
    successful_str = f"{len(matches)} matched exception{('s' if len(matches) > 1 else '')}. " if matches else ''
    if not failed_expected and results.no_match_for_actual(remaining_actual):
        self._fail_reason = f'{successful_str}Unexpected exception(s): {[actual_exceptions[i] for i in remaining_actual]!r}'
        return False
    if not remaining_actual and results.no_match_for_expected(failed_expected):
        no_match_for_str = ', '.join((self._repr_expected(self.expected_exceptions[i]) for i in failed_expected))
        self._fail_reason = f'{successful_str}Too few exceptions raised, found no match for: [{no_match_for_str}]'
        return False
    if 1 == len(remaining_actual) == len(failed_expected) and results.no_match_for_actual(remaining_actual) and results.no_match_for_expected(failed_expected):
        self._fail_reason = f'{successful_str}{results.get_result(failed_expected[0], remaining_actual[0])}'
        return False
    s = ''
    if matches:
        s += f'\n{successful_str}'
    indent_1 = ' ' * 2
    indent_2 = ' ' * 4
    if not remaining_actual:
        s += '\nToo few exceptions raised!'
    elif not failed_expected:
        s += '\nUnexpected exception(s)!'
    if failed_expected:
        s += '\nThe following expected exceptions did not find a match:'
        rev_matches = {v: k for k, v in matches.items()}
    for i_failed in failed_expected:
        s += f'\n{indent_1}{self._repr_expected(self.expected_exceptions[i_failed])}'
        for i_actual, actual in enumerate(actual_exceptions):
            if results.get_result(i_failed, i_actual) is None:
                s += f'\n{indent_2}It matches {backquote(repr(actual))} which was paired with ' + backquote(self._repr_expected(self.expected_exceptions[rev_matches[i_actual]]))
    if remaining_actual:
        s += '\nThe following raised exceptions did not find a match'
    for i_actual in remaining_actual:
        s += f'\n{indent_1}{actual_exceptions[i_actual]!r}:'
        for i_exp, expected in enumerate(self.expected_exceptions):
            res = results.get_result(i_exp, i_actual)
            if i_exp in failed_expected:
                assert res is not None
                if res[0] != '\n':
                    s += '\n'
                s += indent(res, indent_2)
            if res is None:
                s += f'\n{indent_2}It matches {backquote(self._repr_expected(expected))} which was paired with {backquote(repr(actual_exceptions[matches[i_exp]]))}'
    if len(self.expected_exceptions) == len(actual_exceptions) and possible_match(results):
        s += '\nThere exist a possible match when attempting an exhaustive check, but RaisesGroup uses a greedy algorithm. Please make your expected exceptions more stringent with `RaisesExc` etc so the greedy algorithm can function.'
    self._fail_reason = s
    return False

def pop(self, cls: type[Warning]=Warning) -> warnings.WarningMessage:
    """Pop the first recorded warning which is an instance of ``cls``,
        but not an instance of a child class of any other match.
        Raises ``AssertionError`` if there is no match.
        """
    best_idx: int | None = None
    for i, w in enumerate(self._list):
        if w.category == cls:
            return self._list.pop(i)
        if issubclass(w.category, cls) and (best_idx is None or not issubclass(w.category, self._list[best_idx].category)):
            best_idx = i
    if best_idx is not None:
        return self._list.pop(best_idx)
    __tracebackhide__ = True
    raise AssertionError(f'{cls!r} not found in warning list')

def _report_to_json(report: BaseReport) -> dict[str, Any]:
    """Return the contents of this report as a dict of builtin entries,
    suitable for serialization.

    This was originally the serialize_report() function from xdist (ca03269).
    """

    def serialize_repr_entry(entry: ReprEntry | ReprEntryNative) -> dict[str, Any]:
        data = dataclasses.asdict(entry)
        for key, value in data.items():
            if hasattr(value, '__dict__'):
                data[key] = dataclasses.asdict(value)
        entry_data = {'type': type(entry).__name__, 'data': data}
        return entry_data

    def serialize_repr_traceback(reprtraceback: ReprTraceback) -> dict[str, Any]:
        result = dataclasses.asdict(reprtraceback)
        result['reprentries'] = [serialize_repr_entry(x) for x in reprtraceback.reprentries]
        return result

    def serialize_repr_crash(reprcrash: ReprFileLocation | None) -> dict[str, Any] | None:
        if reprcrash is not None:
            return dataclasses.asdict(reprcrash)
        else:
            return None

    def serialize_exception_longrepr(rep: BaseReport) -> dict[str, Any]:
        assert rep.longrepr is not None
        longrepr = cast(ExceptionRepr, rep.longrepr)
        result: dict[str, Any] = {'reprcrash': serialize_repr_crash(longrepr.reprcrash), 'reprtraceback': serialize_repr_traceback(longrepr.reprtraceback), 'sections': longrepr.sections}
        if isinstance(longrepr, ExceptionChainRepr):
            result['chain'] = []
            for repr_traceback, repr_crash, description in longrepr.chain:
                result['chain'].append((serialize_repr_traceback(repr_traceback), serialize_repr_crash(repr_crash), description))
        else:
            result['chain'] = None
        return result
    d = report.__dict__.copy()
    if hasattr(report.longrepr, 'toterminal'):
        if hasattr(report.longrepr, 'reprtraceback') and hasattr(report.longrepr, 'reprcrash'):
            d['longrepr'] = serialize_exception_longrepr(report)
        else:
            d['longrepr'] = str(report.longrepr)
    else:
        d['longrepr'] = report.longrepr
    for name in d:
        if isinstance(d[name], os.PathLike):
            d[name] = os.fspath(d[name])
        elif name == 'result':
            d[name] = None
    return d

def _report_kwargs_from_json(reportdict: dict[str, Any]) -> dict[str, Any]:
    """Return **kwargs that can be used to construct a TestReport or
    CollectReport instance.

    This was originally the serialize_report() function from xdist (ca03269).
    """

    def deserialize_repr_entry(entry_data):
        data = entry_data['data']
        entry_type = entry_data['type']
        if entry_type == 'ReprEntry':
            reprfuncargs = None
            reprfileloc = None
            reprlocals = None
            if data['reprfuncargs']:
                reprfuncargs = ReprFuncArgs(**data['reprfuncargs'])
            if data['reprfileloc']:
                reprfileloc = ReprFileLocation(**data['reprfileloc'])
            if data['reprlocals']:
                reprlocals = ReprLocals(data['reprlocals']['lines'])
            reprentry: ReprEntry | ReprEntryNative = ReprEntry(lines=data['lines'], reprfuncargs=reprfuncargs, reprlocals=reprlocals, reprfileloc=reprfileloc, style=data['style'])
        elif entry_type == 'ReprEntryNative':
            reprentry = ReprEntryNative(data['lines'])
        else:
            _report_unserialization_failure(entry_type, TestReport, reportdict)
        return reprentry

    def deserialize_repr_traceback(repr_traceback_dict):
        repr_traceback_dict['reprentries'] = [deserialize_repr_entry(x) for x in repr_traceback_dict['reprentries']]
        return ReprTraceback(**repr_traceback_dict)

    def deserialize_repr_crash(repr_crash_dict: dict[str, Any] | None):
        if repr_crash_dict is not None:
            return ReprFileLocation(**repr_crash_dict)
        else:
            return None
    if reportdict['longrepr'] and 'reprcrash' in reportdict['longrepr'] and ('reprtraceback' in reportdict['longrepr']):
        reprtraceback = deserialize_repr_traceback(reportdict['longrepr']['reprtraceback'])
        reprcrash = deserialize_repr_crash(reportdict['longrepr']['reprcrash'])
        if reportdict['longrepr']['chain']:
            chain = []
            for repr_traceback_data, repr_crash_data, description in reportdict['longrepr']['chain']:
                chain.append((deserialize_repr_traceback(repr_traceback_data), deserialize_repr_crash(repr_crash_data), description))
            exception_info: ExceptionChainRepr | ReprExceptionInfo = ExceptionChainRepr(chain)
        else:
            exception_info = ReprExceptionInfo(reprtraceback=reprtraceback, reprcrash=reprcrash)
        for section in reportdict['longrepr']['sections']:
            exception_info.addsection(*section)
        reportdict['longrepr'] = exception_info
    return reportdict

@property
def caplog(self) -> str:
    """Return captured log lines, if log capturing is enabled.

        .. versionadded:: 3.5
        """
    return '\n'.join((content for prefix, content in self.get_sections('Captured log')))

@property
def capstdout(self) -> str:
    """Return captured text from stdout, if capturing is enabled.

        .. versionadded:: 3.0
        """
    return ''.join((content for prefix, content in self.get_sections('Captured stdout')))

@property
def capstderr(self) -> str:
    """Return captured text from stderr, if capturing is enabled.

        .. versionadded:: 3.0
        """
    return ''.join((content for prefix, content in self.get_sections('Captured stderr')))

@property
def fspath(self) -> str:
    """The path portion of the reported node, as a string."""
    return self.nodeid.split('::')[0]

@classmethod
def _from_json(cls, reportdict: dict[str, object]) -> Self:
    """Create either a TestReport or CollectReport, depending on the calling class.

        It is the callers responsibility to know which class to pass here.

        This was originally the serialize_report() function from xdist (ca03269).

        Experimental method.
        """
    kwargs = _report_kwargs_from_json(reportdict)
    return cls(**kwargs)

@classmethod
def from_item_and_call(cls, item: Item, call: CallInfo[None]) -> TestReport:
    """Create and fill a TestReport with standard item and call info.

        :param item: The item.
        :param call: The call info.
        """
    when = call.when
    assert when != 'collect'
    duration = call.duration
    start = call.start
    stop = call.stop
    keywords = {x: 1 for x in item.keywords}
    excinfo = call.excinfo
    sections = []
    if not call.excinfo:
        outcome: Literal['passed', 'failed', 'skipped'] = 'passed'
        longrepr: None | ExceptionInfo[BaseException] | tuple[str, int, str] | str | TerminalRepr = None
    elif not isinstance(excinfo, ExceptionInfo):
        outcome = 'failed'
        longrepr = excinfo
    elif isinstance(excinfo.value, skip.Exception):
        outcome = 'skipped'
        r = excinfo._getreprcrash()
        assert r is not None, 'There should always be a traceback entry for skipping a test.'
        if excinfo.value._use_item_location:
            path, line = item.reportinfo()[:2]
            assert line is not None
            longrepr = (os.fspath(path), line + 1, r.message)
        else:
            longrepr = (str(r.path), r.lineno, r.message)
    elif isinstance(excinfo.value, BaseExceptionGroup) and excinfo.value.split(skip.Exception)[1] is None:
        outcome = 'skipped'
        excinfo = cast(ExceptionInfo[BaseExceptionGroup[BaseException | BaseExceptionGroup]], excinfo)
        longrepr = _format_exception_group_all_skipped_longrepr(item, excinfo)
    else:
        outcome = 'failed'
        longrepr = _format_failed_longrepr(item, call, excinfo)
    for rwhen, key, content in item._report_sections:
        sections.append((f'Captured {key} {rwhen}', content))
    return cls(item.nodeid, item.location, keywords, outcome, longrepr, when, sections, duration, start, stop, user_properties=item.user_properties)

def get_reraise_exceptions(config: Config) -> tuple[type[BaseException], ...]:
    """Return exception types that should not be suppressed in general."""
    reraise: tuple[type[BaseException], ...] = (Exit,)
    if not config.getoption('usepdb', False):
        reraise += (KeyboardInterrupt,)
    return reraise

def check_interactive_exception(call: CallInfo[object], report: BaseReport) -> bool:
    """Check whether the call raised an exception that should be reported as
    interactive."""
    if call.excinfo is None:
        return False
    if hasattr(report, 'wasxfail'):
        return False
    unittest = sys.modules.get('unittest')
    if isinstance(call.excinfo.value, Skipped | bdb.BdbQuit) or (unittest is not None and isinstance(call.excinfo.value, unittest.SkipTest)):
        return False
    return True

@property
def result(self) -> TResult:
    """The return value of the call, if it didn't raise.

        Can only be accessed if excinfo is None.
        """
    if self.excinfo is not None:
        raise AttributeError(f'{self!r} has no valid result')
    return cast(TResult, self._result)

def teardown_exact(self, nextitem: Item | None) -> None:
    """Teardown the current stack up until reaching nodes that nextitem
        also descends from.

        When nextitem is None (meaning we're at the last item), the entire
        stack is torn down.
        """
    needed_collectors = nextitem and nextitem.listchain() or []
    exceptions: list[BaseException] = []
    while self.stack:
        if list(self.stack.keys()) == needed_collectors[:len(self.stack)]:
            break
        node, (finalizers, _) = self.stack.popitem()
        these_exceptions = []
        while finalizers:
            fin = finalizers.pop()
            try:
                fin()
            except TEST_OUTCOME as e:
                these_exceptions.append(e)
        if len(these_exceptions) == 1:
            exceptions.extend(these_exceptions)
        elif these_exceptions:
            msg = f'errors while tearing down {node!r}'
            exceptions.append(BaseExceptionGroup(msg, these_exceptions[::-1]))
    if len(exceptions) == 1:
        raise exceptions[0]
    elif exceptions:
        raise BaseExceptionGroup('errors during test teardown', exceptions[::-1])
    if nextitem is None:
        assert not self.stack

@classmethod
def from_user(cls, scope_name: ScopeName, descr: str, where: str | None=None) -> Scope:
    """
        Given a scope name from the user, return the equivalent Scope enum. Should be used
        whenever we want to convert a user provided scope name to its enum object.

        If the scope name is invalid, construct a user friendly message and call pytest.fail.
        """
    from _pytest.outcomes import fail
    try:
        scope = Scope(scope_name)
    except ValueError:
        fail("{} {}got an unexpected scope value '{}'".format(descr, f'from {where} ' if where else '', scope_name), pytrace=False)
    return scope

def evaluate_condition(item: Item, mark: Mark, condition: object) -> tuple[bool, str]:
    """Evaluate a single skipif/xfail condition.

    If an old-style string condition is given, it is eval()'d, otherwise the
    condition is bool()'d. If this fails, an appropriately formatted pytest.fail
    is raised.

    Returns (result, reason). The reason is only relevant if the result is True.
    """
    if isinstance(condition, str):
        globals_ = {'os': os, 'sys': sys, 'platform': platform, 'config': item.config}
        for dictionary in reversed(item.ihook.pytest_markeval_namespace(config=item.config)):
            if not isinstance(dictionary, Mapping):
                raise ValueError(f'pytest_markeval_namespace() needs to return a dict, got {dictionary!r}')
            globals_.update(dictionary)
        if hasattr(item, 'obj'):
            globals_.update(item.obj.__globals__)
        try:
            filename = f'<{mark.name} condition>'
            condition_code = compile(condition, filename, 'eval')
            result = eval(condition_code, globals_)
        except SyntaxError as exc:
            msglines = [f'Error evaluating {mark.name!r} condition', '    ' + condition, '    ' + ' ' * (exc.offset or 0) + '^', 'SyntaxError: invalid syntax']
            fail('\n'.join(msglines), pytrace=False)
        except Exception as exc:
            msglines = [f'Error evaluating {mark.name!r} condition', '    ' + condition, *traceback.format_exception_only(exc)]
            fail('\n'.join(msglines), pytrace=False)
    else:
        try:
            result = bool(condition)
        except Exception as exc:
            msglines = [f'Error evaluating {mark.name!r} condition as a boolean', *traceback.format_exception_only(exc)]
            fail('\n'.join(msglines), pytrace=False)
    reason = mark.kwargs.get('reason', None)
    if reason is None:
        if isinstance(condition, str):
            reason = 'condition: ' + condition
        else:
            msg = f'Error evaluating {mark.name!r}: ' + 'you need to specify reason=STRING when using booleans as conditions.'
            fail(msg, pytrace=False)
    return (result, reason)

def evaluate_skip_marks(item: Item) -> Skip | None:
    """Evaluate skip and skipif marks on item, returning Skip if triggered."""
    for mark in item.iter_markers(name='skipif'):
        if 'condition' not in mark.kwargs:
            conditions = mark.args
        else:
            conditions = (mark.kwargs['condition'],)
        if not conditions:
            reason = mark.kwargs.get('reason', '')
            return Skip(reason)
        for condition in conditions:
            result, reason = evaluate_condition(item, mark, condition)
            if result:
                return Skip(reason)
    for mark in item.iter_markers(name='skip'):
        try:
            return Skip(*mark.args, **mark.kwargs)
        except TypeError as e:
            raise TypeError(str(e) + ' - maybe you meant pytest.mark.skipif?') from None
    return None

def __getitem__(self, key: StashKey[T]) -> T:
    """Get the value for key.

        Raises ``KeyError`` if the key wasn't set before.
        """
    return cast(T, self._storage[key])

def get(self, key: StashKey[T], default: D) -> T | D:
    """Get the value for key, or return default if the key wasn't set
        before."""
    try:
        return self[key]
    except KeyError:
        return default

def setdefault(self, key: StashKey[T], default: T) -> T:
    """Return the value of key if already set, otherwise set the value
        of key to default and return default."""
    try:
        return self[key]
    except KeyError:
        self[key] = default
        return default

def _format_trimmed(format: str, msg: str, available_width: int) -> str | None:
    """Format msg into format, ellipsizing it if doesn't fit in available_width.

    Returns None if even the ellipsis can't fit.
    """
    i = msg.find('\n')
    if i != -1:
        msg = msg[:i]
    ellipsis = '...'
    format_width = wcswidth(format.format(''))
    if format_width + len(ellipsis) > available_width:
        return None
    if format_width + wcswidth(msg) > available_width:
        available_width -= len(ellipsis)
        msg = msg[:available_width]
        while format_width + wcswidth(msg) > available_width:
            msg = msg[:-1]
        msg += ellipsis
    return format.format(msg)

def _get_line_with_reprcrash_message(config: Config, rep: BaseReport, tw: TerminalWriter, word_markup: dict[str, bool]) -> str:
    """Get summary line for a report, trying to add reprcrash message."""
    verbose_word, verbose_markup = rep._get_verbose_word_with_markup(config, word_markup)
    word = tw.markup(verbose_word, **verbose_markup)
    node = _get_node_id_with_markup(tw, config, rep)
    line = f'{word} {node}'
    line_width = wcswidth(line)
    msg: str | None
    try:
        if isinstance(rep.longrepr, str):
            msg = rep.longrepr
        else:
            msg = rep.longrepr.reprcrash.message
    except AttributeError:
        pass
    else:
        if (running_on_ci() or config.option.verbose >= 2) and (not config.option.force_short_summary):
            msg = f' - {msg}'
        else:
            available_width = tw.fullwidth - line_width
            msg = _format_trimmed(' - {}', msg, available_width)
        if msg is not None:
            line += msg
    return line

def format_session_duration(seconds: float) -> str:
    """Format the given seconds in a human readable manner to show in the final summary."""
    if seconds < 60:
        return f'{seconds:.2f}s'
    else:
        dt = datetime.timedelta(seconds=int(seconds))
        return f'{seconds:.2f}s ({dt})'

def format_node_duration(seconds: float) -> str:
    """Format the given seconds in a human readable manner to show in the test progress."""
    if seconds < 1e-05:
        return f' {seconds * 1000000:.3f}us'
    if seconds < 0.0001:
        return f' {seconds * 1000000:.2f}us'
    if seconds < 0.001:
        return f' {seconds * 1000000:.1f}us'
    if seconds < 0.01:
        return f' {seconds * 1000:.3f}ms'
    if seconds < 0.1:
        return f' {seconds * 1000:.2f}ms'
    if seconds < 1:
        return f' {seconds * 1000:.1f}ms'
    if seconds < 60:
        return f' {seconds:.3f}s'
    if seconds < 3600:
        return f' {seconds // 60:.0f}m {seconds % 60:.0f}s'
    return f' {seconds // 3600:.0f}h {seconds % 3600 // 60:.0f}m'

def _get_raw_skip_reason(report: TestReport) -> str:
    """Get the reason string of a skip/xfail/xpass test report.

    The string is just the part given by the user.
    """
    if hasattr(report, 'wasxfail'):
        reason = report.wasxfail
        if reason.startswith('reason: '):
            reason = reason[len('reason: '):]
        return reason
    else:
        assert report.skipped
        assert isinstance(report.longrepr, tuple)
        _, _, reason = report.longrepr
        if reason.startswith('Skipped: '):
            reason = reason[len('Skipped: '):]
        elif reason == 'Skipped':
            reason = ''
        return reason

def get_location(self, config: Config) -> str | None:
    """Return the more user-friendly information about the location of a warning, or None."""
    if self.nodeid:
        return self.nodeid
    if self.fslocation:
        filename, linenum = self.fslocation
        relpath = bestrelpath(config.invocation_params.dir, absolutepath(filename))
        return f'{relpath}:{linenum}'
    return None

def _determine_show_progress_info(self) -> Literal['progress', 'count', 'times', False]:
    """Return whether we should display progress information based on the current config."""
    if self.config.getoption('capture', 'no') == 'no' and self.config.getini('console_output_style') != 'progress-even-when-capture-no':
        return False
    if self.config.getoption('setupshow', False):
        return False
    cfg: str = self.config.getini('console_output_style')
    if cfg in {'progress', 'progress-even-when-capture-no'}:
        return 'progress'
    elif cfg == 'count':
        return 'count'
    elif cfg == 'times':
        return 'times'
    else:
        return False

@property
def reported_progress(self) -> int:
    """The amount of items reported in the progress so far.

        :meta private:
        """
    return len(self._progress_nodeids_reported)

def _get_max_warnings(self) -> int | None:
    """Return the max_warnings threshold, from CLI or INI, or None if unset."""
    value = self.config.option.max_warnings
    if value is not None:
        return int(value)
    ini_value = self.config.getini('max_warnings')
    if ini_value:
        return int(ini_value)
    return None

def build_summary_stats_line(self) -> tuple[list[tuple[str, dict[str, bool]]], str]:
    """
        Build the parts used in the last summary stats line.

        The summary stats line is the line shown at the end, "=== 12 passed, 2 errors in Xs===".

        This function builds a list of the "parts" that make up for the text in that line, in
        the example above it would be::

            [
                ("12 passed", {"green": True}),
                ("2 errors", {"red": True}
            ]

        That last dict for each line is a "markup dictionary", used by TerminalWriter to
        color output.

        The final color of the line is also determined by this function, and is the second
        element of the returned tuple.
        """
    if self.config.getoption('collectonly'):
        return self._build_collect_only_summary_stats_line()
    else:
        return self._build_normal_summary_stats_line()

@property
def seconds(self) -> float:
    """Elapsed time of the duration in seconds, measured using a performance counter for precise timing."""
    return self.stop.perf_count - self.start.perf_count

def get_user() -> str | None:
    """Return the current user name, or None if getuser() does not work
    in the current environment (see #1010)."""
    try:
        import getpass
        return getpass.getuser()
    except (ImportError, OSError, KeyError):
        return None

def pytest_sessionfinish(session, exitstatus: int | ExitCode):
    """After each session, remove base directory if all the tests passed,
    the policy is "failed", and the basetemp is not specified by a user.
    """
    tmp_path_factory: TempPathFactory = session.config._tmp_path_factory
    basetemp = tmp_path_factory._basetemp
    if basetemp is None:
        return
    policy = tmp_path_factory._retention_policy
    if exitstatus == 0 and policy == 'failed' and (tmp_path_factory._given_basetemp is None):
        if basetemp.is_dir():
            rmtree(basetemp, ignore_errors=True)
    if basetemp.is_dir():
        cleanup_dead_symlinks(basetemp)
    tmp_path_factory._exit_stack.close()

def _is_skipped(obj) -> bool:
    """Return True if the given object has been marked with @unittest.skip."""
    return bool(getattr(obj, '__unittest_skip__', False))

def pytest_configure() -> None:
    """Register the TestCaseFunction class as an IReporter if twisted.trial is available."""
    if _get_twisted_version() is not TwistedVersion.NotInstalled:
        from twisted.trial.itrial import IReporter
        from zope.interface import classImplements
        classImplements(TestCaseFunction, IReporter)

def _handle_twisted_exc_info(rawexcinfo: _SysExcInfoType | BaseException) -> _SysExcInfoType:
    """
    Twisted passes a custom Failure instance to `addError()` instead of using `sys.exc_info()`.
    Therefore, if `rawexcinfo` is a `Failure` instance, convert it into the equivalent `sys.exc_info()` tuple
    as expected by pytest.
    """
    twisted_version = _get_twisted_version()
    if twisted_version is TwistedVersion.NotInstalled:
        return rawexcinfo
    elif twisted_version is TwistedVersion.Version24:
        if hasattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR):
            saved_exc_info = getattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR)
            delattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR)
            return saved_exc_info
        return rawexcinfo
    elif twisted_version is TwistedVersion.Version25:
        if isinstance(rawexcinfo, BaseException):
            import twisted.python.failure
            if isinstance(rawexcinfo, twisted.python.failure.Failure):
                tb = rawexcinfo.__traceback__
                if tb is None:
                    tb = sys.exc_info()[2]
                return (type(rawexcinfo.value), rawexcinfo.value, tb)
        return rawexcinfo
    else:
        assert False, f'Unexpected Twisted version: {twisted_version}'

def _register_unittest_setup_class_fixture(self, cls: type) -> None:
    """Register an auto-use fixture to invoke setUpClass and
        tearDownClass (#517)."""
    setup = getattr(cls, 'setUpClass', None)
    teardown = getattr(cls, 'tearDownClass', None)
    if setup is None and teardown is None:
        return None
    cleanup = getattr(cls, 'doClassCleanups', lambda: None)

    def process_teardown_exceptions() -> None:
        exc_infos = getattr(cls, 'tearDown_exceptions', None)
        if not exc_infos:
            return
        exceptions = [exc for _, exc, _ in exc_infos]
        if len(exceptions) == 1:
            raise exceptions[0]
        else:
            raise ExceptionGroup('Unittest class cleanup errors', exceptions)

    def unittest_setup_class_fixture(request: FixtureRequest) -> Generator[None]:
        cls = request.cls
        if _is_skipped(cls):
            reason = cls.__unittest_skip_why__
            raise skip.Exception(reason, _use_item_location=True)
        if setup is not None:
            try:
                setup()
            except Exception:
                cleanup()
                process_teardown_exceptions()
                raise
        yield
        try:
            if teardown is not None:
                teardown()
        finally:
            cleanup()
            process_teardown_exceptions()
    fixtures.register_fixture(name=f'_unittest_setUpClass_fixture_{cls.__qualname__}', func=unittest_setup_class_fixture, node=self, scope='class', autouse=True)

def _register_unittest_setup_method_fixture(self, cls: type) -> None:
    """Register an auto-use fixture to invoke setup_method and
        teardown_method (#517)."""
    setup = getattr(cls, 'setup_method', None)
    teardown = getattr(cls, 'teardown_method', None)
    if setup is None and teardown is None:
        return None

    def unittest_setup_method_fixture(request: FixtureRequest) -> Generator[None]:
        self = request.instance
        if _is_skipped(self):
            reason = self.__unittest_skip_why__
            raise skip.Exception(reason, _use_item_location=True)
        if setup is not None:
            setup(self, request.function)
        yield
        if teardown is not None:
            teardown(self, request.function)
    fixtures.register_fixture(name=f'_unittest_setup_method_fixture_{cls.__qualname__}', func=unittest_setup_method_fixture, node=self, scope='function', autouse=True)

def _obtain_errors_and_skips(self) -> tuple[list[Any], list[Any]]:
    """Compute or obtain the cached values for subtest errors and non-subtest skips."""
    from unittest.case import _SubTest
    assert sys.version_info < (3, 11), 'This workaround only should be used in Python 3.10'
    if self._cached_errors_and_skips is not None:
        return self._cached_errors_and_skips
    subtest_errors = [(x, y) for x, y in self.instance._outcome.errors if isinstance(x, _SubTest) and y is not None]
    non_subtest_skips = [(x, y) for x, y in self.instance._outcome.skipped if not isinstance(x, _SubTest)]
    self._cached_errors_and_skips = (subtest_errors, non_subtest_skips)
    return (subtest_errors, non_subtest_skips)

@contextmanager
def catch_warnings_for_item(config: Config, ihook, when: Literal['config', 'collect', 'runtest'], item: Item | None, *, record: bool=True) -> Generator[None]:
    """Context manager that catches warnings generated in the contained execution block.

    ``item`` can be None if we are not in the context of an item execution.

    Each warning captured triggers the ``pytest_warning_recorded`` hook.
    """
    with config._catch_configured_warnings(record=record) as log:
        nodeid = '' if item is None else item.nodeid
        if item is not None:
            for mark in item.iter_markers(name='filterwarnings'):
                for arg in mark.args:
                    warnings.filterwarnings(*parse_warning_filter(arg, escape=False))
        try:
            yield
        finally:
            if record:
                assert log is not None
                for warning_message in log:
                    ihook.pytest_warning_recorded.call_historic(kwargs=dict(warning_message=warning_message, nodeid=nodeid, when=when, location=None))

def format(self, **kwargs: Any) -> _W:
    """Return an instance of the warning category, formatted with given kwargs."""
    return self.category(self.template.format(**kwargs))

def _diff_text(left: str, right: str, highlighter: _HighlightFunc, verbose: int=0) -> Iterator[str]:
    """Yield the explanation for the diff between text.

    Unless --verbose is used this will skip leading and trailing
    characters which are identical to keep the diff minimal.
    """
    from difflib import ndiff
    if verbose < 1:
        i = 0
        for i in range(min(len(left), len(right))):
            if left[i] != right[i]:
                break
        if i > 42:
            i -= 10
            yield f'Skipping {i} identical leading characters in diff, use -v to show'
            left = left[i:]
            right = right[i:]
        if len(left) == len(right):
            for i in range(1, len(left) + 1):
                if left[-i] != right[-i]:
                    break
            if i > 42:
                i -= 10
                yield f'Skipping {i} identical trailing characters in diff, use -v to show'
                left = left[:-i]
                right = right[:-i]
    keepends = True
    if left.isspace() or right.isspace():
        left = repr(str(left))
        right = repr(str(right))
        yield 'Strings contain only whitespace, escaping them using repr()'
    yield from highlighter('\n'.join((line.strip('\n') for line in ndiff(right.splitlines(keepends), left.splitlines(keepends)))), lexer='diff').splitlines()

def _read_pyc(source: Path, pyc: Path, trace: Callable[[str], None]=lambda x: None) -> types.CodeType | None:
    """Possibly read a pytest pyc containing rewritten code.

    Return rewritten code if successful or None if not.
    """
    try:
        fp = open(pyc, 'rb')
    except OSError:
        return None
    with fp:
        try:
            stat_result = os.stat(source)
            mtime = int(stat_result.st_mtime)
            size = stat_result.st_size
            data = fp.read(16)
        except OSError as e:
            trace(f'_read_pyc({source}): OSError {e}')
            return None
        if len(data) != 16:
            trace(f'_read_pyc({source}): invalid pyc (too short)')
            return None
        if data[:4] != importlib.util.MAGIC_NUMBER:
            trace(f'_read_pyc({source}): invalid pyc (bad magic number)')
            return None
        if data[4:8] != b'\x00\x00\x00\x00':
            trace(f'_read_pyc({source}): invalid pyc (unsupported flags)')
            return None
        mtime_data = data[8:12]
        if int.from_bytes(mtime_data, 'little') != mtime & 4294967295:
            trace(f'_read_pyc({source}): out of date')
            return None
        size_data = data[12:16]
        if int.from_bytes(size_data, 'little') != size & 4294967295:
            trace(f'_read_pyc({source}): invalid pyc (incorrect size)')
            return None
        try:
            co = marshal.load(fp)
        except Exception as e:
            trace(f'_read_pyc({source}): marshal.load error {e}')
            return None
        if not isinstance(co, types.CodeType):
            trace(f'_read_pyc({source}): not a code object')
            return None
        return co

def _saferepr(obj: object) -> str:
    """Get a safe repr of an object for assertion error messages.

    The assertion formatting (util.format_explanation()) requires
    newlines to be escaped since they are a special character for it.
    Normally assertion.util.format_explanation() does this but for a
    custom repr it is possible to contain one of the special escape
    sequences, especially '\\n{' and '\\n}' are likely to be present in
    JSON reprs.
    """
    if isinstance(obj, types.MethodType):
        return obj.__name__
    maxsize = _get_maxsize_for_saferepr(util._config)
    if not maxsize:
        return saferepr_unlimited(obj).replace('\n', '\\n')
    return saferepr(obj, maxsize=maxsize).replace('\n', '\\n')

def _get_maxsize_for_saferepr(config: Config | None) -> int | None:
    """Get `maxsize` configuration for saferepr based on the given config object."""
    if config is None:
        verbosity = 0
    else:
        verbosity = config.get_verbosity(Config.VERBOSITY_ASSERTIONS)
    if verbosity >= 2:
        return None
    if verbosity >= 1:
        return DEFAULT_REPR_MAX_SIZE * 10
    return DEFAULT_REPR_MAX_SIZE

def traverse_node(node: ast.AST) -> Iterator[ast.AST]:
    """Recursively yield node and all its children in depth-first order."""
    yield node
    for child in ast.iter_child_nodes(node):
        yield from traverse_node(child)

def try_makedirs(cache_dir: Path) -> bool:
    """Attempt to create the given directory and sub-directories exist.

    Returns True if successful or if it already exists.
    """
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except (FileNotFoundError, NotADirectoryError, FileExistsError):
        return False
    except PermissionError:
        return False
    except OSError as e:
        if e.errno in {errno.EROFS, errno.ENOSYS}:
            return False
        raise
    return True

def get_cache_dir(file_path: Path) -> Path:
    """Return the cache directory to write .pyc files for the given .py file path."""
    if sys.pycache_prefix:
        return Path(sys.pycache_prefix) / Path(*file_path.parts[1:-1])
    else:
        return file_path.parent / '__pycache__'

def _early_rewrite_bailout(self, name: str, state: AssertionState) -> bool:
    """A fast way to get out of rewriting modules.

        Profiling has shown that the call to PathFinder.find_spec (inside of
        the find_spec from this class) is a major slowdown, so, this method
        tries to filter what we're sure won't be rewritten before getting to
        it.
        """
    if self.session is not None and (not self._session_paths_checked):
        self._session_paths_checked = True
        for initial_path in self.session._initialpaths:
            parts = str(initial_path).split(os.sep)
            self._basenames_to_check_rewrite.add(os.path.splitext(parts[-1])[0])
    parts = name.split('.')
    if parts[-1] in self._basenames_to_check_rewrite:
        return False
    path = PurePath(*parts).with_suffix('.py')
    for pat in self.fnpats:
        if os.path.dirname(pat):
            return False
        if fnmatch_ex(pat, path):
            return False
    if self._is_marked_for_rewrite(name, state):
        return False
    state.trace(f'early skip of rewriting module: {name}')
    return True

def truncate_if_required(explanation: list[str], item: Item) -> list[str]:
    """Truncate this assertion explanation if the given test item is eligible."""
    should_truncate, budget = _get_truncation_parameters(item)
    if should_truncate:
        return _truncate_explanation(explanation, budget)
    return explanation

def assertrepr_compare(op: str, left: object, right: object, *, verbose: int, highlighter: _HighlightFunc, assertion_text_diff_style: _AssertionTextDiffStyle) -> Iterator[str]:
    """Yield specialised explanations for some operators/operands.

    The first line yielded is always the summary (``left op right``);
    subsequent lines are the detailed explanation. Yields nothing when no
    specialised explanation applies, which lets consumers map an empty
    iterator to "no explanation" without materialising anything.

    The iterator is lazy on purpose: a streaming consumer can stop pulling
    lines as soon as it has enough to show, so an enormous diff doesn't
    have to be built in full just to be thrown away.
    """
    use_ascii = isinstance(left, str) and isinstance(right, str) and (normalize('NFD', left) == normalize('NFD', right))
    if verbose > 1:
        left_repr = saferepr_unlimited(left, use_ascii=use_ascii)
        right_repr = saferepr_unlimited(right, use_ascii=use_ascii)
    else:
        maxsize = (80 - 15 - len(op) - 2) // 2
        left_repr = saferepr(left, maxsize=maxsize, use_ascii=use_ascii)
        right_repr = saferepr(right, maxsize=maxsize, use_ascii=use_ascii)
    summary = f'{left_repr} {op} {right_repr}'
    try:
        if op == '==':
            source = _compare_eq_any(left, right, highlighter, verbose, assertion_text_diff_style)
        elif op == 'not in' and istext(left) and istext(right):
            source = _notin_text(left, right, verbose)
        elif op in {'!=', '>=', '<=', '>', '<'} and isset(left) and isset(right):
            source = SET_COMPARISON_FUNCTIONS[op](left, right, highlighter, verbose)
        else:
            source = iter(())
        summary_yielded = False
        for line in source:
            if not summary_yielded:
                yield summary
                if line != '':
                    yield ''
                summary_yielded = True
            yield line
    except outcomes.Exit:
        raise
    except Exception:
        repr_crash = _pytest._code.ExceptionInfo.from_current()._getreprcrash()
        if not summary_yielded:
            yield summary
            yield ''
            summary_yielded = True
        yield f'(pytest_assertion plugin: representation of details failed: {repr_crash}.'
        yield ' Probably an object has a faulty __repr__.)'

def _compare_eq_any(left: object, right: object, highlighter: _HighlightFunc, verbose: int, assertion_text_diff_style: _AssertionTextDiffStyle) -> Iterator[str]:
    """Yield the per-line explanation for ``left == right`` (without summary).

    Yields nothing when no specialised explanation applies, so consumers
    can stream the output and bail out early (e.g. for truncation) without
    materialising the entire diff first.
    """
    if istext(left) and istext(right):
        yield from _compare_eq_text(left, right, highlighter, verbose, assertion_text_diff_style)
    else:
        from _pytest.approx import Approx
        if isinstance(right, Approx):
            yield from right._repr_compare(left)
        elif isinstance(left, Approx):
            yield from left._repr_compare(right)
        elif type(left) is type(right) and (isdatacls(left) or isattrs(left) or isnamedtuple(left)):
            yield from _compare_eq_cls(left, right, highlighter, verbose, assertion_text_diff_style)
        elif issequence(left) and issequence(right):
            yield from _compare_eq_sequence(left, right, highlighter, verbose)
        elif isset(left) and isset(right):
            yield from _compare_eq_set(left, right, highlighter, verbose)
        elif ismapping(left) and ismapping(right):
            yield from _compare_eq_mapping(left, right, highlighter, verbose)
        if isiterable(left) and isiterable(right):
            yield from _compare_eq_iterable(left, right, highlighter, verbose)

def has_default_eq(obj: object) -> bool:
    """Check if an instance of an object contains the default eq

    First, we check if the object's __eq__ attribute has __code__,
    if so, we check the equally of the method code filename (__code__.co_filename)
    to the default one generated by the dataclass and attr module
    for dataclasses the default co_filename is <string>, for attrs class, the __eq__ should contain "attrs eq generated"
    """
    if hasattr(obj.__eq__, '__code__') and hasattr(obj.__eq__.__code__, 'co_filename'):
        code_filename = obj.__eq__.__code__.co_filename
        if isattrs(obj):
            return 'attrs generated ' in code_filename
        return code_filename == '<string>'
    return True

def get_ini_default_for_type(type: Literal['string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float']) -> Any:
    """
    Used by addini to get the default value for a given config option type, when
    default is not supplied.
    """
    if type in ('paths', 'pathlist', 'args', 'linelist'):
        return []
    elif type == 'bool':
        return False
    elif type == 'int':
        return 0
    elif type == 'float':
        return 0.0
    else:
        return ''

def parse(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> argparse.Namespace:
    """Parse the arguments.

        Unlike ``parse_known_args`` and ``parse_known_and_unknown_args``,
        raises PrintHelp on `--help` and UsageError on unknown flags

        :meta private:
        """
    from _pytest._argcomplete import try_argcomplete
    try_argcomplete(self.optparser)
    strargs = [os.fspath(x) for x in args]
    if namespace is None:
        namespace = argparse.Namespace()
    try:
        namespace._raise_print_help = True
        return self.optparser.parse_intermixed_args(strargs, namespace=namespace)
    finally:
        del namespace._raise_print_help

def parse_known_and_unknown_args(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> tuple[argparse.Namespace, list[str]]:
    """Parse the known arguments at this point, and also return the
        remaining unknown flag arguments.

        :returns:
            A tuple containing an argparse namespace object for the known
            arguments, and a list of unknown flag arguments.
        """
    strargs = [os.fspath(x) for x in args]
    if sys.version_info < (3, 12, 8) or (3, 13) <= sys.version_info < (3, 13, 1):
        namespace, unknown = self.optparser.parse_known_args(strargs, namespace)
        assert namespace is not None
        file_or_dir = getattr(namespace, FILE_OR_DIR)
        unknown_flags: list[str] = []
        for arg in unknown:
            (unknown_flags if arg.startswith('-') else file_or_dir).append(arg)
        return (namespace, unknown_flags)
    else:
        return self.optparser.parse_known_intermixed_args(strargs, namespace)

def _parse_ini_config(path: Path) -> iniconfig.IniConfig:
    """Parse the given generic '.ini' file using legacy IniConfig parser, returning
    the parsed object.

    Raise UsageError if the file cannot be parsed.
    """
    try:
        return iniconfig.IniConfig(str(path))
    except iniconfig.ParseError as exc:
        raise UsageError(str(exc)) from exc

def load_config_dict_from_file(filepath: Path) -> ConfigDict | None:
    """Load pytest configuration from the given file path, if supported.

    Return None if the file does not contain valid pytest configuration.
    """
    if filepath.suffix == '.ini':
        iniconfig = _parse_ini_config(filepath)
        if 'pytest' in iniconfig:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['pytest'].items()}
        elif filepath.name in {'pytest.ini', '.pytest.ini'}:
            return {}
    elif filepath.suffix == '.cfg':
        iniconfig = _parse_ini_config(filepath)
        if 'tool:pytest' in iniconfig.sections:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['tool:pytest'].items()}
        elif 'pytest' in iniconfig.sections:
            fail(CFG_PYTEST_SECTION.format(filename='setup.cfg'), pytrace=False)
    elif filepath.suffix == '.toml':
        if sys.version_info >= (3, 11):
            import tomllib
        else:
            import tomli as tomllib
        toml_text = filepath.read_text(encoding='utf-8')
        try:
            config = tomllib.loads(toml_text)
        except tomllib.TOMLDecodeError as exc:
            raise UsageError(f'{filepath}: {exc}') from exc
        if filepath.name in ('pytest.toml', '.pytest.toml'):
            if 'pytest' in config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in config['pytest'].items()}
            top_level_options = [key for key, value in config.items() if not isinstance(value, dict)]
            if top_level_options:
                raise UsageError(f"{filepath}: pytest configuration must be under a [pytest] table (found top-level options: {', '.join(top_level_options)})")
            return {}
        else:
            tool_pytest = config.get('tool', {}).get('pytest', {})
            toml_config = {k: v for k, v in tool_pytest.items() if k != 'ini_options'}
            ini_config = tool_pytest.get('ini_options', None)
            if toml_config and ini_config:
                raise UsageError(f'{filepath}: Cannot use both [tool.pytest] (native TOML types) and [tool.pytest.ini_options] (string-based INI format) simultaneously. Please use [tool.pytest] with native TOML types (recommended) or [tool.pytest.ini_options] for backwards compatibility.')
            if toml_config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in toml_config.items()}
            elif ini_config is not None:

                def make_scalar(v: object) -> str | list[str]:
                    return v if isinstance(v, list) else str(v)
                return {k: ConfigValue(make_scalar(v), origin='file', mode='ini') for k, v in ini_config.items()}
    return None

def locate_config(invocation_dir: Path, args: Iterable[Path]) -> tuple[Path | None, Path | None, ConfigDict, Sequence[str]]:
    """Search in the list of arguments for a valid ini-file for pytest,
    and return a tuple of (rootdir, inifile, cfg-dict, ignored-config-files), where
    ignored-config-files is a list of config basenames found that contain
    pytest configuration but were ignored."""
    config_names = ['pytest.toml', '.pytest.toml', 'pytest.ini', '.pytest.ini', 'pyproject.toml', 'tox.ini', 'setup.cfg']
    args = [x for x in args if not str(x).startswith('-')]
    if not args:
        args = [invocation_dir]
    found_pyproject_toml: Path | None = None
    ignored_config_files: list[str] = []
    for arg in args:
        argpath = absolutepath(arg)
        for base in (argpath, *argpath.parents):
            for config_name in config_names:
                p = base / config_name
                if p.is_file():
                    if p.name == 'pyproject.toml' and found_pyproject_toml is None:
                        found_pyproject_toml = p
                    ini_config = load_config_dict_from_file(p)
                    if ini_config is not None:
                        index = config_names.index(config_name)
                        for remainder in config_names[index + 1:]:
                            p2 = base / remainder
                            if p2.is_file() and load_config_dict_from_file(p2) is not None:
                                ignored_config_files.append(remainder)
                        return (base, p, ini_config, ignored_config_files)
    if found_pyproject_toml is not None:
        return (found_pyproject_toml.parent, found_pyproject_toml, {}, [])
    return (None, None, {}, [])

def parse_override_ini(override_ini: Sequence[str] | None) -> ConfigDict:
    """Parse the -o/--override-ini command line arguments and return the overrides.

    :raises UsageError:
        If one of the values is malformed.
    """
    overrides = {}
    for ini_config in override_ini or ():
        try:
            key, user_ini_value = ini_config.split('=', 1)
        except ValueError as e:
            raise UsageError(f'-o/--override-ini expects option=value style (got: {ini_config!r}).') from e
        else:
            overrides[key] = ConfigValue(user_ini_value, origin='override', mode='ini')
    return overrides

def determine_setup(*, inifile: str | None, override_ini: Sequence[str] | None, args: Sequence[str], rootdir_cmd_arg: str | None, invocation_dir: Path) -> tuple[Path, Path | None, ConfigDict, Sequence[str]]:
    """Determine the rootdir, inifile and ini configuration values from the
    command line arguments.

    :param inifile:
        The `--inifile` command line argument, if given.
    :param override_ini:
        The -o/--override-ini command line arguments, if given.
    :param args:
        The free command line arguments.
    :param rootdir_cmd_arg:
        The `--rootdir` command line argument, if given.
    :param invocation_dir:
        The working directory when pytest was invoked.

    :raises UsageError:
    """
    rootdir = None
    dirs = get_dirs_from_args(args)
    ignored_config_files: Sequence[str] = []
    if inifile:
        inipath_ = absolutepath(inifile)
        inipath: Path | None = inipath_
        inicfg = load_config_dict_from_file(inipath_) or {}
        if rootdir_cmd_arg is None:
            rootdir = inipath_.parent
    else:
        ancestor = get_common_ancestor(invocation_dir, dirs)
        rootdir, inipath, inicfg, ignored_config_files = locate_config(invocation_dir, [ancestor])
        if rootdir is None and rootdir_cmd_arg is None:
            for possible_rootdir in (ancestor, *ancestor.parents):
                if (possible_rootdir / 'setup.py').is_file():
                    rootdir = possible_rootdir
                    break
            else:
                if dirs != [ancestor]:
                    rootdir, inipath, inicfg, _ = locate_config(invocation_dir, dirs)
                if rootdir is None:
                    rootdir = get_common_ancestor(invocation_dir, [invocation_dir, ancestor])
                    if is_fs_root(rootdir):
                        rootdir = ancestor
    if rootdir_cmd_arg:
        rootdir = absolutepath(os.path.expandvars(rootdir_cmd_arg))
        if not rootdir.is_dir():
            raise UsageError(f"Directory '{rootdir}' not found. Check your '--rootdir' option.")
    ini_overrides = parse_override_ini(override_ini)
    inicfg.update(ini_overrides)
    assert rootdir is not None
    return (rootdir, inipath, inicfg, ignored_config_files)

def filter_traceback_for_conftest_import_failure(entry: _pytest._code.TracebackEntry) -> bool:
    """Filter tracebacks entries which point to pytest internals or importlib.

    Make a special case for importlib because we use it to import test modules and conftest files
    in _pytest.pathlib.import_path.
    """
    return filter_traceback(entry) and 'importlib' not in str(entry.path).split(os.sep)

def _get_directory(path: pathlib.Path) -> pathlib.Path:
    """Get the directory of a path - itself if already a directory."""
    if path.is_file():
        return path.parent
    else:
        return path

def _get_plugin_specs_as_list(specs: None | types.ModuleType | str | Sequence[str]) -> list[str]:
    """Parse a plugins specification into a list of plugin names."""
    if specs is None:
        return []
    if isinstance(specs, types.ModuleType):
        return []
    if isinstance(specs, str):
        return specs.split(',') if specs else []
    if isinstance(specs, collections.abc.Sequence):
        return list(specs)
    raise UsageError(f"Plugins may be specified as a sequence or a ','-separated string of plugin names. Got: {specs!r}")

def create_terminal_writer(config: Config, file: TextIO | None=None) -> TerminalWriter:
    """Create a TerminalWriter instance configured according to the options
    in the config object.

    Every code which requires a TerminalWriter object and has access to a
    config object should use this function.
    """
    tw = TerminalWriter(file=file)
    if config.option.color == 'yes':
        tw.hasmarkup = True
    elif config.option.color == 'no':
        tw.hasmarkup = False
    if config.option.code_highlight == 'yes':
        tw.code_highlight = True
    elif config.option.code_highlight == 'no':
        tw.code_highlight = False
    return tw

@lru_cache(maxsize=50)
def parse_warning_filter(arg: str, *, escape: bool) -> tuple[warnings._ActionKind, str, type[Warning], str, int]:
    """Parse a warnings filter string.

    This is copied from warnings._setoption with the following changes:

    * Does not apply the filter.
    * Escaping is optional.
    * Raises UsageError so we get nice error messages on failure.
    """
    __tracebackhide__ = True
    error_template = dedent(f'        while parsing the following warning configuration:\n\n          {arg}\n\n        This error occurred:\n\n        {{error}}\n        ')
    parts = arg.split(':')
    if len(parts) > 5:
        doc_url = 'https://docs.python.org/3/library/warnings.html#describing-warning-filters'
        error = dedent(f'            Too many fields ({len(parts)}), expected at most 5 separated by colons:\n\n              action:message:category:module:line\n\n            For more information please consult: {doc_url}\n            ')
        raise UsageError(error_template.format(error=error))
    while len(parts) < 5:
        parts.append('')
    action_, message, category_, module, lineno_ = (s.strip() for s in parts)
    try:
        action: warnings._ActionKind = warnings._getaction(action_)
    except warnings._OptionError as e:
        raise UsageError(error_template.format(error=str(e))) from None
    try:
        category: type[Warning] = _resolve_warning_category(category_)
    except ImportError:
        raise
    except Exception:
        exc_info = ExceptionInfo.from_current()
        exception_text = exc_info.getrepr(style='native')
        raise UsageError(error_template.format(error=exception_text)) from None
    if message and escape:
        message = re.escape(message)
    if module and escape:
        module = re.escape(module) + '\\Z'
    if lineno_:
        try:
            lineno = int(lineno_)
            if lineno < 0:
                raise ValueError('number is negative')
        except ValueError as e:
            raise UsageError(error_template.format(error=f'invalid lineno {lineno_!r}: {e}')) from None
    else:
        lineno = 0
    try:
        re.compile(message)
        re.compile(module)
    except re.error as e:
        raise UsageError(error_template.format(error=f'Invalid regex {e.pattern!r}: {e}')) from None
    return (action, message, category, module, lineno)

def _resolve_warning_category(category: str) -> type[Warning]:
    """
    Copied from warnings._getcategory, but changed so it lets exceptions (specially ImportErrors)
    propagate so we can get access to their tracebacks (#9218).
    """
    __tracebackhide__ = True
    if not category:
        return Warning
    if '.' not in category:
        import builtins as m
        klass = category
    else:
        module, _, klass = category.rpartition('.')
        m = importlib.import_module(module)
    cat = getattr(m, klass)
    if not issubclass(cat, Warning):
        raise UsageError(f'{cat} is not a Warning subclass')
    return cast(type[Warning], cat)

def hasplugin(self, name: str) -> bool:
    """Return whether a plugin with the given name is registered."""
    return bool(self.get_plugin(name))

def _is_in_confcutdir(self, path: pathlib.Path) -> bool:
    """Whether to consider the given path to load conftests from."""
    if self._confcutdir is None:
        return True
    return path not in self._confcutdir.parents

def import_plugin(self, modname: str, consider_entry_points: bool=False) -> None:
    """Import a plugin with ``modname``.

        If ``consider_entry_points`` is True, entry point names are also
        considered to find a plugin.
        """
    assert isinstance(modname, str), f'module name as text required, got {modname!r}'
    if self.is_blocked(modname) or self.get_plugin(modname) is not None:
        return
    importspec = '_pytest.' + modname if modname in builtin_plugins else modname
    self.rewrite_hook.mark_rewrite(importspec)
    if consider_entry_points:
        loaded = self.load_setuptools_entrypoints('pytest11', name=modname)
        if loaded:
            return
    try:
        if sys.version_info >= (3, 11):
            mod = importlib.import_module(importspec)
        else:
            __import__(importspec)
            mod = sys.modules[importspec]
    except ImportError as e:
        raise ImportError(f'Error importing plugin "{modname}": {e.args[0]}').with_traceback(e.__traceback__) from e
    except Skipped as e:
        self.skipped_plugins.append((modname, e.msg or ''))
    else:
        self.register(mod, modname)

def _mark_plugins_for_rewrite(self, hook: AssertionRewritingHook, disable_autoload: bool) -> None:
    """Given an importhook, mark for rewrite any top-level
        modules or packages in the distribution package for
        all pytest plugins."""
    self.pluginmanager.rewrite_hook = hook
    if disable_autoload:
        return
    package_files = (str(file) for dist in importlib.metadata.distributions() if any((ep.group == 'pytest11' for ep in dist.entry_points)) for file in dist.files or [])
    for name in _iter_rewritable_modules(package_files):
        hook.mark_rewrite(name)

def _decide_args(self, *, args: list[str], pyargs: bool, testpaths: list[str], invocation_dir: pathlib.Path, rootpath: pathlib.Path, warn: bool) -> tuple[list[str], ArgsSource]:
    """Decide the args (initial paths/nodeids) to use given the relevant inputs.

        :param warn: Whether can issue warnings.

        :returns: The args and the args source. Guaranteed to be non-empty.
        """
    if args:
        source = Config.ArgsSource.ARGS
        result = args
    else:
        if invocation_dir == rootpath:
            source = Config.ArgsSource.TESTPATHS
            if pyargs:
                result = testpaths
            else:
                result = []
                for path in testpaths:
                    result.extend(sorted(glob.iglob(path, recursive=True)))
                if testpaths and (not result):
                    if warn:
                        warning_text = 'No files were found in testpaths; consider removing or adjusting your testpaths configuration. Searching recursively from the current directory instead.'
                        self.issue_config_time_warning(PytestConfigWarning(warning_text), stacklevel=3)
        else:
            result = []
        if not result:
            source = Config.ArgsSource.INVOCATION_DIR
            result = [str(invocation_dir)]
    return (result, source)

def _getini_ini(self, name: str, canonical_name: str, type: str, value: str | list[str], default: Any):
    """Handle config values read in INI mode.

        In INI mode, values are stored as str or list[str] only, and coerced
        from string based on the registered type.
        """
    if type == 'paths':
        dp = self.inipath.parent if self.inipath is not None else self.invocation_params.dir
        input_values = shlex.split(value) if isinstance(value, str) else value
        return [dp / x for x in input_values]
    elif type == 'args':
        return shlex.split(value) if isinstance(value, str) else value
    elif type == 'linelist':
        if isinstance(value, str):
            return [t for t in map(lambda x: x.strip(), value.split('\n')) if t]
        else:
            return value
    elif type == 'bool':
        return _strtobool(str(value).strip())
    elif type == 'string':
        return value
    elif type == 'int':
        if not isinstance(value, str):
            raise TypeError(f'Expected an int string for option {name} of type integer, but got: {value!r}') from None
        return int(value)
    elif type == 'float':
        if not isinstance(value, str):
            raise TypeError(f'Expected a float string for option {name} of type float, but got: {value!r}') from None
        return float(value)
    else:
        return self._getini_unknown_type(name, type, value)

def _getini_toml(self, name: str, canonical_name: str, type: str, value: object, default: Any):
    """Handle TOML config values with strict type validation and no coercion.

        In TOML mode, values already have native types from TOML parsing.
        We validate types match expectations exactly, including list items.
        """
    value_type = builtins.type(value).__name__
    if type == 'paths':
        if not isinstance(value, list):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a list for type 'paths', got {value_type}: {value!r}")
        for i, item in enumerate(value):
            if not isinstance(item, str):
                item_type = builtins.type(item).__name__
                raise TypeError(f"{self.inipath}: config option '{name}' expects a list of strings, but item at index {i} is {item_type}: {item!r}")
        dp = self.inipath.parent if self.inipath is not None else self.invocation_params.dir
        return [dp / x for x in value]
    elif type in {'args', 'linelist'}:
        if not isinstance(value, list):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a list for type '{type}', got {value_type}: {value!r}")
        for i, item in enumerate(value):
            if not isinstance(item, str):
                item_type = builtins.type(item).__name__
                raise TypeError(f"{self.inipath}: config option '{name}' expects a list of strings, but item at index {i} is {item_type}: {item!r}")
        return list(value)
    elif type == 'bool':
        if not isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a bool, got {value_type}: {value!r}")
        return value
    elif type == 'int':
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects an int, got {value_type}: {value!r}")
        return value
    elif type == 'float':
        if not isinstance(value, (float, int)) or isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a float, got {value_type}: {value!r}")
        return value
    elif type == 'string':
        if not isinstance(value, str):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a string, got {value_type}: {value!r}")
        return value
    else:
        return self._getini_unknown_type(name, type, value)

@classmethod
def compile(cls, input: str) -> Expression:
    """Compile a match expression.

        :param input: The input expression - one line.

        :raises SyntaxError: If the expression is malformed.
        """
    astexpr = expression(Scanner(input))
    code = compile(astexpr, filename='<pytest match expression>', mode='eval')
    return Expression(input, code)

def get_unpacked_marks(obj: object | type, *, consider_mro: bool=True) -> list[Mark]:
    """Obtain the unpacked marks that are stored on an object.

    If obj is a class and consider_mro is true, return marks applied to
    this class and all of its super-classes in MRO order. If consider_mro
    is false, only return marks applied directly to this class.
    """
    if isinstance(obj, type):
        if not consider_mro:
            mark_lists = [obj.__dict__.get('pytestmark', [])]
        else:
            mark_lists = [x.__dict__.get('pytestmark', []) for x in reversed(obj.__mro__)]
        mark_list = []
        for item in mark_lists:
            if isinstance(item, list):
                mark_list.extend(item)
            else:
                mark_list.append(item)
    else:
        mark_attribute = getattr(obj, 'pytestmark', [])
        if mark_attribute is None:
            warnings.warn("Module defines a `__getattr__` which returns None for 'pytestmark' instead of raising AttributeError. Make sure `__getattr__` raises AttributeError for attributes it does not provide. See https://github.com/pytest-dev/pytest/issues/8265", PytestCollectionWarning, stacklevel=2)
            mark_list = []
        elif isinstance(mark_attribute, list):
            mark_list = mark_attribute
        else:
            mark_list = [mark_attribute]
    return list(normalize_mark_list(mark_list))

@classmethod
def extract_from(cls, parameterset: ParameterSet | Sequence[object] | object, force_tuple: bool=False) -> ParameterSet:
    """Extract from an object or objects.

        :param parameterset:
            A legacy style parameterset that may or may not be a tuple,
            and may or may not be wrapped into a mess of mark objects.

        :param force_tuple:
            Enforce tuple wrapping so single argument tuple values
            don't get decomposed and break tests.
        """
    if isinstance(parameterset, cls):
        return parameterset
    if force_tuple:
        return cls.param(parameterset)
    else:
        return cls(parameterset, marks=[], id=None)

def combined_with(self, other: Mark) -> Mark:
    """Return a new Mark which is a combination of this
        Mark and another Mark.

        Combines by appending args and merging kwargs.

        :param Mark other: The mark to combine with.
        :rtype: Mark
        """
    assert self.name == other.name
    param_ids_from: Mark | None = None
    if self.name == 'parametrize':
        if other._has_param_ids():
            param_ids_from = other
        elif self._has_param_ids():
            param_ids_from = self
    return Mark(self.name, self.args + other.args, dict(self.kwargs, **other.kwargs), param_ids_from=param_ids_from, _ispytest=True)

def getfslineno(obj: object) -> tuple[str | Path, int]:
    """Return source location (path, lineno) for the given object.

    If the source cannot be determined return ("", -1).

    The line number is 0-based.
    """
    obj = get_real_func(obj)
    if hasattr(obj, 'place_as'):
        obj = obj.place_as
    try:
        code = Code.from_function(obj)
    except TypeError:
        try:
            fn = inspect.getsourcefile(obj) or inspect.getfile(obj)
        except TypeError:
            return ('', -1)
        fspath = fn and absolutepath(fn) or ''
        lineno = -1
        if fspath:
            try:
                _, lineno = findsource(obj)
            except OSError:
                pass
        return (fspath, lineno)
    return (code.path, code.firstlineno)

def _byte_offset_to_character_offset(str, offset):
    """Converts a byte based offset in a string to a code-point."""
    as_utf8 = str.encode('utf-8')
    return len(as_utf8[:offset].decode('utf-8', errors='replace'))

@property
def path(self) -> Path | str:
    """Return a path object pointing to source code, or an ``str`` in
        case of ``OSError`` / non-existing file."""
    filename = inspect.getfile(self.raw)
    if not filename:
        return ''
    try:
        p = absolutepath(filename)
        if not p.exists():
            raise OSError('path check failed.')
        return p
    except OSError:
        return filename

@property
def fullsource(self) -> Source | None:
    """Return a _pytest._code.Source object for the full source file of the code."""
    full, _ = findsource(self.raw)
    return full

def source(self) -> Source:
    """Return a _pytest._code.Source object for the code object's source only."""
    return Source(self.raw)

def getargs(self, var: bool=False) -> tuple[str, ...]:
    """Return a tuple with the argument names for the code object.

        If 'var' is set True also return the names of the variable and
        keyword arguments when present.
        """
    args, varargs, varkw = inspect.getargs(self.raw)
    if not var:
        return tuple(args[:self.raw.co_argcount])
    result = list(args)
    if varargs is not None:
        result.append(varargs)
    if varkw is not None:
        result.append(varkw)
    return tuple(result)

def getargs(self, var: bool=False):
    """Return a list of tuples (name, value) for all arguments.

        If 'var' is set True, also include the variable and keyword arguments
        when present.
        """
    retval = []
    for arg in self.code.getargs(var):
        try:
            retval.append((arg, self.f_locals[arg]))
        except KeyError:
            pass
    return retval

def ishidden(self, excinfo: ExceptionInfo[BaseException] | None) -> bool:
    """Return True if the current frame has a var __tracebackhide__
        resolving to True.

        If __tracebackhide__ is a callable, it gets called with the
        ExceptionInfo instance and can decide whether to hide the traceback.

        Mostly for internal use.
        """
    tbh: bool | Callable[[ExceptionInfo[BaseException] | None], bool] = False
    for maybe_ns_dct in (self.frame.f_locals, self.frame.f_globals):
        try:
            tbh = maybe_ns_dct['__tracebackhide__']
        except Exception:
            pass
        else:
            break
    if tbh and callable(tbh):
        return tbh(excinfo)
    return tbh

def cut(self, path: os.PathLike[str] | str | None=None, lineno: int | None=None, firstlineno: int | None=None, excludepath: os.PathLike[str] | None=None) -> Traceback:
    """Return a Traceback instance wrapping part of this Traceback.

        By providing any combination of path, lineno and firstlineno, the
        first frame to start the to-be-returned traceback is determined.

        This allows cutting the first part of a Traceback instance e.g.
        for formatting reasons (removing some uninteresting bits that deal
        with handling of the exception/traceback).
        """
    path_ = None if path is None else os.fspath(path)
    excludepath_ = None if excludepath is None else os.fspath(excludepath)
    for x in self:
        code = x.frame.code
        codepath = code.path
        if path is not None and str(codepath) != path_:
            continue
        if excludepath is not None and isinstance(codepath, Path) and (excludepath_ in (str(p) for p in codepath.parents)):
            continue
        if lineno is not None and x.lineno != lineno:
            continue
        if firstlineno is not None and x.frame.code.firstlineno != firstlineno:
            continue
        return Traceback(x._rawentry)
    return self

def filter(self, excinfo_or_fn: ExceptionInfo[BaseException] | Callable[[TracebackEntry], bool], /) -> Traceback:
    """Return a Traceback instance with certain items removed.

        If the filter is an `ExceptionInfo`, removes all the ``TracebackEntry``s
        which are hidden (see ishidden() above).

        Otherwise, the filter is a function that gets a single argument, a
        ``TracebackEntry`` instance, and should return True when the item should
        be added to the ``Traceback``, False when not.
        """
    if isinstance(excinfo_or_fn, ExceptionInfo):
        fn = lambda x: not x.ishidden(excinfo_or_fn)
    else:
        fn = excinfo_or_fn
    return Traceback(filter(fn, self))

def recursionindex(self) -> int | None:
    """Return the index of the frame/TracebackEntry where recursion originates if
        appropriate, None if no recursion occurred."""
    cache: dict[tuple[Any, int, int], list[dict[str, Any]]] = {}
    for i, entry in enumerate(self):
        key = (entry.frame.code.path, id(entry.frame.code.raw), entry.lineno)
        values = cache.setdefault(key, [])
        loc = dict(entry.frame.f_locals)
        if values:
            for otherloc in values:
                if otherloc == loc:
                    return i
        values.append(loc)
    return None

def exconly(self, tryshort: bool=False) -> str:
    """Return the exception as a string.

        This is usually a single line "<exception type>: <exception str>", but
        may also include additional lines for the exception notes, and detailed
        information for SyntaxError's.

        :param tryshort:
            If true, and the exception is an AssertionError, strip
            'AssertionError: ' from the beginning.
        """

    def _get_single_subexc(eg: BaseExceptionGroup[BaseException]) -> BaseException | None:
        if len(eg.exceptions) != 1:
            return None
        if isinstance((e := eg.exceptions[0]), BaseExceptionGroup):
            return _get_single_subexc(e)
        return e
    if tryshort and isinstance(self.value, BaseExceptionGroup) and ((subexc := _get_single_subexc(self.value)) is not None):
        return f'{subexc!r} [single exception in {type(self.value).__name__}]'
    lines = format_exception_only(self.value)
    text = ''.join(lines)
    text = text.rstrip()
    if tryshort:
        if text.startswith(self._striptext):
            text = text[len(self._striptext):]
    return text

def errisinstance(self, exc: EXCEPTION_OR_MORE) -> bool:
    """Return True if the exception is an instance of exc.

        Consider using ``isinstance(excinfo.value, exc)`` instead.
        """
    return isinstance(self.value, exc)

@property
def colno(self) -> int | None:
    """Starting byte offset of the expression in the traceback entry."""
    return self.get_python_framesummary().colno

@property
def end_colno(self) -> int | None:
    """Ending byte offset of the expression in the traceback entry."""
    return self.get_python_framesummary().end_colno

def getstatementrange(self, lineno: int) -> tuple[int, int]:
    """Return (start, end) tuple which spans the minimal statement region
        which containing the given lineno."""
    if not 0 <= lineno < len(self):
        raise IndexError('lineno out of range')
    _ast, start, end = getstatementrange_ast(lineno, self)
    return (start, end)

def pformat_lines(self, object: Any, *, max_lines: int | None=None, max_chars: int | None=None) -> list[str]:
    """Pretty-print ``object`` and return its lines.

        ``max_lines`` / ``max_chars`` bound the two output dimensions
        independently; either may be ``None`` to leave that dimension
        unbounded, and with both ``None`` the whole object is formatted.
        When a bound is given the object is only formatted far enough to
        reach it, so a huge object costs O(budget) rather than O(N).

        The budget is a stopping condition, not a precise cut: formatting
        stops on the first piece of output that reaches it, so the result
        may slightly overshoot the bound.
        """
    if max_lines is None and max_chars is None:
        return self.pformat(object).splitlines()
    n_lines = 0
    n_chars = 0
    chunks: list[str] = []
    for chunk in self._format(object, 0, 0, set(), 0):
        chunks.append(chunk)
        if max_chars is not None:
            n_chars += len(chunk)
        if max_lines is not None and '\n' in chunk:
            n_lines += chunk.count('\n')
        if max_lines is not None and n_lines >= max_lines or (max_chars is not None and n_chars >= max_chars):
            break
    return ''.join(chunks).splitlines()

def safeformat(obj: object) -> str:
    """Return a pretty printed string for the given object.

    Failing __repr__ functions of user instances will be represented
    with a short exception info.
    """
    try:
        return pprint.pformat(obj)
    except Exception as exc:
        return _format_repr_exception(exc, obj)

def saferepr_unlimited(obj: object, use_ascii: bool=True) -> str:
    """Return an unlimited-size safe repr-string for the given object.

    As with saferepr, failing __repr__ functions of user instances
    will be represented with a short exception info.

    This function is a wrapper around simple repr.

    Note: a cleaner solution would be to alter ``saferepr``this way
    when maxsize=None, but that might affect some other code.
    """
    try:
        if use_ascii:
            return ascii(obj)
        return repr(obj)
    except Exception as exc:
        return _format_repr_exception(exc, obj)

@property
def width_of_current_line(self) -> int:
    """Return an estimate of the width so far in the current line."""
    return wcswidth(self._current_line)

@lru_cache(100)
def wcwidth(c: str) -> int:
    """Determine how many columns are needed to display a character in a terminal.

    Returns -1 if the character is not printable.
    Returns 0, 1 or 2 for other characters.
    """
    o = ord(c)
    if 32 <= o < 127:
        return 1
    if o == 0 or 8203 <= o <= 8207 or 8232 <= o <= 8238 or (8288 <= o <= 8291):
        return 0
    category = unicodedata.category(c)
    if category == 'Cc':
        return -1
    if category in ('Me', 'Mn'):
        return 0
    if unicodedata.east_asian_width(c) in ('F', 'W'):
        return 2
    return 1

def __init__(self, path=None, expanduser=False):
    """Initialize and return a local Path instance.

        Path can be relative to the current directory.
        If path is None it defaults to the current working directory.
        If expanduser is True, tilde-expansion is performed.
        Note that Path instances always carry an absolute path.
        Note also that passing in a local path object will simply return
        the exact same path object. Use new() to get a new copy.
        """
    if path is None:
        self.strpath = error.checked_call(os.getcwd)
    else:
        try:
            path = os.fspath(path)
        except TypeError:
            raise ValueError('can only pass None, Path instances or non-empty strings to LocalPath')
        if expanduser:
            path = os.path.expanduser(path)
        self.strpath = abspath(path)

def read_text(self, encoding):
    """Read and return a Unicode string from reading the path."""
    with self.open('r', encoding=encoding) as f:
        return f.read()

def readlines(self, cr=1):
    """Read and return a list of lines from the path. if cr is False, the
        newline will be removed from the end of each line."""
    mode = 'r'
    if not cr:
        content = self.read(mode)
        return content.split('\n')
    else:
        f = self.open(mode)
        try:
            return f.readlines()
        finally:
            f.close()

def relto(self, relpath):
    """Return a string which is the relative part of the path
        to the given 'relpath'.
        """
    if not isinstance(relpath, str | LocalPath):
        raise TypeError(f'{relpath!r}: not a string or path object')
    strrelpath = str(relpath)
    if strrelpath and strrelpath[-1] != self.sep:
        strrelpath += self.sep
    strself = self.strpath
    if sys.platform == 'win32' or getattr(os, '_name', None) == 'nt':
        if os.path.normcase(strself).startswith(os.path.normcase(strrelpath)):
            return strself[len(strrelpath):]
    elif strself.startswith(strrelpath):
        return strself[len(strrelpath):]
    return ''

def bestrelpath(self, dest):
    """Return a string which is a relative path from self
        (assumed to be a directory) to dest such that
        self.join(bestrelpath) == dest and if not such
        path can be determined return dest.
        """
    try:
        if self == dest:
            return os.curdir
        base = self.common(dest)
        if not base:
            return str(dest)
        self2base = self.relto(base)
        reldest = dest.relto(base)
        if self2base:
            n = self2base.count(self.sep) + 1
        else:
            n = 0
        lst = [os.pardir] * n
        if reldest:
            lst.append(reldest)
        target = dest.sep.join(lst)
        return target
    except AttributeError:
        return str(dest)

def common(self, other):
    """Return the common part shared with the other path
        or None if there is no common part.
        """
    last = None
    for x, y in zip(self.parts(), other.parts()):
        if x != y:
            return last
        last = x
    return last

def __add__(self, other):
    """Return new path object with 'other' added to the basename"""
    return self.new(basename=self.basename + str(other))

def samefile(self, other):
    """Return True if 'other' references the same file as 'self'."""
    other = os.fspath(other)
    if not isabs(other):
        other = abspath(other)
    if self == other:
        return True
    if not hasattr(os.path, 'samefile'):
        return False
    return error.checked_call(os.path.samefile, self.strpath, other)

def remove(self, rec=1, ignore_errors=False):
    """Remove a file or directory (or a directory tree if rec=1).
        if ignore_errors is True, errors while removing directories will
        be ignored.
        """
    if self.check(dir=1, link=0):
        if rec:
            if iswin32:
                self.chmod(448, rec=1)
            import shutil
            error.checked_call(shutil.rmtree, self.strpath, ignore_errors=ignore_errors)
        else:
            error.checked_call(os.rmdir, self.strpath)
    else:
        if iswin32:
            self.chmod(448)
        error.checked_call(os.remove, self.strpath)

def new(self, **kw):
    """Create a modified version of this path.
        the following keyword arguments modify various path parts::

          a:/some/path/to/a/file.ext
          xx                           drive
          xxxxxxxxxxxxxxxxx            dirname
                            xxxxxxxx   basename
                            xxxx       purebasename
                                 xxx   ext
        """
    obj = object.__new__(self.__class__)
    if not kw:
        obj.strpath = self.strpath
        return obj
    drive, dirname, _basename, purebasename, ext = self._getbyspec('drive,dirname,basename,purebasename,ext')
    if 'basename' in kw:
        if 'purebasename' in kw or 'ext' in kw:
            raise ValueError(f'invalid specification {kw!r}')
    else:
        pb = kw.setdefault('purebasename', purebasename)
        try:
            ext = kw['ext']
        except KeyError:
            pass
        else:
            if ext and (not ext.startswith('.')):
                ext = '.' + ext
        kw['basename'] = pb + ext
    if 'dirname' in kw and (not kw['dirname']):
        kw['dirname'] = drive
    else:
        kw.setdefault('dirname', dirname)
    kw.setdefault('sep', self.sep)
    obj.strpath = normpath('{dirname}{sep}{basename}'.format(**kw))
    return obj

def dirpath(self, *args, **kwargs):
    """Return the directory path joined with any given path arguments."""
    if not kwargs:
        path = object.__new__(self.__class__)
        path.strpath = dirname(self.strpath)
        if args:
            path = path.join(*args)
        return path
    return self.new(basename='').join(*args, **kwargs)

def open(self, mode='r', ensure=False, encoding=None):
    """Return an opened file with the given mode.

        If ensure is True, create parent directories if needed.
        """
    if ensure:
        self.dirpath().ensure(dir=1)
    if encoding:
        return error.checked_call(io.open, self.strpath, mode, encoding=encoding)
    return error.checked_call(open, self.strpath, mode)

def check(self, **kw):
    """Check a path for existence and properties.

        Without arguments, return True if the path exists, otherwise False.

        valid checkers::

            file = 1  # is a file
            file = 0  # is not a file (may not even exist)
            dir = 1  # is a dir
            link = 1  # is a link
            exists = 1  # exists

        You can specify multiple checker definitions, for example::

            path.check(file=1, link=1)  # a link pointing to a file
        """
    if not kw:
        return exists(self.strpath)
    if len(kw) == 1:
        if 'dir' in kw:
            return not kw['dir'] ^ isdir(self.strpath)
        if 'file' in kw:
            return not kw['file'] ^ isfile(self.strpath)
    if not kw:
        kw = {'exists': 1}
    return Checkers(self)._evaluate(kw)

def listdir(self, fil=None, sort=None):
    """List directory contents, possibly filter by the given fil func
        and possibly sorted.
        """
    if fil is None and sort is None:
        names = error.checked_call(os.listdir, self.strpath)
        return map_as_list(self._fastjoin, names)
    if isinstance(fil, str):
        if not self._patternchars.intersection(fil):
            child = self._fastjoin(fil)
            if exists(child.strpath):
                return [child]
            return []
        fil = FNMatcher(fil)
    names = error.checked_call(os.listdir, self.strpath)
    res = []
    for name in names:
        child = self._fastjoin(name)
        if fil is None or fil(child):
            res.append(child)
    self._sortlist(res, sort)
    return res

def copy(self, target, mode=False, stat=False):
    """Copy path to target.

        If mode is True, will copy permission from path to target.
        If stat is True, copy permission, last modification
        time, last access time, and flags from path to target.
        """
    if self.check(file=1):
        if target.check(dir=1):
            target = target.join(self.basename)
        assert self != target
        copychunked(self, target)
        if mode:
            copymode(self.strpath, target.strpath)
        if stat:
            copystat(self, target)
    else:

        def rec(p):
            return p.check(link=0)
        for x in self.visit(rec=rec):
            relpath = x.relto(self)
            newx = target.join(relpath)
            newx.dirpath().ensure(dir=1)
            if x.check(link=1):
                newx.mksymlinkto(x.readlink())
                continue
            elif x.check(file=1):
                copychunked(x, newx)
            elif x.check(dir=1):
                newx.ensure(dir=1)
            if mode:
                copymode(x.strpath, newx.strpath)
            if stat:
                copystat(x, newx)

def write(self, data, mode='w', ensure=False):
    """Write data into path.   If ensure is True create
        missing parent directories.
        """
    if ensure:
        self.dirpath().ensure(dir=1)
    if 'b' in mode:
        if not isinstance(data, bytes):
            raise ValueError('can only process bytes')
    elif not isinstance(data, str):
        if not isinstance(data, bytes):
            data = str(data)
        else:
            data = data.decode(sys.getdefaultencoding())
    f = self.open(mode)
    try:
        f.write(data)
    finally:
        f.close()

def ensure(self, *args, **kwargs):
    """Ensure that an args-joined path exists (by default as
        a file). if you specify a keyword argument 'dir=True'
        then the path is forced to be a directory path.
        """
    p = self.join(*args)
    if kwargs.get('dir', 0):
        return p._ensuredirs()
    else:
        p.dirpath()._ensuredirs()
        if not p.check(file=1):
            p.open('wb').close()
        return p

def setmtime(self, mtime=None):
    """Set modification time for the given path.  if 'mtime' is None
        (the default) then the file's mtime is set to current time.

        Note that the resolution for 'mtime' is platform dependent.
        """
    if mtime is None:
        return error.checked_call(os.utime, self.strpath, mtime)
    try:
        return error.checked_call(os.utime, self.strpath, (-1, mtime))
    except error.EINVAL:
        return error.checked_call(os.utime, self.strpath, (self.atime(), mtime))

@contextmanager
def as_cwd(self):
    """
        Return a context manager, which changes to the path's dir during the
        managed "with" context.
        On __enter__ it returns the old dir, which might be ``None``.
        """
    old = self.chdir()
    try:
        yield old
    finally:
        if old is not None:
            old.chdir()

def chmod(self, mode, rec=0):
    """Change permissions to the given mode. If mode is an
        integer it directly encodes the os-specific modes.
        if rec is True perform recursively.
        """
    if not isinstance(mode, int):
        raise TypeError(f'mode {mode!r} must be an integer')
    if rec:
        for x in self.visit(rec=rec):
            error.checked_call(os.chmod, str(x), mode)
    error.checked_call(os.chmod, self.strpath, mode)

def pypkgpath(self):
    """Return the Python package path by looking for the last
        directory upwards which still contains an __init__.py.
        Return None if a pkgpath cannot be determined.
        """
    pkgpath = None
    for parent in self.parts(reverse=True):
        if parent.isdir():
            if not parent.join('__init__.py').exists():
                break
            if not isimportable(parent.basename):
                break
            pkgpath = parent
    return pkgpath

@classmethod
def sysfind(cls, name, checker=None, paths=None):
    """Return a path object found by looking at the systems
        underlying PATH specification. If the checker is not None
        it will be invoked to filter matching paths.  If a binary
        cannot be found, None is returned
        Note: This is probably not working on plain win32 systems
        but may work on cygwin.
        """
    if isabs(name):
        p = local(name)
        if p.check(file=1):
            return p
    else:
        if paths is None:
            if iswin32:
                paths = os.environ['Path'].split(';')
                if '' not in paths and '.' not in paths:
                    paths.append('.')
                try:
                    systemroot = os.environ['SYSTEMROOT']
                except KeyError:
                    pass
                else:
                    paths = [path.replace('%SystemRoot%', systemroot) for path in paths]
            else:
                paths = os.environ['PATH'].split(':')
        tryadd = []
        if iswin32:
            tryadd += os.environ['PATHEXT'].split(os.pathsep)
        tryadd.append('')
        for x in paths:
            for addext in tryadd:
                p = local(x).join(name, abs=True) + addext
                try:
                    if p.check(file=1):
                        if checker:
                            if not checker(p):
                                continue
                        return p
                except error.EACCES:
                    pass
    return None

@classmethod
def get_temproot(cls):
    """Return the system's temporary directory
        (where tempfiles are usually created in)
        """
    import tempfile
    return local(tempfile.gettempdir())

@classmethod
def mkdtemp(cls, rootdir=None):
    """Return a Path object pointing to a fresh new temporary directory
        (which we created ourselves).
        """
    import tempfile
    if rootdir is None:
        rootdir = cls.get_temproot()
    path = error.checked_call(tempfile.mkdtemp, dir=str(rootdir))
    return cls(path)

@classmethod
def make_numbered_dir(cls, prefix='session-', rootdir=None, keep=3, lock_timeout=172800):
    """Return unique directory with a number greater than the current
        maximum one.  The number is assumed to start directly after prefix.
        if keep is true directories with a number less than (maxnum-keep)
        will be removed. If .lock files are used (lock_timeout non-zero),
        algorithm is multi-process safe.
        """
    if rootdir is None:
        rootdir = cls.get_temproot()
    nprefix = prefix.lower()

    def parse_num(path):
        """Parse the number out of a path (if it matches the prefix)"""
        nbasename = path.basename.lower()
        if nbasename.startswith(nprefix):
            try:
                return int(nbasename[len(nprefix):])
            except ValueError:
                pass

    def create_lockfile(path):
        """Exclusively create lockfile. Throws when failed"""
        mypid = os.getpid()
        lockfile = path.join('.lock')
        if hasattr(lockfile, 'mksymlinkto'):
            lockfile.mksymlinkto(str(mypid))
        else:
            fd = error.checked_call(os.open, str(lockfile), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 420)
            with os.fdopen(fd, 'w') as f:
                f.write(str(mypid))
        return lockfile

    def atexit_remove_lockfile(lockfile):
        """Ensure lockfile is removed at process exit"""
        mypid = os.getpid()

        def try_remove_lockfile():
            if os.getpid() != mypid:
                return
            try:
                lockfile.remove()
            except error.Error:
                pass
        atexit.register(try_remove_lockfile)
    lastmax = None
    while True:
        maxnum = -1
        for path in rootdir.listdir():
            num = parse_num(path)
            if num is not None:
                maxnum = max(maxnum, num)
        try:
            udir = rootdir.mkdir(prefix + str(maxnum + 1))
            if lock_timeout:
                lockfile = create_lockfile(udir)
                atexit_remove_lockfile(lockfile)
        except (error.EEXIST, error.ENOENT, error.EBUSY):
            if lastmax == maxnum:
                raise
            lastmax = maxnum
            continue
        break

    def get_mtime(path):
        """Read file modification time"""
        try:
            return path.lstat().mtime
        except error.Error:
            pass
    garbage_prefix = prefix + 'garbage-'

    def is_garbage(path):
        """Check if path denotes directory scheduled for removal"""
        bn = path.basename
        return bn.startswith(garbage_prefix)
    udir_time = get_mtime(udir)
    if keep and udir_time:
        for path in rootdir.listdir():
            num = parse_num(path)
            if num is not None and num <= maxnum - keep:
                try:
                    if lock_timeout:
                        create_lockfile(path)
                except (error.EEXIST, error.ENOENT, error.EBUSY):
                    path_time = get_mtime(path)
                    if not path_time:
                        continue
                    if abs(udir_time - path_time) < lock_timeout:
                        continue
                garbage_path = rootdir.join(garbage_prefix + str(uuid.uuid4()))
                try:
                    path.rename(garbage_path)
                    garbage_path.remove(rec=1)
                except KeyboardInterrupt:
                    raise
                except Exception:
                    pass
            if is_garbage(path):
                try:
                    path.remove(rec=1)
                except KeyboardInterrupt:
                    raise
                except Exception:
                    pass
    try:
        username = os.environ['USER']
    except KeyError:
        try:
            username = os.environ['USERNAME']
        except KeyError:
            username = 'current'
    src = str(udir)
    dest = src[:src.rfind('-')] + '-' + username
    try:
        os.unlink(dest)
    except OSError:
        pass
    try:
        os.symlink(src, dest)
    except (OSError, AttributeError, NotImplementedError):
        pass
    return udir

def chown(self, user, group, rec=0):
    """Change ownership to the given user and group.
            user and group may be specified by a number or
            by a name.  if rec is True change ownership
            recursively.
            """
    uid = getuserid(user)
    gid = getgroupid(group)
    if rec:
        for x in self.visit(rec=lambda x: x.check(link=0)):
            if x.check(link=0):
                error.checked_call(os.chown, str(x), uid, gid)
    error.checked_call(os.chown, str(self), uid, gid)

def parse_num(path):
    """Parse the number out of a path (if it matches the prefix)"""
    nbasename = path.basename.lower()
    if nbasename.startswith(nprefix):
        try:
            return int(nbasename[len(nprefix):])
        except ValueError:
            pass

