def assert_markers(self, items, **expected) -> None:
    """Assert that given items have expected marker names applied to them.
        expected should be a dict of (item name -> seq of expected marker names).

        Note: this could be moved to ``pytester`` if proven to be useful
        to other modules.
        """
    items = {x.name: x for x in items}
    for name, expected_markers in expected.items():
        markers = {m.name for m in items[name].iter_markers()}
        assert markers == set(expected_markers)

def test_backslash_in_identifier_with_string_literal() -> None:
    """Backslashes in identifiers should not cause false rejections when the
    expression also contains string literals. Regression test for a bug where
    the scanner searched the entire input for backslashes instead of only the
    current string literal value."""

    def matcher(name: str, /, **kwargs: str | int | bool | None) -> bool:
        return {'\\nfoo\\n', 'test\\case', 'mark'}.__contains__(name)
    assert evaluate('\\nfoo\\n and mark(x="y")', matcher)
    assert evaluate('mark(x="y") and \\nfoo\\n', matcher)
    assert evaluate('test\\case and mark(x="y")', matcher)

