@property
def driver_exception(self) -> Exception:
    """The original driver exception that was raised.

        This exception object will always originate from outside of
        SQLAlchemy.

        """
    if self.orig is None:
        raise ValueError('No original exception is present.  Was this EmulatedDBAPIException constructed without a driver error?')
    return self.orig

def log(self, level: int, msg: str, *args: Any, **kwargs: Any) -> None:
    """Delegate a log call to the underlying logger.

        The level here is determined by the echo
        flag as well as that of the underlying logger, and
        logger._log() is called directly.

        """
    if self.logger.manager.disable >= level:
        return
    selected_level = self._echo_map[self.echo]
    if selected_level == logging.NOTSET:
        selected_level = self.logger.getEffectiveLevel()
    if level >= selected_level:
        if STACKLEVEL:
            kwargs['stacklevel'] = kwargs.get('stacklevel', 1) + STACKLEVEL_OFFSET
        self.logger._log(level, msg, args, **kwargs)

@property
def exceptions_module(self) -> types.ModuleType:
    """Return the module which we think will have the exception hierarchy.

        For an asyncio driver that wraps a plain DBAPI like aiomysql,
        aioodbc, aiosqlite, etc. these exceptions will be from the
        dbapi_module.  For a "pure" driver like asyncpg these will come
        from the driver module.

        .. versionadded:: 2.1

        """
    if self.dbapi_module is not None:
        return self.dbapi_module
    else:
        return self.driver

def _terminate_handled_exceptions(self) -> Tuple[Type[BaseException], ...]:
    """Returns the exceptions that should be handled when
        calling _graceful_close.
        """
    return (asyncio.TimeoutError, asyncio.CancelledError, OSError)

def _auto_fn(name: str) -> Optional[Callable[[], Type[Dialect]]]:
    """default dialect importer.

    plugs into the :class:`.PluginLoader`
    as a first-hit system.

    """
    if '.' in name:
        dialect, driver = name.split('.')
    else:
        dialect = name
        driver = 'base'
    try:
        if dialect == 'mariadb':
            module: Any = __import__('sqlalchemy.dialects.mysql.mariadb').dialects.mysql.mariadb
            return module.loader(driver)
        else:
            module = __import__('sqlalchemy.dialects.%s' % (dialect,)).dialects
            module = getattr(module, dialect)
    except ImportError:
        return None
    if hasattr(module, driver):
        module = getattr(module, driver)
        return lambda: module.dialect
    else:
        return None

def _row_limit_clause(self, select, **kw):
    """MSSQL 2012 supports OFFSET/FETCH operators
        Use it instead subquery with row_number

        """
    if self.dialect._supports_offset_fetch and (not self._use_top(select)):
        self._check_can_use_fetch_limit(select)
        return self.fetch_clause(select, fetch_clause=self._get_limit_or_fetch(select), require_offset=True, **kw)
    else:
        return ''

def visit_binary(self, binary, **kwargs):
    """Move bind parameters to the right-hand side of an operator, where
        possible.

        """
    if isinstance(binary.left, expression.BindParameter) and binary.operator == operator.eq and (not isinstance(binary.right, expression.BindParameter)):
        return self.process(expression.BinaryExpression(binary.right, binary.left, binary.operator), **kwargs)
    return super().visit_binary(binary, **kwargs)

def delete_table_clause(self, delete_stmt, from_table, extra_froms, **kw):
    """If we have extra froms make sure we render any alias as hint."""
    ashint = False
    if extra_froms:
        ashint = True
    return from_table._compiler_dispatch(self, asfrom=True, iscrud=True, ashint=ashint, **kw)

def delete_extra_from_clause(self, delete_stmt, from_table, extra_froms, from_hints, **kw):
    """Render the DELETE .. FROM clause specific to MSSQL.

        Yes, it has the FROM keyword twice.

        """
    return 'FROM ' + ', '.join((t._compiler_dispatch(self, asfrom=True, fromhints=from_hints, **kw) for t in [from_table] + extra_froms))

def render_literal_value(self, value, type_):
    """
        For date and datetime values, convert to a string
        format acceptable to MSSQL. That seems to be the
        so-called ODBC canonical date format which looks
        like this:

            yyyy-mm-dd hh:mi:ss.mmm(24h)

        For other data types, call the base class implementation.
        """
    if issubclass(type(value), datetime.date):
        return "'" + str(value) + "'"
    else:
        return super().render_literal_value(value, type_)

@staticmethod
def _multi_name_map(filter_names):
    """Build a case-insensitive ``server_name -> user_name`` mapper.

        MSSQL object names are case-insensitive under the default
        collation, so a user may pass ``"sOmEtAbLe"`` for a table
        physically stored as ``"SomeTable"``. The bulk SQL returns the
        server-side casing, but result keys must use the user-supplied
        casing so that downstream code (e.g.
        :meth:`.Inspector.reflect_table`) can find the entry.

        Returns a callable ``(server_name) -> user_name``. When
        ``filter_names`` is empty/None, returns identity.
        """
    if not filter_names:
        return lambda n: n
    lookup = {n.lower(): n for n in filter_names}
    return lambda n: lookup.get(n.lower(), n)

def _resolve_temp_names(self, connection, temp_names):
    """Resolve user-facing temp names (``#foo``) to their mangled
        tempdb names, grouped by owner.

        Returns ``(resolved_by_owner, temp_name_map)``:

        * ``resolved_by_owner`` -- ``{owner: [mangled_name, ...]}``,
          one bulk query per owner (typically just ``'dbo'``).
        * ``temp_name_map`` -- a function that maps mangled names back
          to the user-supplied name.

        Names that don't resolve (no matching temp table in tempdb) are
        silently dropped. The single-table reflection wrappers handle
        the resulting absence by raising :exc:`.NoSuchTableError` via
        :meth:`._value_or_raise`.
        """
    resolved_by_owner = {}
    original_by_mangled = {}
    for name in temp_names:
        try:
            temp_owner, mangled = self._get_internal_temp_table_name(connection, name)
        except exc.NoSuchTableError:
            continue
        resolved_by_owner.setdefault(temp_owner, []).append(mangled)
        original_by_mangled[mangled] = name

    def temp_name_map(server_name):
        return original_by_mangled.get(server_name, server_name)
    return (resolved_by_owner, temp_name_map)

def _fetch_multi_pk_constraint(self, connection, owner, names, schema, name_map, result, exec_opts):
    """Execute the unified pk_constraint select for one catalog pass.

        Used by :meth:`.get_multi_pk_constraint` for both the main DB
        pass and the tempdb pass (with ``schema_translate_map`` set).
        """
    s = self._pk_constraint_select()
    rp = connection.execute(s, {'owner': owner, 'filter_names': names}, execution_options=exec_opts)
    for row in rp.mappings():
        table_name = name_map(row['table_name'])
        key = (schema, table_name)
        if key not in result:
            result[key] = {'constrained_columns': [], 'name': row['constraint_name'], 'dialect_options': {'mssql_clustered': row['index_type'] == 1}}
        result[key]['constrained_columns'].append(row['column_name'])
    for n in names:
        key = (schema, name_map(n))
        if key not in result:
            result[key] = ReflectionDefaults.pk_constraint()

def _fetch_multi_foreign_keys(self, connection, dbname, owner, names, schema, name_map, final):
    """Execute the unified FK query for the main-DB pass.

        Uses the _fk_query_sql sql text, restricted to the provided owner and
        IN-list of names. Groups result rows by table and constraint
        name into the final dict.
        """
    rp = connection.execute(sql.text(self._fk_query_sql(fk_info_where='ischema_key_col.table_schema = :owner\n      AND ischema_key_col.table_name IN :filter_names', extra_cols='fk_info.table_name,')).bindparams(sql.bindparam('owner', owner, ischema.CoerceUnicode()), sql.bindparam('filter_names', names, expanding=True)).columns(constraint_schema=sqltypes.Unicode(), constraint_name=sqltypes.Unicode(), table_name=sqltypes.Unicode(), constrained_column=sqltypes.Unicode(), referred_table_schema=sqltypes.Unicode(), referred_table_name=sqltypes.Unicode(), referred_column=sqltypes.Unicode()))
    grouped = {}
    for r in rp.all():
        table_name, _, rfknm, _, scol, rschema, rtbl, rcol, _, fkuprule, fkdelrule = r
        key = (schema, name_map(table_name))
        if key not in grouped:
            grouped[key] = util.defaultdict(lambda: {'name': None, 'constrained_columns': [], 'referred_schema': None, 'referred_table': None, 'referred_columns': [], 'options': {}})
        rec = grouped[key][rfknm]
        rec['name'] = rfknm
        if fkuprule != 'NO ACTION':
            rec['options']['onupdate'] = fkuprule
        if fkdelrule != 'NO ACTION':
            rec['options']['ondelete'] = fkdelrule
        if not rec['referred_table']:
            rec['referred_table'] = rtbl
            if schema is not None or owner != rschema:
                if dbname:
                    rschema = dbname + '.' + rschema
                rec['referred_schema'] = rschema
        rec['constrained_columns'].append(scol)
        rec['referred_columns'].append(rcol)
    for key, fk_dict in grouped.items():
        final[key] = list(fk_dict.values())
    for n in names:
        key = (schema, name_map(n))
        if key not in final:
            final[key] = ReflectionDefaults.foreign_keys()

def _fetch_multi_indexes(self, connection, owner, names, schema, name_map, result, exec_opts):
    """Execute the unified indexes queries for one catalog pass.

        Runs two Core sys.* selects (index metadata + index columns),
        grouped by table. Used for both the main-DB pass and the
        tempdb pass (with ``schema_translate_map={"sys": "tempdb.sys"}``
        applied).
        """
    meta_q = self._indexes_metadata_select()
    rp = connection.execute(meta_q, {'owner': owner, 'filter_names': names}, execution_options=exec_opts)
    indexes_by_table = {}
    for row in rp.mappings():
        tname = name_map(row['table_name'])
        if tname not in indexes_by_table:
            indexes_by_table[tname] = {}
        current = {'name': row['name'], 'unique': row['is_unique'] == 1, 'column_names': [], 'dialect_options': {'mssql_include': []}}
        do = current['dialect_options']
        index_type = row['type']
        if index_type in {1, 2}:
            do['mssql_clustered'] = index_type == 1
        if index_type in {5, 6}:
            do['mssql_clustered'] = index_type == 5
            do['mssql_columnstore'] = True
        if row['filter_definition'] is not None:
            do['mssql_where'] = row['filter_definition']
        indexes_by_table[tname][row['index_id']] = current
    cols_q = self._indexes_columns_select()
    rp2 = connection.execute(cols_q, {'owner': owner, 'filter_names': names}, execution_options=exec_opts)
    for row in rp2.mappings():
        tname = name_map(row['table_name'])
        idx_id = row['index_id']
        if tname not in indexes_by_table:
            continue
        if idx_id not in indexes_by_table[tname]:
            continue
        index_def = indexes_by_table[tname][idx_id]
        do = index_def['dialect_options']
        is_colstore = do.get('mssql_columnstore')
        is_clustered = do.get('mssql_clustered')
        if not (is_colstore and is_clustered):
            if row['is_included_column'] and (not is_colstore):
                do['mssql_include'].append(row['name'])
            else:
                index_def['column_names'].append(row['name'])
    for tname, idx_dict in indexes_by_table.items():
        result[schema, tname] = list(idx_dict.values())
    for n in names:
        key = (schema, name_map(n))
        if key not in result:
            result[key] = ReflectionDefaults.indexes()

def _fetch_multi_table_comment(self, connection, owner, names, schema, name_map, result, exec_opts):
    """Execute the unified table comment query for one catalog pass.

        Core sys.* select so ``schema_translate_map`` actually rewrites
        the catalog reference for the tempdb pass.
        """
    q = self._table_comment_select()
    rp = connection.execute(q, {'owner': owner, 'filter_names': names}, execution_options=exec_opts)
    for row in rp.mappings():
        table_name = name_map(row['table_name'])
        comment = row['comment']
        result[schema, table_name] = {'text': comment} if comment else {'text': None}
    for n in names:
        key = (schema, name_map(n))
        if key not in result:
            result[key] = ReflectionDefaults.table_comment()

