def default_from(self) -> str:
    """Called when a ``SELECT`` statement has no froms,
        and no ``FROM`` clause is to be appended.

        """
    if self.stack:
        stmt = self.stack[-1]['selectable']
        if stmt._where_criteria:
            return ' FROM DUAL'
    return ''

def get_select_precolumns(self, select: selectable.Select[Any], **kw: Any) -> str:
    """Add special MySQL keywords in place of DISTINCT.

        .. deprecated:: 1.4 This usage is deprecated.
           :meth:`_expression.Select.prefix_with` should be used for special
           keywords at the start of a SELECT.

        """
    if isinstance(select._distinct, str):
        util.warn_deprecated("Sending string values for 'distinct' is deprecated in the MySQL dialect and will be removed in a future release.  Please use :meth:`.Select.prefix_with` for special keywords at the start of a SELECT statement", version='1.4')
        return select._distinct.upper() + ' '
    return super().get_select_precolumns(select, **kw)

def delete_table_clause(self, delete_stmt: Delete, from_table: _DMLTableElement, extra_froms: list[selectable.FromClause], **kw: Any) -> str:
    """If we have extra froms make sure we render any alias as hint."""
    ashint = False
    if extra_froms:
        ashint = True
    return from_table._compiler_dispatch(self, asfrom=True, iscrud=True, ashint=ashint, **kw)

def _extend_string(self, type_: _StringType, defaults: dict[str, Any], spec: str) -> str:
    """Extend a string-type declaration with standard SQL CHARACTER SET /
        COLLATE annotations and MySQL specific extensions.

        """

    def attr(name: str) -> Any:
        return getattr(type_, name, defaults.get(name))
    if attr('charset'):
        charset = 'CHARACTER SET %s' % attr('charset')
    elif attr('ascii'):
        charset = 'ASCII'
    elif attr('unicode'):
        charset = 'UNICODE'
    else:
        charset = None
    if attr('collation'):
        collation = 'COLLATE %s' % type_.collation
    elif attr('binary'):
        collation = 'BINARY'
    else:
        collation = None
    if attr('national'):
        return ' '.join([c for c in ('NATIONAL', spec, collation) if c is not None])
    return ' '.join([c for c in (spec, charset, collation) if c is not None])

def _compat_fetchone(self, rp: CursorResult[Unpack[TupleAny]], charset: Optional[str]=None) -> Union[Row[Unpack[TupleAny]], None, _DecodingRow]:
    """Proxy a result row to smooth over MySQL-Python driver
        inconsistencies."""
    row = rp.fetchone()
    if row:
        return _DecodingRow(row, charset)
    else:
        return None

def _compat_first(self, rp: CursorResult[Unpack[TupleAny]], charset: Optional[str]=None) -> Optional[_DecodingRow]:
    """Proxy a result row to smooth over MySQL-Python driver
        inconsistencies."""
    row = rp.first()
    if row:
        return _DecodingRow(row, charset)
    else:
        return None

@util.memoized_property
def _tabledef_parser(self) -> _reflection.MySQLTableDefinitionParser:
    """return the MySQLTableDefinitionParser, generate if needed.

        The deferred creation ensures that the dialect has
        retrieved server version information first.

        """
    preparer = self.identifier_preparer
    return _reflection.MySQLTableDefinitionParser(self, preparer)

def _detect_casing(self, connection: Connection) -> int:
    """Sniff out identifier case sensitivity.

        Cached per-connection. This value can not change without a server
        restart.

        """
    setting = self._fetch_setting(connection, 'lower_case_table_names')
    if setting is None:
        cs = 0
    elif setting == 'OFF':
        cs = 0
    elif setting == 'ON':
        cs = 1
    else:
        cs = int(setting)
    self._casing = cs
    return cs

def _detect_collations(self, connection: Connection) -> dict[str, str]:
    """Pull the active COLLATIONS list from the server.

        Cached per-connection.
        """
    collations = {}
    charset = self._connection_charset
    rs = connection.exec_driver_sql('SHOW COLLATION')
    for row in self._compat_fetchall(rs, charset):
        collations[row[0]] = row[1]
    return collations

def result_processor(self, dialect: Dialect, coltype: object) -> Optional[_ResultProcessorType[Any]]:
    """Convert MySQL's 64 bit, variable length binary string to a long."""

    def process(value: Optional[Iterable[int]]) -> Optional[int]:
        if value is not None:
            v = 0
            for i in iter(value):
                v = v << 8 | i
            return v
        return value
    return process

def _detect_charset(self, connection: Connection) -> str:
    """Sniff out the character set in use for connection results."""
    try:
        cset_name: Callable[[], str] = connection.connection.character_set_name
    except AttributeError:
        util.warn("No 'character_set_name' can be detected with this MySQL-Python version; please upgrade to a recent version of MySQL-Python.  Assuming latin1.")
        return 'latin1'
    else:
        return cset_name()

