def _detect_charset(self, connection: Connection) -> str:
    """Sniff out the character set in use for connection results."""
    self._connection_charset = None
    try:
        value = self._fetch_setting(connection, 'character_set_client')
        if value:
            return value
    except exc.DBAPIError:
        pass
    util.warn('Could not detect the connection character set.  Assuming latin1.')
    return 'latin1'

def _parse_constraints(self, line: str) -> Union[tuple[None, str], tuple[Literal['partition'], str], tuple[Literal['ck_constraint', 'fk_constraint', 'key'], dict[str, str]]]:
    """Parse a KEY or CONSTRAINT line.

        :param line: A line of SHOW CREATE TABLE output
        """
    m = self._re_key.match(line)
    if m:
        spec = m.groupdict()
        spec['columns'] = self._parse_keyexprs(spec['columns'])
        if spec['version_sql']:
            m2 = self._re_key_version_sql.match(spec['version_sql'])
            if m2 and m2.groupdict()['parser']:
                spec['parser'] = m2.groupdict()['parser']
        if spec['parser']:
            spec['parser'] = self.preparer.unformat_identifiers(spec['parser'])[0]
        return ('key', spec)
    m = self._re_fk_constraint.match(line)
    if m:
        spec = m.groupdict()
        spec['table'] = self.preparer.unformat_identifiers(spec['table'])
        spec['local'] = [c[0] for c in self._parse_keyexprs(spec['local'])]
        spec['foreign'] = [c[0] for c in self._parse_keyexprs(spec['foreign'])]
        return ('fk_constraint', spec)
    m = self._re_ck_constraint.match(line)
    if m:
        spec = m.groupdict()
        return ('ck_constraint', spec)
    m = self._re_partition.match(line)
    if m:
        return ('partition', line)
    return (None, line)

def _parse_table_options(self, line: str, state: ReflectedState) -> None:
    """Build a dictionary of all reflected table-level options.

        :param line: The final line of SHOW CREATE TABLE output.
        """
    options = {}
    if line and line != ')':
        rest_of_line = line
        for regex, cleanup in self._pr_options:
            m = regex.search(rest_of_line)
            if not m:
                continue
            directive, value = (m.group('directive'), m.group('val'))
            if cleanup:
                value = cleanup(value)
            options[directive.lower()] = value
            rest_of_line = regex.sub('', rest_of_line)
    for nope in ('auto_increment', 'data directory', 'index directory'):
        options.pop(nope, None)
    for opt, val in options.items():
        state.table_options['%s_%s' % (self.dialect.name, opt)] = val

def _parse_column(self, line: str, state: ReflectedState) -> None:
    """Extract column details.

        Falls back to a 'minimal support' variant if full parse fails.

        :param line: Any column-bearing line from SHOW CREATE TABLE
        """
    spec = None
    m = self._re_column.match(line)
    if m:
        spec = m.groupdict()
        spec['full'] = True
    else:
        m = self._re_column_loose.match(line)
        if m:
            spec = m.groupdict()
            spec['full'] = False
    if not spec:
        util.warn('Unknown column definition %r' % line)
        return
    if not spec['full']:
        util.warn('Incomplete reflection of column definition %r' % line)
    name, type_, args = (spec['name'], spec['coltype'], spec['arg'])
    try:
        col_type = self.dialect.ischema_names[type_]
    except KeyError:
        util.warn("Did not recognize type '%s' of column '%s'" % (type_, name))
        col_type = sqltypes.NullType
    if args is None or args == '':
        type_args = []
    elif args[0] == "'" and args[-1] == "'":
        type_args = self._re_csv_str.findall(args)
    else:
        type_args = [int(v) for v in self._re_csv_int.findall(args)]
    type_kw = {}
    if issubclass(col_type, (DATETIME, TIME, TIMESTAMP)):
        if type_args:
            type_kw['fsp'] = type_args.pop(0)
    for kw in ('unsigned', 'zerofill'):
        if spec.get(kw, False):
            type_kw[kw] = True
    for kw in ('charset', 'collate'):
        if spec.get(kw, False):
            type_kw[kw] = spec[kw]
    if issubclass(col_type, (ENUM, SET)):
        type_args = _strip_values(type_args)
        if issubclass(col_type, SET) and '' in type_args:
            type_kw['retrieve_as_bitwise'] = True
    type_instance = col_type(*type_args, **type_kw)
    col_kw: dict[str, Any] = {}
    col_kw['nullable'] = True
    if spec.get('notnull', False) == 'NOT NULL':
        col_kw['nullable'] = False
    if spec.get('notnull_generated', False) == 'NOT NULL':
        col_kw['nullable'] = False
    if spec.get('autoincr', False):
        col_kw['autoincrement'] = True
    elif issubclass(col_type, sqltypes.Integer):
        col_kw['autoincrement'] = False
    default = spec.get('default', None)
    if default == 'NULL':
        default = None
    comment = spec.get('comment', None)
    if comment is not None:
        comment = cleanup_text(comment)
    sqltext = spec.get('generated')
    if sqltext is not None:
        computed = dict(sqltext=sqltext)
        persisted = spec.get('persistence')
        if persisted is not None:
            computed['persisted'] = persisted == 'STORED'
        col_kw['computed'] = computed
    col_d = dict(name=name, type=type_instance, default=default, comment=comment)
    col_d.update(col_kw)
    state.columns.append(col_d)

def _describe_to_create(self, table_name: str, columns: Sequence[tuple[str, str, str, str, str, str]]) -> str:
    """Re-format DESCRIBE output as a SHOW CREATE TABLE string.

        DESCRIBE is a much simpler reflection and is sufficient for
        reflecting views for runtime use.  This method formats DDL
        for columns only- keys are omitted.

        :param columns: A sequence of DESCRIBE or SHOW COLUMNS 6-tuples.
          SHOW FULL COLUMNS FROM rows must be rearranged for use with
          this function.
        """
    buffer = []
    for row in columns:
        name, col_type, nullable, default, extra = (row[i] for i in (0, 1, 2, 4, 5))
        line = [' ']
        line.append(self.preparer.quote_identifier(name))
        line.append(col_type)
        if not nullable:
            line.append('NOT NULL')
        if default:
            if 'auto_increment' in default:
                pass
            elif col_type.startswith('timestamp') and default.startswith('C'):
                line.append('DEFAULT')
                line.append(default)
            elif default == 'NULL':
                line.append('DEFAULT')
                line.append(default)
            else:
                line.append('DEFAULT')
                line.append("'%s'" % default.replace("'", "''"))
        if extra:
            line.append(extra)
        buffer.append(' '.join(line))
    return ''.join(['CREATE TABLE %s (\n' % self.preparer.quote_identifier(table_name), ',\n'.join(buffer), '\n) '])

def result_processor(self, dialect: MySQLDialect, coltype: object) -> Optional[_ResultProcessorType[Any]]:
    """Convert a MySQL's 64 bit, variable length binary string to a
        long."""
    if dialect.supports_native_bit:
        return None

    def process(value: Optional[Iterable[int]]) -> Optional[int]:
        if value is not None:
            v = 0
            for i in value:
                v = v << 8 | i
            return v
        return value
    return process

def _row_limit_clause(self, select, **kw):
    """Oracle Database 12c supports OFFSET/FETCH operators
        Use it instead subquery with row_number

        """
    if select._fetch_clause is not None or not self.dialect._supports_offset_fetch:
        return super()._row_limit_clause(select, use_literal_execute_for_simple_int=True, **kw)
    else:
        return self.fetch_clause(select, fetch_clause=self._get_limit_or_fetch(select), use_literal_execute_for_simple_int=True, **kw)

@reflection.cache
def has_table(self, connection, table_name, schema=None, dblink=None, **kw):
    """Supported kw arguments are: ``dblink`` to reflect via a db link."""
    self._ensure_has_table_connection(connection)
    if not schema:
        schema = self.default_schema_name
    params = {'table_name': self.denormalize_name(table_name), 'owner': self.denormalize_schema_name(schema)}
    cursor = self._execute_reflection(connection, self._has_table_query, dblink, returns_long=False, params=params)
    return bool(cursor.scalar())

@reflection.cache
def has_sequence(self, connection, sequence_name, schema=None, dblink=None, **kw):
    """Supported kw arguments are: ``dblink`` to reflect via a db link."""
    if not schema:
        schema = self.default_schema_name
    query = select(dictionary.all_sequences.c.sequence_name).where(dictionary.all_sequences.c.sequence_name == self.denormalize_schema_name(sequence_name), dictionary.all_sequences.c.sequence_owner == self.denormalize_schema_name(schema))
    cursor = self._execute_reflection(connection, query, dblink, returns_long=False)
    return bool(cursor.scalar())

@reflection.cache
def get_schema_names(self, connection, dblink=None, **kw):
    """Supported kw arguments are: ``dblink`` to reflect via a db link."""
    query = select(dictionary.all_users.c.username).order_by(dictionary.all_users.c.username)
    result = self._execute_reflection(connection, query, dblink, returns_long=False).scalars()
