@classmethod
def _adapt_string_for_cast(cls, type_: sqltypes.String) -> 'VARCHAR2':
    """Adapt a String type for use in CAST expressions.

        Oracle requires a length for VARCHAR2 in CAST expressions.
        If no length is specified, we default to 4000 (max for VARCHAR2).
        """
    type_ = sqltypes.to_instance(type_)
    if isinstance(type_, VARCHAR2):
        return type_
    elif isinstance(type_, VARCHAR):
        return VARCHAR2(length=type_.length or 4000, collation=type_.collation)
    else:
        return VARCHAR2(length=type_.length or 4000)

def _cached_bind_processor(self, dialect):
    """
        Converts a Python-side SparseVector instance into an
        oracledb.SparseVectormor a compatible array format before
        binding it to the database.
        """

    def process(value):
        if value is None or isinstance(value, array.array):
            return value
        elif isinstance(value, list):
            typecode = self._array_typecode(self.storage_format)
            value = array.array(typecode, value)
            return value
        elif isinstance(value, SparseVector):
            return dialect.dbapi.SparseVector(value.num_dimensions, value.indices, value.values)
        else:
            raise TypeError('\n                    Invalid input for VECTOR: expected a list, an array.array,\n                    or a SparseVector object.\n                    ')
    return process

def _cached_result_processor(self, dialect, coltype):
    """
        Converts database-returned values into Python-native representations.
        If the value is an oracledb.SparseVector, it is converted into the
        SQLAlchemy-side SparseVector class.
        If the value is a array.array, it is converted to a plain Python list.

        """

    def process(value):
        if value is None:
            return None
        elif isinstance(value, array.array):
            return list(value)
        elif isinstance(value, dialect.dbapi.SparseVector):
            return SparseVector(num_dimensions=value.num_dimensions, indices=value.indices, values=value.values)
    return process

def contained_by(self, other: typing_Any) -> ColumnElement[bool]:
    """Boolean expression.  Test if elements are a proper subset of the
            elements of the argument array expression.
            """
    return self.operate(CONTAINED_BY, other, result_type=sqltypes.Boolean)

def overlap(self, other: typing_Any) -> ColumnElement[bool]:
    """Boolean expression.  Test if array has elements in common with
            an argument array expression.
            """
    return self.operate(OVERLAP, other, result_type=sqltypes.Boolean)

async def setup_asyncpg_jsonb_codec(self, conn):
    """set up JSONB codec for asyncpg.

        This occurs for all new connections and
        can be overridden by third party dialects.

        .. versionadded:: 1.4.27

        """
    asyncpg_connection = conn._connection

    def _jsonb_encoder(str_value):
        return b'\x01' + str_value.encode()
    deserializer = self._json_deserializer or _py_json.loads

    def _jsonb_decoder(bin_value):
        return deserializer(bin_value[1:].decode())
    await asyncpg_connection.set_type_codec('jsonb', encoder=_jsonb_encoder, decoder=_jsonb_decoder, schema='pg_catalog', format='binary')

def _reflect_type(self, format_type: Optional[str], named_type_loader: _NamedTypeLoader, type_description: str, collation: Optional[str]) -> sqltypes.TypeEngine[Any]:
    """
        Attempts to reconstruct a column type defined in ischema_names based
        on the information available in the format_type.

        If the `format_type` cannot be associated with a known `ischema_names`,
        it is treated as a reference to a known PostgreSQL named `ENUM` or
        `DOMAIN` type.
        """
    type_description = type_description or 'unknown type'
    if format_type is None:
        util.warn('PostgreSQL format_type() returned NULL for %s' % type_description)
        return sqltypes.NULLTYPE
    attype_args_match = self._format_type_args_pattern.search(format_type)
    if attype_args_match and attype_args_match.group(1):
        attype_args = self._format_type_args_delim.split(attype_args_match.group(1))
    else:
        attype_args = ()
    match_array_dim = self._format_array_spec_pattern.search(format_type)
    array_dim = len(match_array_dim.group(1) or '') // 2
    attype = self._format_type_args_pattern.sub('', format_type)
    attype = self._format_array_spec_pattern.sub('', attype)
    schema_type = self.ischema_names.get(attype.lower(), None)
    args, kwargs = ((), {})
    if attype == 'numeric':
        if len(attype_args) == 2:
            precision, scale = map(int, attype_args)
            args = (precision, scale)
    elif attype == 'double precision':
        args = (53,)
    elif attype == 'integer':
        args = ()
    elif attype in ('timestamp with time zone', 'time with time zone'):
        kwargs['timezone'] = True
        if len(attype_args) == 1:
            kwargs['precision'] = int(attype_args[0])
    elif attype in ('timestamp without time zone', 'time without time zone', 'time'):
        kwargs['timezone'] = False
        if len(attype_args) == 1:
            kwargs['precision'] = int(attype_args[0])
    elif attype == 'bit varying':
        kwargs['varying'] = True
        if len(attype_args) == 1:
            charlen = int(attype_args[0])
            args = (charlen,)
    elif attype == 'interval' or attype.startswith('interval '):
        schema_type = INTERVAL
        field_match = re.match('interval (.+)', attype)
        if field_match:
            kwargs['fields'] = field_match.group(1)
        if len(attype_args) == 1:
            kwargs['precision'] = int(attype_args[0])
    else:
        enum_or_domain_key = tuple(util.quoted_token_parser(attype))
        if schema_type is None and enum_or_domain_key in named_type_loader.enums:
            schema_type = ENUM
            enum = named_type_loader.enums[enum_or_domain_key]
            kwargs['name'] = enum['name']
            if not enum['visible']:
                kwargs['schema'] = enum['schema']
            args = tuple(enum['labels'])
        elif schema_type is None and enum_or_domain_key in named_type_loader.domains:
            schema_type = DOMAIN
            domain = named_type_loader.domains[enum_or_domain_key]
            data_type = self._reflect_type(domain['type'], named_type_loader, type_description="DOMAIN '%s'" % domain['name'], collation=domain['collation'])
            args = (domain['name'], data_type)
            kwargs['collation'] = domain['collation']
            kwargs['default'] = domain['default']
            kwargs['not_null'] = not domain['nullable']
            kwargs['create_type'] = False
            if domain['constraints']:
                check_constraint = domain['constraints'][0]
                kwargs['constraint_name'] = check_constraint['name']
                kwargs['check'] = check_constraint['check']
            if not domain['visible']:
                kwargs['schema'] = domain['schema']
        else:
            try:
                charlen = int(attype_args[0])
                args = (charlen, *attype_args[1:])
            except (ValueError, IndexError):
                args = attype_args
    if not schema_type:
        util.warn("Did not recognize type '%s' of %s" % (attype, type_description))
        return sqltypes.NULLTYPE
    if collation is not None:
        kwargs['collation'] = collation
    data_type = schema_type(*args, **kwargs)
    if array_dim >= 1:
        data_type = _array.ARRAY(data_type)
    return data_type

@classmethod
def from_int(cls, value: int, length: int) -> BitString:
    """Returns a BitString consisting of the bits in the integer ``value``.
        A ``ValueError`` is raised if ``value`` is not a non-negative integer.

        If the provided ``value`` can not be represented in a bit string
        of at most ``length``, a ``ValueError`` will be raised. The bitstring
        will be padded on the left by ``'0'`` to bits to produce a
        bitstring of the desired length.
        """
    if value < 0:
        raise ValueError('value must be non-negative')
    if length < 0:
        raise ValueError('length must be non-negative')
    template_str = f'{{0:0{length}b}}' if length > 0 else ''
    r = template_str.format(value)
    if length == 0 and value > 0 or len(r) > length:
        raise ValueError(f'Cannot encode {value} as a BitString of length {length}')
    return cls(r)

def get_bit(self, index: int) -> Literal['0', '1']:
    """Returns the value of the flag at the given
        index::

            BitString("0101").get_flag(4) == "1"
        """
    return cast(Literal['0', '1'], super().__getitem__(index))

def set_bit(self, index: int, value: bool | int | Literal['0', '1']) -> BitString:
    """Set the bit at index to the given value.

        If value is an int, then it is considered to be '1' iff nonzero.
        """
    if index < 0 or index >= len(self):
        raise IndexError('BitString index out of range')
    if isinstance(value, (bool, int)):
        value = '1' if value else '0'
    if self.get_bit(index) == value:
        return self
    return BitString(''.join([self[:index], value, self[index + 1:]]), False)

def lstrip(self, char: str | None=None) -> BitString:
    """Returns a copy of the BitString with leading characters removed.

        If omitted or None, 'chars' defaults '0'::

            BitString("00010101000").lstrip() == BitString("00010101")
            BitString("11110101111").lstrip("1") == BitString("1111010")
        """
    if char is None:
        char = '0'
    return BitString(super().lstrip(char), False)

def rstrip(self, char: str | None='0') -> BitString:
    """Returns a copy of the BitString with trailing characters removed.

        If omitted or None, ``'char'`` defaults to "0"::

            BitString("00010101000").rstrip() == BitString("10101000")
            BitString("11110101111").rstrip("1") == BitString("10101111")
        """
    if char is None:
        char = '0'
    return BitString(super().rstrip(char), False)

def strip(self, char: str | None='0') -> BitString:
    """Returns a copy of the BitString with both leading and trailing
        characters removed.
        If omitted or None, ``'char'`` defaults to ``"0"``::

            BitString("00010101000").rstrip() == BitString("10101")
            BitString("11110101111").rstrip("1") == BitString("1010")
        """
    if char is None:
        char = '0'
    return BitString(super().strip(char))

def __lshift__(self, amount: int) -> BitString:
    """Shifts each the bitstring to the left by the given amount.
        String length is preserved::

            BitString("000101") << 1 == BitString("001010")
        """
    return BitString(''.join([self, *('0' for _ in range(amount))])[-len(self):], False)

def __rshift__(self, amount: int) -> BitString:
    """Shifts each bit in the bitstring to the right by the given amount.
        String length is preserved::

            BitString("101") >> 1 == BitString("010")
        """
    return BitString(self[:-amount], False).zfill(width=len(self))

def __invert__(self) -> BitString:
    """Inverts (~) each bit in the
        bitstring::

            ~BitString("01010") == BitString("10101")
        """
    return BitString(''.join(('1' if x == '0' else '0' for x in self)))

def __and__(self, o: str) -> BitString:
    """Performs a bitwise and (``&``) with the given operand.
        A ``ValueError`` is raised if the operand is not the same length.

        e.g.::

            BitString("011") & BitString("011") == BitString("010")
        """
    if not isinstance(o, str):
        return NotImplemented
    o = BitString(o)
    if len(self) != len(o):
        raise ValueError('Operands must be the same length')
    return BitString(''.join(('1' if x == '1' and y == '1' else '0' for x, y in zip(self, o))), False)

def __or__(self, o: str) -> BitString:
    """Performs a bitwise or (``|``) with the given operand.
        A ``ValueError`` is raised if the operand is not the same length.

        e.g.::

            BitString("011") | BitString("010") == BitString("011")
        """
    if not isinstance(o, str):
        return NotImplemented
    if len(self) != len(o):
        raise ValueError('Operands must be the same length')
    o = BitString(o)
    return BitString(''.join(('1' if x == '1' or y == '1' else '0' for x, y in zip(self, o))), False)

def __xor__(self, o: str) -> BitString:
    """Performs a bitwise xor (``^``) with the given operand.
        A ``ValueError`` is raised if the operand is not the same length.

        e.g.::

            BitString("011") ^ BitString("010") == BitString("001")
        """
    if not isinstance(o, BitString):
        return NotImplemented
    if len(self) != len(o):
        raise ValueError('Operands must be the same length')
    return BitString(''.join(('1' if x == '1' and y == '0' or (x == '0' and y == '1') else '0' for x, y in zip(self, o))), False)

def _serialize_hstore(val: _HSTORE_VAL) -> str:
    """Serialize a dictionary into an hstore literal.  Keys and values must
    both be strings (except None for values).

    """

    def esc(s: Optional[str], position: str) -> str:
        if position == 'value' and s is None:
            return 'NULL'
        elif isinstance(s, str):
            return '"%s"' % s.replace('\\', '\\\\').replace('"', '\\"')
        else:
            raise ValueError('%r in %s position is not a string.' % (s, position))
    return ', '.join(('%s=>%s' % (esc(k, 'key'), esc(v, 'value')) for k, v in val.items()))

def has_key(self, other: Any) -> Any:
    """Boolean expression.  Test for presence of a key.  Note that the
            key may be a SQLA expression.
            """
    return self.operate(HAS_KEY, other, result_type=sqltypes.Boolean)

def has_all(self, other: Any) -> Any:
    """Boolean expression.  Test for presence of all keys in jsonb"""
    return self.operate(HAS_ALL, other, result_type=sqltypes.Boolean)

def has_any(self, other: Any) -> Any:
    """Boolean expression.  Test for presence of any key in jsonb"""
    return self.operate(HAS_ANY, other, result_type=sqltypes.Boolean)

def contained_by(self, other: Any) -> Any:
    """Boolean expression.  Test if keys are a proper subset of the
            keys of the argument jsonb expression.
            """
    return self.operate(CONTAINED_BY, other, result_type=sqltypes.Boolean)

def defined(self, key: Any) -> Any:
    """Boolean expression.  Test for presence of a non-NULL value for
            the key.  Note that the key may be a SQLA expression.
            """
    return _HStoreDefinedFunction(self.expr, key)

def delete(self, key: Any) -> Any:
    """HStore expression.  Returns the contents of this hstore with the
            given key deleted.  Note that the key may be a SQLA expression.
            """
    if isinstance(key, dict):
        key = _serialize_hstore(key)
    return _HStoreDeleteFunction(self.expr, key)

def slice(self, array: Any) -> Any:
    """HStore expression.  Returns a subset of an hstore defined by
            array of keys.
            """
    return _HStoreSliceFunction(self.expr, array)

def array(self) -> Any:
    """Text array expression.  Returns array of alternating keys and
            values.
            """
    return _HStoreArrayFunction(self.expr)

@property
def astext(self) -> ColumnElement[str]:
    """On an indexed expression, use the "astext" (e.g. "->>")
            conversion when rendered in SQL.

            E.g.::

                select(data_table.c.data["some key"].astext)

            .. seealso::

                :meth:`_expression.ColumnElement.cast`

            """
    if isinstance(self.expr.right.type, sqltypes.JSON.JSONPathType):
        return self.expr.left.operate(JSONPATH_ASTEXT, self.expr.right, result_type=self.type.astext_type)
    else:
        return self.expr.left.operate(ASTEXT, self.expr.right, result_type=self.type.astext_type)

def has_key(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression.  Test for presence of a key (equivalent of
            the ``?`` operator).  Note that the key may be a SQLA expression.
            """
    return self.operate(HAS_KEY, other, result_type=sqltypes.Boolean)

def has_all(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression.  Test for presence of all keys in jsonb
            (equivalent of the ``?&`` operator)
            """
    return self.operate(HAS_ALL, other, result_type=sqltypes.Boolean)

def has_any(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression.  Test for presence of any key in jsonb
            (equivalent of the ``?|`` operator)
            """
    return self.operate(HAS_ANY, other, result_type=sqltypes.Boolean)

def contained_by(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression.  Test if keys are a proper subset of the
            keys of the argument jsonb expression
            (equivalent of the ``<@`` operator).
            """
    return self.operate(CONTAINED_BY, other, result_type=sqltypes.Boolean)

def path_exists(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Test for presence of item given by the
            argument JSONPath expression (equivalent of the ``@?`` operator).

            .. versionadded:: 2.0
            """
    return self.operate(PATH_EXISTS, other, result_type=sqltypes.Boolean)

def bind_processor(self, dialect):
    """psycopg's bind processor is assembled on the type adapter,
        but we still need to wrap the value in a psycopg.Json() object"""
    return self._make_bind_processor(None, dialect._psycopg_Json)

def bind_processor(self, dialect):
    """psycopg's bind processor is assembled on the type adapter,
        but we still need to wrap the value in a psycopg.Jsonb() object"""
    return self._make_bind_processor(None, dialect._psycopg_Jsonb)

@property
def lower_inf(self) -> bool:
    """Return True if this range is non-empty and lower bound is
        infinite."""
    return not self.empty and self.lower is None

@property
def upper_inf(self) -> bool:
    """Return True if this range is non-empty and the upper bound is
        infinite."""
    return not self.empty and self.upper is None

def _get_discrete_step(self) -> Any:
    """Determine the “step” for this range, if it is a discrete one."""
    if isinstance(self.lower, int) or isinstance(self.upper, int):
        return 1
    elif isinstance(self.lower, datetime) or isinstance(self.upper, datetime):
        return None
    elif isinstance(self.lower, date) or isinstance(self.upper, date):
        return timedelta(days=1)
    else:
        return None

def _compare_edges(self, value1: Optional[_T], bound1: str, value2: Optional[_T], bound2: str, only_values: bool=False) -> int:
    """Compare two range bounds.

        Return -1, 0 or 1 respectively when `value1` is less than,
        equal to or greater than `value2`.

        When `only_value` is ``True``, do not consider the *inclusivity*
        of the edges, just their values.
        """
    value1_is_lower_bound = bound1 in {'[', '('}
    value2_is_lower_bound = bound2 in {'[', '('}
    if value1 is value2 is None:
        if value1_is_lower_bound == value2_is_lower_bound:
            return 0
        else:
            return -1 if value1_is_lower_bound else 1
    elif value1 is None:
        return -1 if value1_is_lower_bound else 1
    elif value2 is None:
        return 1 if value2_is_lower_bound else -1
    if bound1 == bound2 and value1 == value2:
        return 0
    value1_inc = bound1 in {'[', ']'}
    value2_inc = bound2 in {'[', ']'}
    step = self._get_discrete_step()
    if step is not None:
        if value1_is_lower_bound:
            if not value1_inc:
                value1 += step
                value1_inc = True
        elif value1_inc:
            value1 += step
            value1_inc = False
        if value2_is_lower_bound:
            if not value2_inc:
                value2 += step
                value2_inc = True
        elif value2_inc:
            value2 += step
            value2_inc = False
    if value1 < value2:
        return -1
    elif value1 > value2:
        return 1
    elif only_values:
        return 0
    elif value1_inc and value2_inc:
        return 0
    elif not value1_inc and (not value2_inc):
        if value1_is_lower_bound == value2_is_lower_bound:
            return 0
        else:
            return 1 if value1_is_lower_bound else -1
    elif not value1_inc:
        return 1 if value1_is_lower_bound else -1
    elif not value2_inc:
        return -1 if value2_is_lower_bound else 1
    else:
        return 0

def _upper_edge_adjacent_to_lower(self, value1: Optional[_T], bound1: str, value2: Optional[_T], bound2: str) -> bool:
    """Determine whether an upper bound is immediately successive to a
        lower bound."""
    res = self._compare_edges(value1, bound1, value2, bound2, True)
    if res == -1:
        step = self._get_discrete_step()
        if step is None:
            return False
        if bound1 == ']':
            if bound2 == '[':
                return value1 == value2 - step
            else:
                return value1 == value2
        elif bound2 == '[':
            return value1 == value2
        else:
            return value1 == value2 - step
    elif res == 0:
        if bound1 == ']' and bound2 == '[' or (bound1 == ')' and bound2 == '('):
            step = self._get_discrete_step()
            if step is not None:
                return True
        return bound1 == ')' and bound2 == '[' or (bound1 == ']' and bound2 == '(')
    else:
        return False

def difference(self, other: Range[_T]) -> Range[_T]:
    """Compute the difference between this range and the `other`.

        This raises a ``ValueError`` exception if the two ranges are
        "disjunct", that is neither adjacent nor overlapping.
        """
    if self.empty or other.empty:
        return self
    slower = self.lower
    slower_b = self.bounds[0]
    supper = self.upper
    supper_b = self.bounds[1]
    olower = other.lower
    olower_b = other.bounds[0]
    oupper = other.upper
    oupper_b = other.bounds[1]
    sl_vs_ol = self._compare_edges(slower, slower_b, olower, olower_b)
    su_vs_ou = self._compare_edges(supper, supper_b, oupper, oupper_b)
    if sl_vs_ol < 0 and su_vs_ou > 0:
        raise ValueError('Subtracting a strictly inner range is not implemented')
    sl_vs_ou = self._compare_edges(slower, slower_b, oupper, oupper_b)
    su_vs_ol = self._compare_edges(supper, supper_b, olower, olower_b)
    if sl_vs_ou > 0 or su_vs_ol < 0:
        return self
    if sl_vs_ol >= 0 and su_vs_ou <= 0:
        return Range(None, None, empty=True)
    if sl_vs_ol <= 0 and su_vs_ol >= 0 and (su_vs_ou <= 0):
        rupper_b = ')' if olower_b == '[' else ']'
        if slower_b != '[' and rupper_b != ']' and (self._compare_edges(slower, slower_b, olower, rupper_b) == 0):
            return Range(None, None, empty=True)
        else:
            return Range(slower, olower, bounds=cast(_BoundsType, slower_b + rupper_b))
    if sl_vs_ol >= 0 and su_vs_ou >= 0 and (sl_vs_ou <= 0):
        rlower_b = '(' if oupper_b == ']' else '['
        if rlower_b != '[' and supper_b != ']' and (self._compare_edges(oupper, rlower_b, supper, supper_b) == 0):
            return Range(None, None, empty=True)
        else:
            return Range(oupper, supper, bounds=cast(_BoundsType, rlower_b + supper_b))
    assert False, f'Unhandled case computing {self} - {other}'

def adapt(self, cls: Type[Union[TypeEngine[Any], TypeEngineMixin]], **kw: Any) -> TypeEngine[Any]:
    """Dynamically adapt a range type to an abstract impl.

        For example ``INT4RANGE().adapt(_Psycopg2NumericRange)`` should
        produce a type that will have ``_Psycopg2NumericRange`` behaviors
        and also render as ``INT4RANGE`` in SQL and DDL.

        """
    if issubclass(cls, (AbstractSingleRangeImpl, AbstractMultiRangeImpl)) and cls is not self.__class__:
        visit_name = self.__visit_name__
        return type(f'{visit_name}RangeImpl', (cls, self.__class__), {'__visit_name__': visit_name})()
    else:
        return super().adapt(cls)

def contained_by(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the column is contained
            within the right hand operand.
            """
    return self.expr.operate(CONTAINED_BY, other)

def overlaps(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the column overlaps
            (has points in common with) the right hand operand.
            """
    return self.expr.operate(OVERLAP, other)

def strictly_left_of(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the column is strictly
            left of the right hand operand.
            """
    return self.expr.operate(STRICTLY_LEFT_OF, other)

def strictly_right_of(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the column is strictly
            right of the right hand operand.
            """
    return self.expr.operate(STRICTLY_RIGHT_OF, other)

def not_extend_right_of(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the range in the column
            does not extend right of the range in the operand.
            """
    return self.expr.operate(NOT_EXTEND_RIGHT_OF, other)

def not_extend_left_of(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the range in the column
            does not extend left of the range in the operand.
            """
    return self.expr.operate(NOT_EXTEND_LEFT_OF, other)

def adjacent_to(self, other: Any) -> ColumnElement[bool]:
    """Boolean expression. Returns true if the range in the column
            is adjacent to the range in the operand.
            """
    return self.expr.operate(ADJACENT_TO, other)

def union(self, other: Any) -> ColumnElement[bool]:
    """Range expression. Returns the union of the two ranges.
            Will raise an exception if the resulting range is not
            contiguous.
            """
    return self.expr.operate(operators.add, other)

def difference(self, other: Any) -> ColumnElement[bool]:
    """Range expression. Returns the union of the two ranges.
            Will raise an exception if the resulting range is not
            contiguous.
            """
    return self.expr.operate(operators.sub, other)

def intersection(self, other: Any) -> ColumnElement[Range[_T]]:
    """Range expression. Returns the intersection of the two ranges.
            Will raise an exception if the resulting range is not
            contiguous.
            """
    return self.expr.operate(operators.mul, other)

@property
def format_is_text_affinity(self):
    """return True if the storage format will automatically imply
        a TEXT affinity.

        If the storage format contains no non-numeric characters,
        it will imply a NUMERIC storage format on SQLite; in this case,
        the type will generate its DDL as DATE_CHAR, DATETIME_CHAR,
        TIME_CHAR.

        """
    spec = self._storage_format % {'year': 0, 'month': 0, 'day': 0, 'hour': 0, 'minute': 0, 'second': 0, 'microsecond': 0}
    return bool(re.search('[^0-9]', spec))

def define_constraint_remote_table(self, constraint, table, preparer):
    """Format the remote table clause of a CREATE CONSTRAINT clause."""
    return preparer.format_table(table, use_schema=False)

def _resolve_type_affinity(self, type_):
    """Return a data type from a reflected column, using affinity rules.

        SQLite's goal for universal compatibility introduces some complexity
        during reflection, as a column's defined type might not actually be a
        type that SQLite understands - or indeed, my not be defined *at all*.
        Internally, SQLite handles this with a 'data type affinity' for each
        column definition, mapping to one of 'TEXT', 'NUMERIC', 'INTEGER',
        'REAL', or 'NONE' (raw bits). The algorithm that determines this is
        listed in https://www.sqlite.org/datatype3.html section 2.1.

        This method allows SQLAlchemy to support that algorithm, while still
        providing access to smarter reflection utilities by recognizing
        column definitions that SQLite only supports through affinity (like
        DATE and DOUBLE).

        """
    match = re.match('([\\w ]+)(\\(.*?\\))?', type_)
    if match:
        coltype = match.group(1)
        args = match.group(2)
    else:
        coltype = ''
        args = ''
    if coltype in self.ischema_names:
        coltype = self.ischema_names[coltype]
    elif 'INT' in coltype:
        coltype = sqltypes.INTEGER
    elif 'CHAR' in coltype or 'CLOB' in coltype or 'TEXT' in coltype:
        coltype = sqltypes.TEXT
    elif 'BLOB' in coltype or not coltype:
        coltype = sqltypes.NullType
    elif 'REAL' in coltype or 'FLOA' in coltype or 'DOUB' in coltype:
        coltype = sqltypes.REAL
    else:
        coltype = sqltypes.NUMERIC
    if args is not None:
        args = re.findall('(\\d+)', args)
        try:
            coltype = coltype(*[int(a) for a in args])
        except TypeError:
            util.warn('Could not instantiate type %s with reflected arguments %s; using no arguments.' % (coltype, args))
            coltype = coltype()
    else:
        coltype = coltype()
    return coltype

def _format_url(url, driver, ident):
    """given a sqlite url + desired driver + ident, make a canonical
    URL out of it

    """
    url = sa_url.make_url(url)
    if driver is None:
        driver = url.get_driver_name()
    filename = url.database
    needs_enc = driver == 'pysqlcipher'
    name_token = None
    if filename and filename != ':memory:':
        assert 'test_schema' not in filename
        tokens = re.split('[_\\.]', filename)
        for token in tokens:
            if token in _drivernames:
                if driver is None:
                    driver = token
                continue
            elif token in ('db', 'enc'):
                continue
            elif name_token is None:
                name_token = token.strip('_')
        assert name_token, f'sqlite filename has no name token: {url.database}'
        new_filename = f'{name_token}_{driver}'
        if ident:
            new_filename += f'_{ident}'
        new_filename += '.db'
        if needs_enc:
            new_filename += '.enc'
        url = url.set(database=new_filename)
    if needs_enc:
        url = url.set(password='test')
    url = url.set(drivername='sqlite+%s' % (driver,))
    return url

@event.listens_for(engine, 'engine_disposed')
def dispose(engine):
    """most databases should be dropped using
        stop_test_class_outside_fixtures

        however a few tests like AttachedDBTest might not get triggered on
        that main hook

        """
    if os.path.exists(attach_path):
        os.remove(attach_path)
    filename = engine.url.database
    if filename and filename != ':memory:' and os.path.exists(filename):
        os.remove(filename)

