def scalar(self, statement: Executable, parameters: Optional[_CoreSingleExecuteParams]=None, *, execution_options: Optional[CoreExecuteOptionsParameter]=None) -> Any:
    """Executes a SQL statement construct and returns a scalar object.

        This method is shorthand for invoking the
        :meth:`_engine.Result.scalar` method after invoking the
        :meth:`_engine.Connection.execute` method.  Parameters are equivalent.

        :return: a scalar Python value representing the first column of the
         first row returned.

        """
    distilled_parameters = _distill_params_20(parameters)
    try:
        meth = statement._execute_on_scalar
    except AttributeError as err:
        raise exc.ObjectNotExecutableError(statement) from err
    else:
        return meth(self, distilled_parameters, execution_options or NO_OPTIONS)

def _exec_single_context(self, dialect: Dialect, context: ExecutionContext, statement: Union[str, Compiled], parameters: Optional[_AnyMultiExecuteParams]) -> CursorResult[Unpack[TupleAny]]:
    """continue the _execute_context() method for a single DBAPI
        cursor.execute() or cursor.executemany() call.

        """
    if dialect.bind_typing is BindTyping.SETINPUTSIZES:
        generic_setinputsizes = context._prepare_set_input_sizes()
        if generic_setinputsizes:
            try:
                dialect.do_set_input_sizes(context.cursor, generic_setinputsizes, context)
            except BaseException as e:
                self._handle_dbapi_exception(e, str(statement), parameters, None, context)
    cursor, str_statement, parameters = (context.cursor, context.statement, context.parameters)
    effective_parameters: Optional[_AnyExecuteParams]
    if not context.executemany:
        effective_parameters = parameters[0]
    else:
        effective_parameters = parameters
    evt_handled: bool = False
    try:
        if self._has_events or self.engine._has_events:
            for fn in self.dispatch.before_cursor_execute:
                str_statement, effective_parameters = fn(self, cursor, str_statement, effective_parameters, context, context.executemany)
        if self._echo:
            self._log_info(str_statement)
            stats = context._get_cache_stats()
            if not self.engine.hide_parameters:
                self._log_info('[%s] %r', stats, sql_util._repr_params(effective_parameters, batches=10, ismulti=context.executemany))
            else:
                self._log_info('[%s] [SQL parameters hidden due to hide_parameters=True]', stats)
        if context.execute_style is ExecuteStyle.EXECUTEMANY:
            effective_parameters = cast('_CoreMultiExecuteParams', effective_parameters)
            if self.dialect._has_events:
                for fn in self.dialect.dispatch.do_executemany:
                    if fn(cursor, str_statement, effective_parameters, context):
                        evt_handled = True
                        break
            if not evt_handled:
                self.dialect.do_executemany(cursor, str_statement, effective_parameters, context)
        elif not effective_parameters and context.no_parameters:
            if self.dialect._has_events:
                for fn in self.dialect.dispatch.do_execute_no_params:
                    if fn(cursor, str_statement, context):
                        evt_handled = True
                        break
            if not evt_handled:
                self.dialect.do_execute_no_params(cursor, str_statement, context)
        else:
            effective_parameters = cast('_CoreSingleExecuteParams', effective_parameters)
            if self.dialect._has_events:
                for fn in self.dialect.dispatch.do_execute:
                    if fn(cursor, str_statement, effective_parameters, context):
                        evt_handled = True
                        break
            if not evt_handled:
                self.dialect.do_execute(cursor, str_statement, effective_parameters, context)
        if self._has_events or self.engine._has_events:
            self.dispatch.after_cursor_execute(self, cursor, str_statement, effective_parameters, context, context.executemany)
        context.post_exec()
        result = context._setup_result_proxy()
    except BaseException as e:
        self._handle_dbapi_exception(e, str_statement, effective_parameters, cursor, context)
    return result

def _exec_insertmany_context(self, dialect: Dialect, context: ExecutionContext) -> CursorResult[Unpack[TupleAny]]:
    """continue the _execute_context() method for an "insertmanyvalues"
        operation, which will invoke DBAPI
        cursor.execute() one or more times with individual log and
        event hook calls.

        """
    if dialect.bind_typing is BindTyping.SETINPUTSIZES:
        generic_setinputsizes = context._prepare_set_input_sizes()
    else:
        generic_setinputsizes = None
    cursor, str_statement, parameters = (context.cursor, context.statement, context.parameters)
    effective_parameters = parameters
    engine_events = self._has_events or self.engine._has_events
    if self.dialect._has_events:
        do_execute_dispatch: Iterable[Any] = self.dialect.dispatch.do_execute
    else:
        do_execute_dispatch = ()
    if self._echo:
        stats = context._get_cache_stats() + ' (insertmanyvalues)'
    preserve_rowcount = context.execution_options.get('preserve_rowcount', False)
    rowcount = 0
    for imv_batch in dialect._deliver_insertmanyvalues_batches(self, cursor, str_statement, effective_parameters, generic_setinputsizes, context):
        if imv_batch.processed_setinputsizes:
            try:
                dialect.do_set_input_sizes(context.cursor, imv_batch.processed_setinputsizes, context)
            except BaseException as e:
                self._handle_dbapi_exception(e, sql_util._long_statement(imv_batch.replaced_statement), imv_batch.replaced_parameters, None, context, is_sub_exec=True)
        sub_stmt = imv_batch.replaced_statement
        sub_params = imv_batch.replaced_parameters
        try:
            if engine_events:
                for fn in self.dispatch.before_cursor_execute:
                    sub_stmt, sub_params = fn(self, cursor, sub_stmt, sub_params, context, True)
            if self._echo:
                self._log_info(sql_util._long_statement(sub_stmt))
                imv_stats = f" {imv_batch.batchnum}/{imv_batch.total_batches} ({('ordered' if imv_batch.rows_sorted else 'unordered')}{('; batch not supported' if imv_batch.is_downgraded else '')})"
                if imv_batch.batchnum == 1:
                    stats += imv_stats
                else:
                    stats = f'insertmanyvalues{imv_stats}'
                if not self.engine.hide_parameters:
                    self._log_info('[%s] %r', stats, sql_util._repr_params(sub_params, batches=10, ismulti=False))
                else:
                    self._log_info('[%s] [SQL parameters hidden due to hide_parameters=True]', stats)
            for fn in do_execute_dispatch:
                if fn(cursor, sub_stmt, sub_params, context):
                    break
            else:
                dialect.do_execute(cursor, sub_stmt, sub_params, context)
            if engine_events:
                self.dispatch.after_cursor_execute(self, cursor, sub_stmt, sub_params, context, context.executemany)
        except BaseException as e:
            self._handle_dbapi_exception(e, sql_util._long_statement(sub_stmt), sub_params, cursor, context, is_sub_exec=True)
        if preserve_rowcount:
            rowcount += imv_batch.current_batch_size
    try:
        context.post_exec()
        if preserve_rowcount:
            context._rowcount = rowcount
        result = context._setup_result_proxy()
    except BaseException as e:
        self._handle_dbapi_exception(e, str_statement, effective_parameters, cursor, context)
    return result

def _cursor_execute(self, cursor: DBAPICursor, statement: str, parameters: _DBAPISingleExecuteParams, context: Optional[ExecutionContext]=None) -> None:
    """Execute a statement + params on the given cursor.

        Adds appropriate logging and exception handling.

        This method is used by DefaultDialect for special-case
        executions, such as for sequences and column defaults.
        The path of statement execution in the majority of cases
        terminates at _execute_context().

        """
    try:
        if self._has_events or self.engine._has_events:
            for fn in self.dispatch.before_cursor_execute:
                statement, parameters = fn(self, cursor, statement, parameters, context, False)
        if self._echo:
            self._log_info(statement)
            self._log_info('[raw sql] %r', parameters)
        for fn in () if not self.dialect._has_events else self.dialect.dispatch.do_execute:
            if fn(cursor, statement, parameters, context):
                break
        else:
            self.dialect.do_execute(cursor, statement, parameters, context)
        if self._has_events or self.engine._has_events:
            self.dispatch.after_cursor_execute(self, cursor, statement, parameters, context, False)
    except BaseException as e:
        self._handle_dbapi_exception(e, statement, parameters, cursor, context)

def _safe_close_cursor(self, cursor: DBAPICursor) -> None:
    """Close the given cursor, catching exceptions
        and turning into log warnings.

        """
    try:
        cursor.close()
    except Exception:
        self.engine.pool.logger.error('Error closing cursor', exc_info=True)

