def make_url(name_or_url: Union[str, URL]) -> URL:
    """Given a string, produce a new URL instance.

    The format of the URL generally follows `RFC-1738
    <https://www.ietf.org/rfc/rfc1738.txt>`_, with some exceptions, including
    that underscores, and not dashes or periods, are accepted within the
    "scheme" portion.

    If a :class:`.URL` object is passed, it is returned as is.

    .. seealso::

        :ref:`database_urls`

    """
    if isinstance(name_or_url, str):
        return _parse_url(name_or_url)
    elif not isinstance(name_or_url, URL) and (not hasattr(name_or_url, '_sqla_is_testing_if_this_is_a_mock_object')):
        raise exc.ArgumentError(f'Expected string or URL object, got {name_or_url!r}')
    else:
        return name_or_url

def difference_update_query(self, names: Iterable[str]) -> URL:
    """
        Remove the given names from the :attr:`_engine.URL.query` dictionary,
        returning the new :class:`_engine.URL`.

        E.g.::

            url = url.difference_update_query(["foo", "bar"])

        Equivalent to using :meth:`_engine.URL.set` as follows::

            url = url.set(
                query={
                    key: url.query[key]
                    for key in set(url.query).difference(["foo", "bar"])
                }
            )

        .. versionadded:: 1.4

        .. seealso::

            :attr:`_engine.URL.query`

            :meth:`_engine.URL.update_query_dict`

            :meth:`_engine.URL.set`

        """
    if not set(names).intersection(self.query):
        return self
    return URL(self.drivername, self.username, self.password, self.host, self.port, self.database, util.immutabledict({key: self.query[key] for key in set(self.query).difference(names)}))

@util.deprecated('1.4', 'The :meth:`_engine.URL.__to_string__ method is deprecated and will be removed in a future release.  Please use the :meth:`_engine.URL.render_as_string` method.')
def __to_string__(self, hide_password: bool=True) -> str:
    """Render this :class:`_engine.URL` object as a string.

        :param hide_password: Defaults to True.   The password is not shown
         in the string unless this is set to False.

        """
    return self.render_as_string(hide_password=hide_password)

def render_as_string(self, hide_password: bool=True) -> str:
    """Render this :class:`_engine.URL` object as a string.

        This method is used when the ``__str__()`` or ``__repr__()``
        methods are used.   The method directly includes additional options.

        :param hide_password: Defaults to True.   The password is not shown
         in the string unless this is set to False.

        """
    s = self.drivername + '://'
    if self.username is not None:
        s += quote(self.username, safe=' +')
        if self.password is not None:
            s += ':' + ('***' if hide_password else quote(str(self.password), safe=' +'))
        s += '@'
    if self.host is not None:
        if ':' in self.host:
            s += f'[{self.host}]'
        else:
            s += self.host
    if self.port is not None:
        s += ':' + str(self.port)
    if self.database is not None:
        s += '/' + quote(self.database, safe=' +/')
    if self.query:
        keys = list(self.query)
        keys.sort()
        s += '?' + '&'.join((f'{quote_plus(k)}={quote_plus(element)}' for k in keys for element in util.to_list(self.query[k])))
    return s

def get_backend_name(self) -> str:
    """Return the backend name.

        This is the name that corresponds to the database backend in
        use, and is the portion of the :attr:`_engine.URL.drivername`
        that is to the left of the plus sign.

        """
    if '+' not in self.drivername:
        return self.drivername
    else:
        return self.drivername.split('+')[0]

def _get_entrypoint(self) -> Type[Dialect]:
    """Return the "entry point" dialect class.

        This is normally the dialect itself except in the case when the
        returned class implements the get_dialect_cls() method.

        """
    if '+' not in self.drivername:
        name = self.drivername
    else:
        name = self.drivername.replace('+', '.')
    cls = registry.load(name)
    if hasattr(cls, 'dialect') and isinstance(cls.dialect, type) and issubclass(cls.dialect, Dialect):
        return cls.dialect
    else:
        return cast('Type[Dialect]', cls)

def get_dialect(self, _is_async: bool=False) -> Type[Dialect]:
    """Return the SQLAlchemy :class:`_engine.Dialect` class corresponding
        to this URL's driver name.

        """
    entrypoint = self._get_entrypoint()
    if _is_async:
        dialect_cls = entrypoint.get_async_dialect_cls(self)
    else:
        dialect_cls = entrypoint.get_dialect_cls(self)
    return dialect_cls

def translate_connect_args(self, names: Optional[List[str]]=None, **kw: Any) -> Dict[str, Any]:
    """Translate url attributes into a dictionary of connection arguments.

        Returns attributes of this url (`host`, `database`, `username`,
        `password`, `port`) as a plain dictionary.  The attribute names are
        used as the keys by default.  Unset or false attributes are omitted
        from the final dictionary.

        :param \\**kw: Optional, alternate key names for url attributes.

        :param names: Deprecated.  Same purpose as the keyword-based alternate
            names, but correlates the name to the original positionally.
        """
    if names is not None:
        util.warn_deprecated('The `URL.translate_connect_args.name`s parameter is deprecated. Please pass the alternate names as kw arguments.', '1.4')
    translated = {}
    attribute_names = ['host', 'database', 'username', 'password', 'port']
    for sname in attribute_names:
        if names:
            name = names.pop(0)
        elif sname in kw:
            name = kw[sname]
        else:
            name = sname
        if name is not None and getattr(self, sname, False):
            if sname == 'password':
                translated[name] = str(getattr(self, sname))
            else:
                translated[name] = getattr(self, sname)
    return translated

def connection_memoize(key: str) -> Callable[[_C], _C]:
    """Decorator, memoize a function in a connection.info stash.

    Only applicable to functions which take no arguments other than a
    connection.  The memo will be stored in ``connection.info[key]``.
    """

    @util.decorator
    def decorated(fn, self, connection):
        connection = connection.connect()
        try:
            return connection.info[key]
        except KeyError:
            connection.info[key] = val = fn(self, connection)
            return val
    return decorated

