def compiles(class_: Type[Any], *specs: str) -> Callable[[_F], _F]:
    """Register a function as a compiler for a
    given :class:`_expression.ClauseElement` type."""

    def decorate(fn: _F) -> _F:
        existing = class_.__dict__.get('_compiler_dispatcher', None)
        existing_dispatch = getattr(class_, '_compiler_dispatch', None)
        if not existing:
            existing = _dispatcher()
            if existing_dispatch:

                def _wrap_existing_dispatch(element: Any, compiler: SQLCompiler, **kw: Any) -> Any:
                    try:
                        return existing_dispatch(element, compiler, **kw)
                    except exc.UnsupportedCompilationError as uce:
                        raise exc.UnsupportedCompilationError(compiler, type(element), message='%s construct has no default compilation handler.' % type(element)) from uce
                existing.specs['default'] = _wrap_existing_dispatch
            setattr(class_, '_compiler_dispatch', lambda *arg, **kw: existing(*arg, **kw))
            setattr(class_, '_compiler_dispatcher', existing)
        if specs:
            for s in specs:
                existing.specs[s] = fn
        else:
            existing.specs['default'] = fn
        return fn
    return decorate

def connection_callable(self, mapper: Optional[Mapper[_T]]=None, instance: Optional[Any]=None, shard_id: Optional[ShardIdentifier]=None, **kw: Any) -> Connection:
    """Provide a :class:`_engine.Connection` to use in the unit of work
        flush process.

        """
    if shard_id is None:
        shard_id = self._choose_shard_and_assign(mapper, instance)
    if self.in_transaction():
        trans = self.get_transaction()
        assert trans is not None
        return trans.connection(mapper, shard_id=shard_id)
    else:
        bind = self.get_bind(mapper=mapper, shard_id=shard_id, instance=instance)
        if isinstance(bind, Engine):
            return bind.connect(**kw)
        else:
            assert isinstance(bind, Connection)
            return bind

