@no_type_check
def _entity_descriptor(entity: _EntityType[Any], key: str) -> Any:
    """Return a class attribute given an entity and string name.

    May return :class:`.InstrumentedAttribute` or user-defined
    attribute.

    """
    insp = inspection.inspect(entity)
    if insp.is_selectable:
        description = entity
        entity = insp.c
    elif insp.is_aliased_class:
        entity = insp.entity
        description = entity
    elif hasattr(insp, 'mapper'):
        description = entity = insp.mapper.class_
    else:
        description = entity
    try:
        return getattr(entity, key)
    except AttributeError as err:
        raise sa_exc.InvalidRequestError("Entity '%s' has no property '%s'" % (description, key)) from err

@classmethod
def _do_pre_synchronize_auto(cls, session, statement, params, execution_options, bind_arguments, update_options):
    """setup auto sync strategy


        "auto" checks if we can use "evaluate" first, then falls back
        to "fetch"

        evaluate is vastly more efficient for the common case
        where session is empty, only has a few objects, and the UPDATE
        statement can potentially match thousands/millions of rows.

        OTOH more complex criteria that fails to work with "evaluate"
        we would hope usually correlates with fewer net rows.

        """
    try:
        eval_condition = cls._eval_condition_from_statement(update_options, statement)
    except evaluator.UnevaluatableError:
        pass
    else:
        return update_options + {'_eval_condition': eval_condition, '_synchronize_session': 'evaluate'}
    update_options += {'_synchronize_session': 'fetch'}
    return cls._do_pre_synchronize_fetch(session, statement, params, execution_options, bind_arguments, update_options)

@classmethod
def _apply_update_set_values_to_objects(cls, session, update_options, statement, effective_params, matched_objects, prefetch_cols, postfetch_cols):
    """apply values to objects derived from an update statement, e.g.
        UPDATE..SET <values>

        """
    mapper = update_options._subject_mapper
    target_cls = mapper.class_
    evaluator_compiler = evaluator._EvaluatorCompiler(target_cls)
    resolved_values = cls._get_resolved_values(mapper, statement)
    resolved_keys_as_propnames = cls._resolved_keys_as_propnames(mapper, resolved_values)
    value_evaluators = {}
    for key, value in resolved_keys_as_propnames:
        try:
            _evaluator = evaluator_compiler.process(coercions.expect(roles.ExpressionElementRole, value))
        except evaluator.UnevaluatableError:
            pass
        else:
            value_evaluators[key] = _evaluator
    evaluated_keys = list(value_evaluators.keys())
    attrib = {k for k, v in resolved_keys_as_propnames}
    states = set()
    to_prefetch = {c for c in prefetch_cols if c.key in effective_params and c in mapper._columntoproperty and (c.key not in evaluated_keys)}
    to_expire = {mapper._columntoproperty[c].key for c in postfetch_cols if c in mapper._columntoproperty}.difference(evaluated_keys)
    prefetch_transfer = [(mapper._columntoproperty[c].key, c.key) for c in to_prefetch]
    for obj, state, dict_ in matched_objects:
        dict_.update({col_to_prop: effective_params[c_key] for col_to_prop, c_key in prefetch_transfer})
        state._expire_attributes(state.dict, to_expire)
        to_evaluate = state.unmodified.intersection(evaluated_keys)
        for key in to_evaluate:
            if key in dict_:
                dict_[key] = value_evaluators[key](obj)
        state.manager.dispatch.refresh(state, None, to_evaluate)
        state._commit(dict_, list(to_evaluate))
        to_expire = attrib.intersection(dict_).difference(to_evaluate)
        if to_expire:
            state._expire_attributes(dict_, to_expire)
        states.add(state)
    session._register_altered(states)

def _add_class(classname: str, cls: Type[_T], decl_class_registry: _ClsRegistryType) -> None:
    """Add a class to the _decl_class_registry associated with the
    given declarative class.

    """
    if classname in decl_class_registry:
        existing = decl_class_registry[classname]
        if not isinstance(existing, _MultipleClassMarker):
            decl_class_registry[classname] = _MultipleClassMarker([cls, cast('Type[Any]', existing)])
    else:
        decl_class_registry[classname] = cls
    try:
        root_module = cast(_ModuleMarker, decl_class_registry['_sa_module_registry'])
    except KeyError:
        decl_class_registry['_sa_module_registry'] = root_module = _ModuleMarker('_sa_module_registry', None)
    tokens = cls.__module__.split('.')
    while tokens:
        token = tokens.pop(0)
        module = root_module.get_module(token)
        for token in tokens:
            module = module.get_module(token)
        try:
            module.add_class(classname, cls)
        except AttributeError as ae:
            if not isinstance(module, _ModuleMarker):
                raise exc.InvalidRequestError(f'name "{classname}" matches both a class name and a module name') from ae
            else:
                raise

def _key_is_empty(key: str, decl_class_registry: _ClsRegistryType, test: Callable[[Any], bool]) -> bool:
    """test if a key is empty of a certain object.

    used for unit tests against the registry to see if garbage collection
    is working.

    "test" is a callable that will be passed an object should return True
    if the given object is the one we were looking for.

    We can't pass the actual object itself b.c. this is for testing garbage
    collection; the caller will have to have removed references to the
    object itself.

    """
    if key not in decl_class_registry:
        return True
    thing = decl_class_registry[key]
    if isinstance(thing, _MultipleClassMarker):
        for sub_thing in thing.contents:
            if test(sub_thing):
                return False
        else:
            raise NotImplementedError('unknown codepath')
    else:
        return not test(thing)

def _locate_roles_and_methods(cls):
    """search for _sa_instrument_role-decorated methods in
    method resolution order, assign to roles.

    """
    roles: Dict[str, str] = {}
    methods: Dict[str, Tuple[Optional[str], Optional[int], Optional[str]]] = {}
    for supercls in cls.__mro__:
        for name, method in vars(supercls).items():
            if not callable(method):
                continue
            if hasattr(method, '_sa_instrument_role'):
                role = method._sa_instrument_role
                assert role in ('appender', 'remover', 'iterator')
                roles.setdefault(role, name)
            before: Optional[Tuple[str, int]] = None
            after: Optional[str] = None
            if hasattr(method, '_sa_instrument_before'):
                op, argument = method._sa_instrument_before
                assert op in ('fire_append_event', 'fire_remove_event')
                before = (op, argument)
            if hasattr(method, '_sa_instrument_after'):
                op = method._sa_instrument_after
                assert op in ('fire_append_event', 'fire_remove_event')
                after = op
            if before:
                methods[name] = before + (after,)
            elif after:
                methods[name] = (None, None, after)
    return (roles, methods)

def _setup_canned_roles(cls, roles, methods):
    """see if this class has "canned" roles based on a known
    collection type (dict, set, list).  Apply those roles
    as needed to the "roles" dictionary, and also
    prepare "decorator" methods

    """
    collection_type = util.duck_type_collection(cls)
    if collection_type in __interfaces:
        assert collection_type is not None
        canned_roles, decorators = __interfaces[collection_type]
        for role, name in canned_roles.items():
            roles.setdefault(role, name)
        for method, decorator in decorators.items():
            fn = getattr(cls, method, None)
            if fn and method not in methods and (not hasattr(fn, '_sa_instrumented')):
                setattr(cls, method, decorator(fn))

def _assert_required_roles(cls, roles, methods):
    """ensure all roles are present, and apply implicit instrumentation if
    needed

    """
    if 'appender' not in roles or not hasattr(cls, roles['appender']):
        raise sa_exc.ArgumentError('Type %s must elect an appender method to be a collection class' % cls.__name__)
    elif roles['appender'] not in methods and (not hasattr(getattr(cls, roles['appender']), '_sa_instrumented')):
        methods[roles['appender']] = ('fire_append_event', 1, None)
    if 'remover' not in roles or not hasattr(cls, roles['remover']):
        raise sa_exc.ArgumentError('Type %s must elect a remover method to be a collection class' % cls.__name__)
    elif roles['remover'] not in methods and (not hasattr(getattr(cls, roles['remover']), '_sa_instrumented')):
        methods[roles['remover']] = ('fire_remove_event', 1, None)
    if 'iterator' not in roles or not hasattr(cls, roles['iterator']):
        raise sa_exc.ArgumentError('Type %s must elect an iterator method to be a collection class' % cls.__name__)

def _set_collection_attributes(cls, roles, methods):
    """apply ad-hoc instrumentation from decorators, class-level defaults
    and implicit role declarations

    """
    for method_name, (before, argument, after) in methods.items():
        setattr(cls, method_name, _instrument_membership_mutator(getattr(cls, method_name), before, argument, after))
    for role, method_name in roles.items():
        setattr(cls, '_sa_%s' % role, getattr(cls, method_name))
    cls._sa_adapter = None
    cls._sa_instrumented = id(cls)

def _instrument_membership_mutator(method, before, argument, after):
    """Route method args and/or return value through the collection
    adapter."""
    if before:
        fn_args = list(util.flatten_iterator(inspect_getfullargspec(method)[0]))
        if isinstance(argument, int):
            pos_arg = argument
            named_arg = len(fn_args) > argument and fn_args[argument] or None
        else:
            if argument in fn_args:
                pos_arg = fn_args.index(argument)
            else:
                pos_arg = None
            named_arg = argument
        del fn_args

    def wrapper(*args, **kw):
        if before:
            if pos_arg is None:
                if named_arg not in kw:
                    raise sa_exc.ArgumentError('Missing argument %s' % argument)
                value = kw[named_arg]
            elif len(args) > pos_arg:
                value = args[pos_arg]
            elif named_arg in kw:
                value = kw[named_arg]
            else:
                raise sa_exc.ArgumentError('Missing argument %s' % argument)
        initiator = kw.pop('_sa_initiator', None)
        if initiator is False:
            executor = None
        else:
            executor = args[0]._sa_adapter
        if before and executor:
            getattr(executor, before)(value, initiator)
        if not after or not executor:
            return method(*args, **kw)
        else:
            res = method(*args, **kw)
            if res is not None:
                getattr(executor, after)(res, initiator)
            return res
    wrapper._sa_instrumented = True
    if hasattr(method, '_sa_instrument_role'):
        wrapper._sa_instrument_role = method._sa_instrument_role
    wrapper.__name__ = method.__name__
    wrapper.__doc__ = method.__doc__
    return wrapper

def __set_wo_mutation(collection, item, _sa_initiator=None):
    """Run set wo mutation events.

    The collection is not mutated.

    """
    if _sa_initiator is not False:
        executor = collection._sa_adapter
        if executor:
            executor.fire_append_wo_mutation_event(item, _sa_initiator, key=None)

def __set(collection, item, _sa_initiator, key):
    """Run set events.

    This event always occurs before the collection is actually mutated.

    """
    if _sa_initiator is not False:
        executor = collection._sa_adapter
        if executor:
            item = executor.fire_append_event(item, _sa_initiator, key=key)
    return item

def __before_pop(collection, _sa_initiator=None):
    """An event which occurs on a before a pop() operation occurs."""
    executor = collection._sa_adapter
    if executor:
        executor.fire_pre_remove_event(_sa_initiator)

