def _resolve_type_with_events(self, cls: Any, key: str, raw_annotation: _MatchedOnType, extracted_type: _MatchedOnType, *, raw_pep_593_type: Optional[GenericProtocol[Any]]=None, pep_593_resolved_argument: Optional[_MatchedOnType]=None, raw_pep_695_type: Optional[TypeAliasType]=None, pep_695_resolved_value: Optional[_MatchedOnType]=None) -> Optional[sqltypes.TypeEngine[Any]]:
    """Resolve type with event support for custom type mapping.

        This method fires the resolve_type_annotation event first to allow
        custom resolution, then falls back to normal resolution.

        """
    if self.dispatch.resolve_type_annotation:
        type_resolve = TypeResolve(self, cls, key, raw_annotation, pep_593_resolved_argument if pep_593_resolved_argument is not None else pep_695_resolved_value if pep_695_resolved_value is not None else extracted_type, raw_pep_593_type, pep_593_resolved_argument, raw_pep_695_type, pep_695_resolved_value)
        for fn in self.dispatch.resolve_type_annotation:
            result = fn(type_resolve)
            if result is not None:
                return sqltypes.to_instance(result)
    if raw_pep_695_type is not None:
        sqltype = self._resolve_type(raw_pep_695_type)
        if sqltype is not None:
            return sqltype
    sqltype = self._resolve_type(extracted_type)
    if sqltype is not None:
        return sqltype
    if pep_593_resolved_argument is not None:
        sqltype = self._resolve_type(pep_593_resolved_argument)
    return sqltype

def as_declarative_base(self, **kw: Any) -> Callable[[Type[_T]], Type[_T]]:
    """
        Class decorator which will invoke
        :meth:`_orm.registry.generate_base`
        for a given base class.

        E.g.::

            from sqlalchemy.orm import registry

            mapper_registry = registry()


            @mapper_registry.as_declarative_base()
            class Base:
                @declared_attr
                def __tablename__(cls):
                    return cls.__name__.lower()

                id = Column(Integer, primary_key=True)


            class MyMappedClass(Base): ...

        All keyword arguments passed to
        :meth:`_orm.registry.as_declarative_base` are passed
        along to :meth:`_orm.registry.generate_base`.

        """

    def decorate(cls: Type[_T]) -> Type[_T]:
        kw['cls'] = cls
        kw['name'] = cls.__name__
        return self.generate_base(**kw)
    return decorate

