def _get_arguments_for_make_dataclass(cls, decl_scan: _ClassScanAbstractConfig, key: str, annotation: _AnnotationScanType, mapped_container: Optional[Any], elem: Any, dataclass_setup_arguments: _DataclassArguments, enable_descriptor_defaults: bool) -> Union[Tuple[str, _AnnotationScanType], Tuple[str, _AnnotationScanType, dataclasses.Field[Any] | None]]:
    """given attribute key, annotation, and value from a class, return
        the argument tuple we would pass to dataclasses.make_dataclass()
        for this attribute.

