    if isinstance(elem, _DCAttributeOptions):
        attribute_options = elem._get_dataclass_setup_options(decl_scan, key, dataclass_setup_arguments, enable_descriptor_defaults)
        dc_field = attribute_options._as_dataclass_field(key, dataclass_setup_arguments)
        return (key, annotation, dc_field)
    elif elem is not _NoArg.NO_ARG:
        return (key, annotation, elem)
    elif mapped_container is not None:
