@util.became_legacy_20(':func:`_orm.merge_result`', alternative='The function as well as the method on :class:`_orm.Query` is superseded by the :func:`_orm.merge_frozen_result` function.')
@util.preload_module('sqlalchemy.orm.context')
def merge_result(query: Query[Any], iterator: Union[FrozenResult, Iterable[Sequence[Any]], Iterable[object]], load: bool=True) -> Union[FrozenResult, Iterable[Any]]:
    """Merge a result into the given :class:`.Query` object's Session.

    See :meth:`_orm.Query.merge_result` for top-level documentation on this
    function.

    """
    querycontext = util.preloaded.orm_context
    session = query.session
    if load:
        session._autoflush()
    if isinstance(iterator, FrozenResult):
        frozen_result = iterator
        iterator = iter(frozen_result.data)
    else:
        frozen_result = None
    ctx = querycontext._ORMSelectCompileState._create_entities_collection(query, legacy=True)
    autoflush = session.autoflush
    try:
        session.autoflush = False
        single_entity = not frozen_result and len(ctx._entities) == 1
        if single_entity:
            if isinstance(ctx._entities[0], querycontext._MapperEntity):
                result = [session._merge(attributes.instance_state(instance), attributes.instance_dict(instance), load=load, _recursive={}, _resolve_conflict_map={}) for instance in iterator]
            else:
                result = list(iterator)
        else:
            mapped_entities = [i for i, e in enumerate(ctx._entities) if isinstance(e, querycontext._MapperEntity)]
            result = []
            keys = [ent._label_name for ent in ctx._entities]
            keyed_tuple = result_tuple(keys, [ent._extra_entities for ent in ctx._entities])
            for row in iterator:
                newrow = list(row)
                for i in mapped_entities:
                    if newrow[i] is not None:
                        newrow[i] = session._merge(attributes.instance_state(newrow[i]), attributes.instance_dict(newrow[i]), load=load, _recursive={}, _resolve_conflict_map={})
                result.append(keyed_tuple(newrow))
