def _mappers_from_spec(self, spec: Any, selectable: Optional[FromClause]) -> Sequence[Mapper[Any]]:
    """given a with_polymorphic() argument, return the set of mappers it
        represents.

        Trims the list of mappers to just those represented within the given
        selectable, if present. This helps some more legacy-ish mappings.

        """
    if spec == '*':
        mappers = list(self.self_and_descendants)
    elif spec:
        mapper_set: Set[Mapper[Any]] = set()
        for m in util.to_list(spec):
            m = _class_to_mapper(m)
            if not m.isa(self):
                raise sa_exc.InvalidRequestError('%r does not inherit from %r' % (m, self))
            if selectable is None:
                mapper_set.update(m.iterate_to_root())
            else:
                mapper_set.add(m)
        mappers = [m for m in self.self_and_descendants if m in mapper_set]
    else:
        mappers = []
    if selectable is not None:
        tables = set(sql_util.find_tables(selectable, include_aliases=True))
        mappers = [m for m in mappers if m.local_table in tables]
    return mappers

def _selectable_from_mappers(self, mappers: Iterable[Mapper[Any]], innerjoin: bool) -> FromClause:
    """given a list of mappers (assumed to be within this mapper's
        inheritance hierarchy), construct an outerjoin amongst those mapper's
        mapped tables.

        """
    from_obj = self.persist_selectable
    for m in mappers:
        if m is self:
            continue
        if m.concrete:
            raise sa_exc.InvalidRequestError("'with_polymorphic()' requires 'selectable' argument when concrete-inheriting mappers are used.")
        elif not m.single:
            if innerjoin:
                from_obj = from_obj.join(m.local_table, m.inherit_condition)
            else:
                from_obj = from_obj.outerjoin(m.local_table, m.inherit_condition)
    return from_obj

