    return RelationshipProperty.Comparator(self.prop, self._parententity, adapt_to_entity=self._adapt_to_entity, of_type=class_, extra_criteria=self._extra_criteria)

def mark_exclude_cols(elem: SupportsAnnotations, annotations: _AnnotationDict) -> SupportsAnnotations:
    """note unrelated columns in the "extra criteria" as either
                should be adapted or not adapted, even though they are not
                part of our "local" or "remote" side.

                see #9779 for this case, as well as #11010 for a follow up

                """
    parentmapper_for_element = elem._annotations.get('parentmapper', None)
    if parentmapper_for_element is not self.prop.parent and (parentmapper_for_element is None or not parentmapper_for_element.isa(self.prop.mapper)) and (elem not in self._secondary_lineage_set):
        return _safe_annotate(elem, annotations)
    else:
        return elem

def __call__(self, **kw: Any) -> _S:
    """Return the current :class:`.Session`, creating it
        using the :attr:`.scoped_session.session_factory` if not present.

        :param \\**kw: Keyword arguments will be passed to the
         :attr:`.scoped_session.session_factory` callable, if an existing
         :class:`.Session` is not present.  If the :class:`.Session` is present
         and keyword arguments have been passed,
         :exc:`~sqlalchemy.exc.InvalidRequestError` is raised.

        """
    if kw:
        if self.registry.has():
            raise sa_exc.InvalidRequestError('Scoped session is already present; no new arguments may be specified.')
        else:
            sess = self.session_factory(**kw)
            self.registry.set(sess)
    else:
        sess = self.registry()
    if not self._support_async and sess._is_asyncio:
        warn_deprecated('Using `scoped_session` with asyncio is deprecated and will raise an error in a future version. Please use `async_scoped_session` instead.', '1.4.23')
    return sess

