@classmethod
def declare_states(cls, prerequisite_states: Union[Literal[_StateChangeStates.ANY], Tuple[_StateChangeState, ...]], moves_to: _StateChangeState) -> Callable[[_F], _F]:
    """Method decorator declaring valid states.

        :param prerequisite_states: sequence of acceptable prerequisite
         states.   Can be the single constant _State.ANY to indicate no
         prerequisite state

        :param moves_to: the expected state at the end of the method, assuming
         no exceptions raised.   Can be the constant _State.NO_CHANGE to
         indicate state should not change at the end of the method.

        """
    assert prerequisite_states, 'no prerequisite states sent'
    has_prerequisite_states = prerequisite_states is not _StateChangeStates.ANY
    prerequisite_state_collection = cast('Tuple[_StateChangeState, ...]', prerequisite_states)
    expect_state_change = moves_to is not _StateChangeStates.NO_CHANGE

    @util.decorator
    def _go(fn: _F, self: Any, *arg: Any, **kw: Any) -> Any:
        current_state = self._state
        if has_prerequisite_states and current_state not in prerequisite_state_collection:
            self._raise_for_prerequisite_state(fn.__name__, current_state)
        next_state = self._next_state
        existing_fn = self._current_fn
        expect_state = moves_to if expect_state_change else current_state
        if next_state is not _StateChangeStates.ANY and expect_state_change and (next_state is not expect_state):
            if existing_fn and next_state in (_StateChangeStates.NO_CHANGE, _StateChangeStates.CHANGE_IN_PROGRESS):
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' can't be called here; method '{existing_fn.__name__}()' is already in progress and this would cause an unexpected state change to {moves_to!r}", code='isce')
            else:
                raise sa_exc.IllegalStateChangeError(f"Can't run operation '{fn.__name__}()' here; will move to state {moves_to!r} where we are expecting {next_state!r}", code='isce')
        self._current_fn = fn
        self._next_state = _StateChangeStates.CHANGE_IN_PROGRESS
        try:
            ret_value = fn(self, *arg, **kw)
        except:
            raise
        else:
            if self._state is expect_state:
                return ret_value
            if self._state is current_state:
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' failed to change state to {moves_to!r} as expected", code='isce')
            elif existing_fn:
                raise sa_exc.IllegalStateChangeError(f"While method '{existing_fn.__name__}()' was running, method '{fn.__name__}()' caused an unexpected state change to {self._state!r}", code='isce')
            else:
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' caused an unexpected state change to {self._state!r}", code='isce')
        finally:
            self._next_state = next_state
            self._current_fn = existing_fn
    return _go

@contextlib.contextmanager
def _expect_state(self, expected: _StateChangeState) -> Iterator[Any]:
    """called within a method that changes states.

        method must also use the ``@declare_states()`` decorator.

        """
    assert self._next_state is _StateChangeStates.CHANGE_IN_PROGRESS, 'Unexpected call to _expect_state outside of state-changing method'
    self._next_state = expected
    try:
        yield
    except:
        raise
    else:
        if self._state is not expected:
            raise sa_exc.IllegalStateChangeError(f'Unexpected state change to {self._state!r}', code='isce')
    finally:
        self._next_state = _StateChangeStates.CHANGE_IN_PROGRESS

def setup_query(self, compile_state, query_entity, path, loadopt, adapter, column_collection=None, parentmapper=None, chained_from_outerjoin=False, **kwargs):
    """Add a left outer join to the statement that's being constructed."""
    if not compile_state.compile_options._enable_eagerloads:
        return
    elif loadopt and compile_state.statement is not None and compile_state.statement.is_dml:
        util.warn_deprecated('The joinedload loader option is not compatible with DML statements such as INSERT, UPDATE.  Only SELECT may be used.This warning will become an exception in a future release.', '2.0')
    elif self.uselist:
        compile_state.multi_row_eager_loaders = True
    path = path[self.parent_property]
    user_defined_adapter = self._init_user_defined_eager_proc(loadopt, compile_state, compile_state.attributes) if loadopt else False
    if user_defined_adapter is not False:
        clauses, adapter, add_to_collection = self._setup_query_on_user_defined_adapter(compile_state, query_entity, path, adapter, user_defined_adapter)
    else:
        if not path.contains(compile_state.attributes, 'loader'):
            if self.join_depth:
                if path.length / 2 > self.join_depth:
                    return
            elif path.contains_mapper(self.mapper):
                return
        clauses, adapter, add_to_collection, chained_from_outerjoin = self._generate_row_adapter(compile_state, query_entity, path, loadopt, adapter, column_collection, parentmapper, chained_from_outerjoin)
        compile_state.eager_adding_joins = True
    with_poly_entity = path.get(compile_state.attributes, 'path_with_polymorphic', None)
    if with_poly_entity is not None:
        with_polymorphic = inspect(with_poly_entity).with_polymorphic_mappers
    else:
        with_polymorphic = None
    path = path[self.entity]
    loading._setup_entity_query(compile_state, self.mapper, query_entity, path, clauses, add_to_collection, with_polymorphic=with_polymorphic, parentmapper=self.mapper, chained_from_outerjoin=chained_from_outerjoin)
    has_nones = util.NONE_SET.intersection(compile_state.secondary_columns)
    if has_nones:
        if with_poly_entity is not None:
            raise sa_exc.InvalidRequestError('Detected unaliased columns when generating joined load.  Make sure to use aliased=True or flat=True when using joined loading with with_polymorphic().')
        else:
            compile_state.secondary_columns = [c for c in compile_state.secondary_columns if c is not None]

def _parse_attr_argument(attr: _AttrType) -> Tuple[InspectionAttr, _InternalEntityType[Any], MapperProperty[Any]]:
    """parse an attribute or wildcard argument to produce an
    :class:`._AbstractLoad` instance.

    This is used by the standalone loader strategy functions like
    ``joinedload()``, ``defer()``, etc. to produce :class:`_orm.Load` or
    :class:`._WildcardLoad` objects.

    """
    try:
        insp: InspectionAttr = inspect(attr)
    except sa_exc.NoInspectionAvailable as err:
        raise sa_exc.ArgumentError('expected ORM mapped attribute for loader strategy argument') from err
    lead_entity: _InternalEntityType[Any]
    if insp_is_mapper_property(insp):
        lead_entity = insp.parent
        prop = insp
    elif insp_is_attribute(insp):
        lead_entity = insp.parent
        prop = insp.prop
    else:
        raise sa_exc.ArgumentError('expected ORM mapped attribute for loader strategy argument')
    return (insp, lead_entity, prop)

def _reconcile_query_entities_with_us(self, mapper_entities, raiseerr):
    """called at process time to allow adjustment of the root
        entity inside of _LoadElement objects.

        """
    path = self.path
    for ent in mapper_entities:
        ezero = ent.entity_zero
        if ezero and orm_util._entity_corresponds_to(ezero, cast('_InternalEntityType[Any]', path[0])):
            return ezero
    return None

@_generative
def options(self, *opts: _AbstractLoad) -> Self:
    """Apply a series of options as sub-options to this
        :class:`_orm.Load`
        object.

        E.g.::

            query = session.query(Author)
            query = query.options(
                joinedload(Author.book).options(
                    load_only(Book.summary, Book.excerpt),
                    joinedload(Book.citations).options(joinedload(Citation.author)),
                )
            )

        :param \\*opts: A series of loader option objects (ultimately
         :class:`_orm.Load` objects) which should be applied to the path
         specified by this :class:`_orm.Load` object.

        .. seealso::

            :func:`.defaultload`

            :ref:`orm_queryguide_relationship_sub_options`

        """
    for opt in opts:
        try:
            opt._apply_to_parent(self)
        except AttributeError as ae:
            if not isinstance(opt, _AbstractLoad):
                raise sa_exc.ArgumentError(f'Loader option {opt} is not compatible with the Load.options() method.') from ae
            else:
                raise
    return self

def _prepend_path_from(self, parent: Load) -> _LoadElement:
    """adjust the path of this :class:`._LoadElement` to be
        a subpath of that of the given parent :class:`_orm.Load` object's
        path.

        This is used by the :meth:`_orm.Load._apply_to_parent` method,
        which is in turn part of the :meth:`_orm.Load.options` method.

        """
    if not any((orm_util._entity_corresponds_to_use_path_impl(elem, self.path.odd_element(0)) for elem in (parent.path.odd_element(-1),) + parent.additional_source_entities)):
        raise sa_exc.ArgumentError(f'Attribute "{self.path[1]}" does not link from element "{entity_str(parent.path[-1])}".')
    return self._prepend_path(parent.path)

@staticmethod
def _reconcile(replacement: _LoadElement, existing: _LoadElement) -> _LoadElement:
    """define behavior for when two Load objects are to be put into
        the context.attributes under the same key.

        :param replacement: ``_LoadElement`` that seeks to replace the
         existing one

        :param existing: ``_LoadElement`` that is already present.

        """
    if replacement._reconcile_to_other:
        return existing
    elif replacement._reconcile_to_other is False:
        return replacement
    elif existing._reconcile_to_other:
        return replacement
    elif existing._reconcile_to_other is False:
        return existing
    if existing is replacement:
        return replacement
    elif existing.strategy == replacement.strategy and existing.local_opts == replacement.local_opts:
        return replacement
    elif replacement.is_opts_only:
        existing = existing._clone()
        existing.local_opts = existing.local_opts.union(replacement.local_opts)
        existing._extra_criteria += replacement._extra_criteria
        return existing
    elif existing.is_opts_only:
        replacement = replacement._clone()
        replacement.local_opts = replacement.local_opts.union(existing.local_opts)
        replacement._extra_criteria += existing._extra_criteria
        return replacement
    elif replacement.path.is_token:
        return replacement
    raise sa_exc.InvalidRequestError(f'Loader strategy replacement {replacement._to_option_method_string()} is in conflict with existing strategy {existing._to_option_method_string()}')

def _to_option_method_string(self) -> str:
    """Return a string representation of this :class:`._LoadElement`
        as it would be written as a loader option method call, e.g.
        ``"joinedload(User.orders)"``.

        """
    assert self.strategy is not None, 'to_option_method_string() requires a strategy to be set'
    for opt_key in self.local_opts:
        fn = _STRATEGY_FN_LABELS.get((self.strategy, opt_key))
        if fn:
            break
    else:
        fn = _STRATEGY_FN_LABELS.get((self.strategy, None))
    assert fn is not None, f'No _STRATEGY_FN_LABELS entry for strategy {self.strategy!r}'
    return f'{fn}({self.path.path_string()})'

def _source_modified(uowcommit, source, source_mapper, synchronize_pairs):
    """return true if the source object has changes from an old to a
    new value on the given synchronize pairs

    """
    for l, r in synchronize_pairs:
        try:
            prop = source_mapper._columntoproperty[l]
        except exc.UnmappedColumnError as err:
            _raise_col_to_prop(False, source_mapper, l, None, r, err)
        history = uowcommit.get_attribute_history(source, prop.key, PassiveFlag.PASSIVE_NO_INITIALIZE)
        if bool(history.deleted):
            return True
    else:
        return False

def was_already_deleted(self, state):
    """Return ``True`` if the given state is expired and was deleted
        previously.
        """
    if state.expired:
        try:
            state._load_expired(state, attributes.PASSIVE_OFF)
        except orm_exc.ObjectDeletedError:
            self.session._remove_newly_deleted([state])
            return True
    return False

@util.memoized_property
def _mapper_for_dep(self):
    """return a dynamic mapping of (Mapper, DependencyProcessor) to
        True or False, indicating if the DependencyProcessor operates
        on objects of that Mapper.

        The result is stored in the dictionary persistently once
        calculated.

        """
    return util.PopulateDict(lambda tup: tup[0]._props.get(tup[1].key) is tup[1].prop)

def _generate_actions(self):
    """Generate the full, unsorted collection of PostSortRecs as
        well as dependency pairs for this UOWTransaction.

        """
    while True:
        ret = False
        for action in list(self.presort_actions.values()):
            if action.execute(self):
                ret = True
        if not ret:
            break
    self.cycles = cycles = topological.find_cycles(self.dependencies, list(self.postsort_actions.values()))
    if cycles:
        convert = {rec: set(rec.per_state_flush_actions(self)) for rec in cycles}
        for edge in list(self.dependencies):
            if None in edge or edge[0].disabled or edge[1].disabled or cycles.issuperset(edge):
                self.dependencies.remove(edge)
            elif edge[0] in cycles:
                self.dependencies.remove(edge)
                for dep in convert[edge[0]]:
                    self.dependencies.add((dep, edge[1]))
            elif edge[1] in cycles:
                self.dependencies.remove(edge)
                for dep in convert[edge[1]]:
                    self.dependencies.add((edge[0], dep))
    return {a for a in self.postsort_actions.values() if not a.disabled}.difference(cycles)

def finalize_flush_changes(self) -> None:
    """Mark processed objects as clean / deleted after a successful
        flush().

        This method is called within the flush() method after the
        execute() method has succeeded and the transaction has been committed.

        """
    if not self.states:
        return
    states = set(self.states)
    isdel = {s for s, (isdelete, listonly) in self.states.items() if isdelete}
    other = states.difference(isdel)
    if isdel:
        self.session._remove_newly_deleted(isdel)
    if other:
        self.session._register_persistent(other)

def _validator_events(desc, key, validator, include_removes, include_backrefs):
    """Runs a validation method on an attribute value to be set or
    appended.
    """
    if not include_backrefs:

        def detect_is_backref(state, initiator):
            impl = state.manager[key].impl
            return initiator.impl is not impl
    if include_removes:

        def append(state, value, initiator):
            if initiator.op is not attributes.OP_BULK_REPLACE and (include_backrefs or not detect_is_backref(state, initiator)):
                return validator(state.obj(), key, value, False)
            else:
                return value

        def bulk_set(state, values, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                obj = state.obj()
                values[:] = [validator(obj, key, value, False) for value in values]

        def set_(state, value, oldvalue, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                return validator(state.obj(), key, value, False)
            else:
                return value

        def remove(state, value, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                validator(state.obj(), key, value, True)
    else:

        def append(state, value, initiator):
            if initiator.op is not attributes.OP_BULK_REPLACE and (include_backrefs or not detect_is_backref(state, initiator)):
                return validator(state.obj(), key, value)
            else:
                return value

        def bulk_set(state, values, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                obj = state.obj()
                values[:] = [validator(obj, key, value) for value in values]

        def set_(state, value, oldvalue, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                return validator(state.obj(), key, value)
            else:
                return value
    event.listen(desc, 'append', append, raw=True, retval=True)
    event.listen(desc, 'bulk_replace', bulk_set, raw=True)
    event.listen(desc, 'set', set_, raw=True, retval=True)
    if include_removes:
        event.listen(desc, 'remove', remove, raw=True, retval=True)

def polymorphic_union(table_map, typecolname, aliasname='p_union', cast_nulls=True):
    """Create a ``UNION`` statement used by a polymorphic mapper.

    See  :ref:`concrete_inheritance` for an example of how
    this is used.

    :param table_map: mapping of polymorphic identities to
     :class:`_schema.Table` objects.
    :param typecolname: string name of a "discriminator" column, which will be
     derived from the query, producing the polymorphic identity for
     each row.  If ``None``, no polymorphic discriminator is generated.
    :param aliasname: name of the :func:`~sqlalchemy.sql.expression.alias()`
     construct generated.
    :param cast_nulls: if True, non-existent columns, which are represented
     as labeled NULLs, will be passed into CAST.   This is a legacy behavior
     that is problematic on some backends such as Oracle - in which case it
     can be set to False.

    """
    colnames: util.OrderedSet[str] = util.OrderedSet()
    colnamemaps = {}
    types = {}
    for key in table_map:
        table = table_map[key]
        table = coercions.expect(roles.FromClauseRole, table)
        table_map[key] = table
        m = {}
        for c in table.c:
            if c.key == typecolname:
                raise sa_exc.InvalidRequestError("Polymorphic union can't use '%s' as the discriminator column due to mapped column %r; please apply the 'typecolname' argument; this is available on ConcreteBase as '_concrete_discriminator_name'" % (typecolname, c))
            colnames.add(c.key)
            m[c.key] = c
            types[c.key] = c.type
        colnamemaps[table] = m

    def col(name, table):
        try:
            return colnamemaps[table][name]
        except KeyError:
            if cast_nulls:
                return sql.cast(sql.null(), types[name]).label(name)
            else:
                return sql.type_coerce(sql.null(), types[name]).label(name)
    result = []
    for type_, table in table_map.items():
        if typecolname is not None:
            result.append(sql.select(*[col(name, table) for name in colnames] + [sql.literal_column(sql_util._quote_ddl_expr(type_)).label(typecolname)]).select_from(table))
        else:
            result.append(sql.select(*[col(name, table) for name in colnames]).select_from(table))
    return sql.union_all(*result).alias(aliasname)

def _entity_corresponds_to(given: _InternalEntityType[Any], entity: _InternalEntityType[Any]) -> bool:
    """determine if 'given' corresponds to 'entity', in terms
    of an entity passed to Query that would match the same entity
    being referred to elsewhere in the query.

    """
    if insp_is_aliased_class(entity):
        if insp_is_aliased_class(given):
            if entity._base_alias() is given._base_alias():
                return True
        return False
    elif insp_is_aliased_class(given):
        if given._use_mapper_path:
            return entity in given.with_polymorphic_mappers
        else:
            return entity is given
    assert insp_is_mapper(given)
    return entity.common_parent(given)

def _entity_corresponds_to_use_path_impl(given: _InternalEntityType[Any], entity: _InternalEntityType[Any]) -> bool:
    """determine if 'given' corresponds to 'entity', in terms
    of a path of loader options where a mapped attribute is taken to
    be a member of a parent entity.

    e.g.::

        someoption(A).someoption(A.b)  # -> fn(A, A) -> True
        someoption(A).someoption(C.d)  # -> fn(A, C) -> False

        a1 = aliased(A)
        someoption(a1).someoption(A.b)  # -> fn(a1, A) -> False
        someoption(a1).someoption(a1.b)  # -> fn(a1, a1) -> True

        wp = with_polymorphic(A, [A1, A2])
        someoption(wp).someoption(A1.foo)  # -> fn(wp, A1) -> False
        someoption(wp).someoption(wp.A1.foo)  # -> fn(wp, wp.A1) -> True

    """
    if insp_is_aliased_class(given):
        return insp_is_aliased_class(entity) and (not entity._use_mapper_path) and (given is entity or entity in given._with_polymorphic_entities)
    elif not insp_is_aliased_class(entity):
        return given.isa(entity.mapper)
    else:
        return entity._use_mapper_path and given in entity.with_polymorphic_mappers

def _entity_isa(given: _InternalEntityType[Any], mapper: Mapper[Any]) -> bool:
    """determine if 'given' "is a" mapper, in terms of the given
    would load rows of type 'mapper'.

    """
    if given.is_aliased_class:
        return mapper in given.with_polymorphic_mappers or given.mapper.isa(mapper)
    elif given.with_polymorphic_mappers:
        return mapper in given.with_polymorphic_mappers or given.isa(mapper)
    else:
        return given.isa(mapper)

def _getitem(iterable_query: Query[Any], item: Any) -> Any:
    """calculate __getitem__ in terms of an iterable query object
    that also has a slice() method.

    """

    def _no_negative_indexes():
        raise IndexError('negative indexes are not accepted by SQL index / slice operators')
    if isinstance(item, slice):
        start, stop, step = util.decode_slice(item)
        if isinstance(stop, int) and isinstance(start, int) and (stop - start <= 0):
            return []
        elif isinstance(start, int) and start < 0 or (isinstance(stop, int) and stop < 0):
            _no_negative_indexes()
        res = iterable_query.slice(start, stop)
        if step is not None:
            return list(res)[None:None:item.step]
        else:
            return list(res)
    elif item == -1:
        _no_negative_indexes()
    else:
        return list(iterable_query[item:item + 1])[0]

def _extract_mapped_subtype(raw_annotation: Optional[_AnnotationScanType], cls: type, originating_module: str, key: str, attr_cls: Type[Any], required: bool, is_dataclass_field: bool, expect_mapped: bool=True, raiseerr: bool=True) -> Optional[Tuple[Union[_AnnotationScanType, str], Optional[type]]]:
    """given an annotation, figure out if it's ``Mapped[something]`` and if
    so, return the ``something`` part.

    Includes error raise scenarios and other options.

    """
    if raw_annotation is None:
        if required:
            raise orm_exc.MappedAnnotationError(f'Python typing annotation is required for attribute "{cls.__name__}.{key}" when primary argument(s) for "{attr_cls.__name__}" construct are None or not present')
        return None
    try:
        annotated = de_stringify_annotation(cls, raw_annotation, originating_module, str_cleanup_fn=_cleanup_mapped_str_annotation)
    except _CleanupError as ce:
        raise orm_exc.MappedAnnotationError(f'Could not interpret annotation {raw_annotation}.  Check that it uses names that are correctly imported at the module level. See chained stack trace for more hints.') from ce
    except NameError as ne:
        if raiseerr and 'Mapped[' in raw_annotation:
            raise orm_exc.MappedAnnotationError(f'Could not interpret annotation {raw_annotation}.  Check that it uses names that are correctly imported at the module level. See chained stack trace for more hints.') from ne
        annotated = raw_annotation
    if is_dataclass_field:
        return (annotated, None)
    else:
        if not hasattr(annotated, '__origin__') or not is_origin_of_cls(annotated, _MappedAnnotationBase):
            if expect_mapped:
                if not raiseerr:
                    return None
                origin = getattr(annotated, '__origin__', None)
                if origin is typing.ClassVar:
                    return None
                elif isinstance(origin, type) and issubclass(origin, ORMDescriptor):
                    return None
                raise orm_exc.MappedAnnotationError(f'''Type annotation for "{cls.__name__}.{key}" can't be correctly interpreted for Annotated Declarative Table form.  ORM annotations should normally make use of the ``Mapped[]`` generic type, or other ORM-compatible generic type, as a container for the actual type, which indicates the intent that the attribute is mapped. Class variables that are not intended to be mapped by the ORM should use ClassVar[].  To allow Annotated Declarative to disregard legacy annotations which don't use Mapped[] to pass, set "__allow_unmapped__ = True" on the class or a superclass this class.''', code='zlpr')
            else:
                return (annotated, None)
        generic_annotated = cast(GenericProtocol[Any], annotated)
        if len(generic_annotated.__args__) != 1:
            raise orm_exc.MappedAnnotationError('Expected sub-type for Mapped[] annotation')
        return (fixup_container_fwd_refs(generic_annotated.__args__[0]), generic_annotated.__origin__)

def path_string(self) -> str:
    """Return a user-facing name for this :class:`.AliasedInsp`,
        for use in a :class:`_orm.PathRegistry` string representation.

        """
    if self._is_with_polymorphic:
        return 'with_polymorphic(%s, [%s])' % (self._target.__name__, ', '.join((mp.class_.__name__ for mp in self.with_polymorphic_mappers if mp is not self.mapper)))
    else:
        return 'aliased(%s)' % (self._target.__name__,)

def create_row_processor(self, query: Select[Unpack[TupleAny]], procs: Sequence[Callable[[Row[Unpack[TupleAny]]], Any]], labels: Sequence[str]) -> Callable[[Row[Unpack[TupleAny]]], Any]:
    """Produce the "row processing" function for this :class:`.Bundle`.

        May be overridden by subclasses to provide custom behaviors when
        results are fetched. The method is passed the statement object and a
        set of "row processor" functions at query execution time; these
        processor functions when given a result row will return the individual
        attribute value, which can then be adapted into any kind of return data
        structure.

        The example below illustrates replacing the usual :class:`.Row`
        return structure with a straight Python dictionary::

            from sqlalchemy.orm import Bundle


            class DictBundle(Bundle):
                def create_row_processor(self, query, procs, labels):
                    "Override create_row_processor to return values as dictionaries"

                    def proc(row):
                        return dict(zip(labels, (proc(row) for proc in procs)))

                    return proc

        A result from the above :class:`_orm.Bundle` will return dictionary
        values::

            bn = DictBundle("mybundle", MyClass.data1, MyClass.data2)
            for row in session.execute(select(bn)).where(bn.c.data1 == "d1"):
                print(row.mybundle["data1"], row.mybundle["data2"])

        The above example is available natively using :class:`.DictBundle`

        .. seealso::

            :class:`.DictBundle`

        """
    keyed_tuple = result_tuple(labels, [() for l in labels])

    def proc(row: Row[Unpack[TupleAny]]) -> Any:
        return keyed_tuple([proc(row) for proc in procs])
    return proc

def _splice_into_center(self, other):
    """Splice a join into the center.

        Given join(a, b) and join(b, c), return join(a, b).join(c)

        """
    leftmost = other
    while isinstance(leftmost, sql.Join):
        leftmost = leftmost.left
    assert self.right is leftmost
    left = _ORMJoin(self.left, other.left, self.onclause, isouter=self.isouter, _left_memo=self._left_memo, _right_memo=other._left_memo._path_registry)
    return _ORMJoin(left, other.right, other.onclause, isouter=other.isouter, _right_memo=other._right_memo)

def select(self) -> Select[_T]:
    """Produce a :class:`_sql.Select` construct that represents the
        rows within this instance-local :class:`_orm.WriteOnlyCollection`.

        """
    stmt = select(self.attr.target_mapper).where(*self._where_criteria)
    if self._from_obj:
        stmt = stmt.select_from(*self._from_obj)
    if self._order_by_clauses:
        stmt = stmt.order_by(*self._order_by_clauses)
    return stmt

def update(self) -> Update:
    """Produce a :class:`_dml.Update` which will refer to rows in terms
        of this instance-local :class:`_orm.WriteOnlyCollection`.

        """
    return update(self.attr.target_mapper).where(*self._where_criteria)

def delete(self) -> Delete:
    """Produce a :class:`_dml.Delete` which will refer to rows in terms
        of this instance-local :class:`_orm.WriteOnlyCollection`.

        """
    return delete(self.attr.target_mapper).where(*self._where_criteria)

@util.deprecated('1.4', 'The :class:`.AliasOption` object is not necessary for entities to be matched up to a query that is established via :meth:`.Query.from_statement` and now does nothing.', enable_warnings=False)
def contains_alias(alias: Union[Alias, Subquery]) -> AliasOption:
    """Return a :class:`.MapperOption` that will indicate to the
    :class:`_query.Query`
    that the main table has been aliased.

    """
    return AliasOption(alias)

def _finalize_fairy(dbapi_connection: Optional[DBAPIConnection], connection_record: Optional[_ConnectionRecord], pool: Pool, ref: Optional[weakref.ref[_ConnectionFairy]], echo: Optional[log._EchoFlagType], transaction_was_reset: bool=False, fairy: Optional[_ConnectionFairy]=None) -> None:
    """Cleanup for a :class:`._ConnectionFairy` whether or not it's already
    been garbage collected.

    When using an async dialect no IO can happen here (without using
    a dedicated thread), since this is called outside the greenlet
    context and with an already running loop. In this case function
    will only log a message and raise a warning.
    """
    is_gc_cleanup = ref is not None
    if is_gc_cleanup:
        assert ref is not None
        _strong_ref_connection_records.pop(ref, None)
        assert connection_record is not None
        if connection_record.fairy_ref is not ref:
            return
        assert dbapi_connection is None
        dbapi_connection = connection_record.dbapi_connection
    elif fairy:
        _strong_ref_connection_records.pop(weakref.ref(fairy), None)
    dont_restore_gced = pool._dialect.is_async
    if dont_restore_gced:
        detach = connection_record is None or is_gc_cleanup
        can_manipulate_connection = not is_gc_cleanup
        can_close_or_terminate_connection = not pool._dialect.is_async or pool._dialect.has_terminate
        requires_terminate_for_close = pool._dialect.is_async and pool._dialect.has_terminate
    else:
        detach = connection_record is None
        can_manipulate_connection = can_close_or_terminate_connection = True
        requires_terminate_for_close = False
    if dbapi_connection is not None:
        if connection_record and echo:
            pool.logger.debug('Connection %r being returned to pool', dbapi_connection)
        try:
            if not fairy:
                assert connection_record is not None
                fairy = _ConnectionFairy(pool, dbapi_connection, connection_record, echo)
            assert fairy.dbapi_connection is dbapi_connection
            fairy._reset(pool, transaction_was_reset=transaction_was_reset, terminate_only=detach, asyncio_safe=can_manipulate_connection)
            if detach:
                if connection_record:
                    fairy._pool = pool
                    fairy.detach()
                if can_close_or_terminate_connection:
                    if pool.dispatch.close_detached:
                        pool.dispatch.close_detached(dbapi_connection)
                    pool._close_connection(dbapi_connection, terminate=requires_terminate_for_close)
        except BaseException as e:
            pool.logger.error('Exception during reset or similar', exc_info=True)
            if connection_record:
                connection_record.invalidate(e=e)
            if not isinstance(e, Exception):
                raise
        finally:
            if detach and is_gc_cleanup and dont_restore_gced:
                message = f"The garbage collector is trying to clean up non-checked-in connection {dbapi_connection!r}, which will be {('dropped, as it cannot be safely terminated' if not can_close_or_terminate_connection else 'terminated')}.  Please ensure that SQLAlchemy pooled connections are returned to the pool explicitly, either by calling ``close()`` or by using appropriate context managers to manage their lifecycle."
                pool.logger.error(message)
                util.warn(message)
    if connection_record and connection_record.fairy_ref is not None:
        connection_record.checkin()
    if fairy is not None:
        fairy.dbapi_connection = None
        fairy._connection_record = None
    del dbapi_connection
    del connection_record
    del fairy

def _should_wrap_creator(self, creator: Union[_CreatorFnType, _CreatorWRecFnType]) -> _CreatorWRecFnType:
    """Detect if creator accepts a single argument, or is sent
        as a legacy style no-arg function.

        """
    try:
        argspec = util.get_callable_argspec(self._creator, no_self=True)
    except TypeError:
        creator_fn = cast(_CreatorFnType, creator)
        return lambda rec: creator_fn()
    if argspec.defaults is not None:
        defaulted = len(argspec.defaults)
    else:
        defaulted = 0
    positionals = len(argspec[0]) - defaulted
    if (argspec[0], argspec[3]) == (['connection_record'], (None,)):
        return cast(_CreatorWRecFnType, creator)
    elif positionals == 1:
        return cast(_CreatorWRecFnType, creator)
    else:
        creator_fn = cast(_CreatorFnType, creator)
        return lambda rec: creator_fn()

def status(self) -> str:
    """Returns a brief description of the state of this pool."""
    raise NotImplementedError()

def close(self) -> None:
    """Close the DBAPI connection managed by this connection pool entry."""
    raise NotImplementedError()

@property
def is_valid(self) -> bool:
    """Return True if this :class:`.PoolProxiedConnection` still refers
        to an active DBAPI connection."""
    raise NotImplementedError()

@property
def is_detached(self) -> bool:
    """Return True if this :class:`.PoolProxiedConnection` is detached
        from its pool."""
    raise NotImplementedError()

def _deep_annotate(element: _SA, annotations: _AnnotationDict, exclude: Optional[Sequence[SupportsAnnotations]]=None, *, detect_subquery_cols: bool=False, ind_cols_on_fromclause: bool=False, annotate_callable: Optional[Callable[[SupportsAnnotations, _AnnotationDict], SupportsAnnotations]]=None) -> _SA:
    """Deep copy the given ClauseElement, annotating each element
    with the given annotations dictionary.

    Elements within the exclude collection will be cloned but not annotated.

    """
    cloned_ids: Dict[int, SupportsAnnotations] = {}

    def clone(elem: SupportsAnnotations, **kw: Any) -> SupportsAnnotations:
        kw['detect_subquery_cols'] = detect_subquery_cols
        id_ = id(elem)
        if id_ in cloned_ids:
            return cloned_ids[id_]
        if exclude and hasattr(elem, 'proxy_set') and elem.proxy_set.intersection(exclude):
            newelem = elem._clone(clone=clone, **kw)
        elif annotations != elem._annotations:
            if detect_subquery_cols and elem._is_immutable:
                to_annotate = elem._clone(clone=clone, **kw)
            else:
                to_annotate = elem
            if annotate_callable:
                newelem = annotate_callable(to_annotate, annotations)
            else:
                newelem = _safe_annotate(to_annotate, annotations)
        else:
            newelem = elem
        newelem._copy_internals(clone=clone, ind_cols_on_fromclause=ind_cols_on_fromclause, _annotations_traversal=True)
        cloned_ids[id_] = newelem
        return newelem
    if element is not None:
        element = cast(_SA, clone(element))
    clone = None
    return element

def _new_annotation_type(cls: Type[SupportsWrappingAnnotations], base_cls: Type[Annotated]) -> Type[Annotated]:
    """Generates a new class that subclasses Annotated and proxies a given
    element type.

    """
    if issubclass(cls, Annotated):
        return cls
    elif cls in annotated_classes:
        return annotated_classes[cls]
    for super_ in cls.__mro__:
        if super_ in annotated_classes:
            base_cls = annotated_classes[super_]
            break
    annotated_classes[cls] = anno_cls = cast(Type[Annotated], type('Annotated%s' % cls.__name__, (base_cls, cls), {}))
    globals()['Annotated%s' % cls.__name__] = anno_cls
    if '_traverse_internals' in cls.__dict__:
        anno_cls._traverse_internals = list(cls._traverse_internals) + [('_annotations', InternalTraversal.dp_annotations_key)]
    elif cls.__dict__.get('inherit_cache', False):
        anno_cls._traverse_internals = list(cls._traverse_internals) + [('_annotations', InternalTraversal.dp_annotations_key)]
    if cls.__dict__.get('inherit_cache', False):
        anno_cls.inherit_cache = True
    elif 'inherit_cache' in cls.__dict__:
        anno_cls.inherit_cache = cls.__dict__['inherit_cache']
    anno_cls._is_column_operators = issubclass(cls, operators.ColumnOperators)
    return anno_cls

def _annotate(self, values: _AnnotationDict) -> Self:
    """return a copy of this ClauseElement with annotations
        updated by the given dictionary.

        """
    return Annotated._as_annotated_instance(self, values)

def _with_annotations(self, values: _AnnotationDict) -> Self:
    """return a copy of this ClauseElement with annotations
        replaced by the given dictionary.

        """
    return Annotated._as_annotated_instance(self, values)

def _select_iterables(elements: Iterable[roles.ColumnsClauseRole]) -> _SelectIterable:
    """expand tables into individual columns in the
    given list of column expressions.

    """
    return itertools.chain.from_iterable([c._select_iterable for c in elements])

def _expand_cloned(elements: Iterable[_CLE]) -> Iterable[_CLE]:
    """expand the given set of ClauseElements to be the set of all 'cloned'
    predecessors.

    """
    return itertools.chain(*[x._cloned_set for x in elements])

def _entity_namespace(entity: Union[_HasEntityNamespace, ExternallyTraversible]) -> _EntityNamespace:
    """Return the nearest .entity_namespace for the given entity.

    If not immediately available, does an iterate to find a sub-element
    that has one, if any.

    """
    try:
        return cast(_HasEntityNamespace, entity).entity_namespace
    except AttributeError:
        for elem in visitors.iterate(cast(ExternallyTraversible, entity)):
            if _is_has_entity_namespace(elem):
                return elem.entity_namespace
        else:
            raise

def _entity_namespace_key(entity: Union[_HasEntityNamespace, ExternallyTraversible], key: str, default: Union[SQLCoreOperations[Any], _T, _NoArg]=NO_ARG) -> Union[SQLCoreOperations[Any], _T]:
    """Return an entry from an entity_namespace.


    Raises :class:`_exc.InvalidRequestError` rather than attribute error
    on not found.

    """
    try:
        ns = _entity_namespace(entity)
        if default is not NO_ARG:
            return getattr(ns, key, default)
        else:
            return getattr(ns, key)
    except AttributeError as err:
        raise exc.InvalidRequestError('Entity namespace for "%s" has no property "%s"' % (entity, key)) from err

@classmethod
def from_execution_options(cls, key: str, attrs: set[str], exec_options: Mapping[str, Any], statement_exec_options: Mapping[str, Any]) -> Tuple['Options', Mapping[str, Any]]:
    """process Options argument in terms of execution options.


        e.g.::

            (
                load_options,
                execution_options,
            ) = QueryContext.default_load_options.from_execution_options(
                "_sa_orm_load_options",
                {"populate_existing", "autoflush", "yield_per"},
                execution_options,
                statement._execution_options,
            )

        get back the Options and refresh "_sa_orm_load_options" in the
        exec options dict w/ the Options as well

        """
    check_argnames = attrs.intersection(set(exec_options).union(statement_exec_options))
    existing_options = exec_options.get(key, cls)
    if check_argnames:
        result = {}
        for argname in check_argnames:
            local = '_' + argname
            if argname in exec_options:
                result[local] = exec_options[argname]
            elif argname in statement_exec_options:
                result[local] = statement_exec_options[argname]
        new_options = existing_options + result
        exec_options = util.EMPTY_DICT.merge_with(exec_options, {key: new_options})
        return (new_options, exec_options)
    else:
        return (existing_options, exec_options)

@_generative
def params(self, __optionaldict: _CoreSingleExecuteParams | None=None, /, **kwargs: Any) -> Self:
    """Return a copy with the provided bindparam values.

        Returns a copy of this Executable with bindparam values set
        to the given dictionary::

          >>> clause = column("x") + bindparam("foo")
          >>> print(clause.compile().params)
          {'foo': None}
          >>> print(clause.params({"foo": 7}).compile().params)
          {'foo': 7}

        """
    if __optionaldict:
        kwargs.update(__optionaldict)
    self._params = util.immutabledict(kwargs) if not self._params else self._params | kwargs
    return self

def compare(self, other: ColumnCollection[_COLKEY, _COL_co]) -> bool:
    """Compare this :class:`_expression.ColumnCollection` to another
        based on the names of the keys"""
    for l, r in zip_longest(self, other):
        if l is not r:
            return False
    else:
        return True

def get(self, key: str, default: Optional[_COL]=None) -> Optional[Union[_COL_co, _COL]]:
    """Get a :class:`_sql.ColumnClause` or :class:`_schema.Column` object
        based on a string key name from this
        :class:`_expression.ColumnCollection`."""
    if key in self._index:
        return self._index[key][1]
    else:
        return default

def replace(self, column: _NAMEDCOL, *, extra_remove: Optional[Iterable[_NAMEDCOL]]=None, index: Optional[int]=None) -> None:
    """add the given column to this collection, removing unaliased
        versions of this column  as well as existing columns with the
        same key.

        e.g.::

            t = Table("sometable", metadata, Column("col1", Integer))
            t.columns.replace(Column("col1", Integer, key="columnone"))

        will remove the original 'col1' from the collection, and add
        the new column under the name 'columnname'.

        Used by schema.Column to override columns during table reflection.

        """
    if extra_remove:
        remove_col = set(extra_remove)
    else:
        remove_col = set()
    if column.name in self._index and column.key != column.name:
        other = self._index[column.name][1]
        if other.name == other.key:
            remove_col.add(other)
    if column.key in self._index:
        remove_col.add(self._index[column.key][1])
    if not remove_col:
        self._append_new_column(column.key, column, index=index)
        return
    new_cols: List[Tuple[str, _NAMEDCOL, _ColumnMetrics[_NAMEDCOL]]] = []
    replace_index = None
    for idx, (k, col, metrics) in enumerate(self._collection):
        if col in remove_col:
            if replace_index is None:
                replace_index = idx
                new_cols.append((column.key, column, _ColumnMetrics(self, column)))
        else:
            new_cols.append((k, col, metrics))
    if remove_col:
        self._colset.difference_update(remove_col)
        for rc in remove_col:
            for metrics in self._proxy_index.get(rc, ()):
                metrics.dispose(self)
    if replace_index is None:
        if index is not None:
            new_cols.insert(index, (column.key, column, _ColumnMetrics(self, column)))
        else:
            new_cols.append((column.key, column, _ColumnMetrics(self, column)))
    elif index is not None:
        to_move = new_cols[replace_index]
        effective_positive_index = index if index >= 0 else max(0, len(new_cols) + index)
        new_cols.insert(index, to_move)
        if replace_index > effective_positive_index:
            del new_cols[replace_index + 1]
        else:
            del new_cols[replace_index]
    self._colset.add(column._deannotate())
    self._collection[:] = new_cols
    self._index.clear()
    self._index.update({idx: (k, col) for idx, (k, col, _) in enumerate(self._collection)})
    self._index.update({k: (k, col) for k, col, _ in self._collection})

@classmethod
def _generate_cache_attrs(cls) -> Union[_CacheKeyTraversalDispatchType, Literal[CacheConst.NO_CACHE]]:
    """generate cache key dispatcher for a new class.

        This sets the _generated_cache_key_traversal attribute once called
        so should only be called once per class.

        """
    inherit_cache = cls.__dict__.get('inherit_cache', None)
    inherit = bool(inherit_cache)
    if inherit:
        _cache_key_traversal = getattr(cls, '_cache_key_traversal', None)
        if _cache_key_traversal is None:
            try:
                assert issubclass(cls, HasTraverseInternals)
                _cache_key_traversal = cls._traverse_internals
            except AttributeError:
                cls._generated_cache_key_traversal = NO_CACHE
                return NO_CACHE
        assert _cache_key_traversal is not NO_CACHE, f'class {cls} has _cache_key_traversal=NO_CACHE, which conflicts with inherit_cache=True'
        return _cache_key_traversal_visitor.generate_dispatch(cls, _cache_key_traversal, '_generated_cache_key_traversal')
    else:
        _cache_key_traversal = cls.__dict__.get('_cache_key_traversal', None)
        if _cache_key_traversal is None:
            _cache_key_traversal = cls.__dict__.get('_traverse_internals', None)
            if _cache_key_traversal is None:
                cls._generated_cache_key_traversal = NO_CACHE
                if inherit_cache is None and cls._hierarchy_supports_caching:
                    util.warn("Class %s will not make use of SQL compilation caching as it does not set the 'inherit_cache' attribute to ``True``.  This can have significant performance implications including some performance degradations in comparison to prior SQLAlchemy versions.  Set this attribute to True if this object can make use of the cache key generated by the superclass.  Alternatively, this attribute may be set to False which will disable this warning." % cls.__name__, code='cprf')
                return NO_CACHE
        return _cache_key_traversal_visitor.generate_dispatch(cls, _cache_key_traversal, '_generated_cache_key_traversal')

@util.preload_module('sqlalchemy.sql.elements')
def _gen_cache_key(self, anon_map: anon_map, bindparams: List[BindParameter[Any]]) -> Optional[Tuple[Any, ...]]:
    """return an optional cache key.

        The cache key is a tuple which can contain any series of
        objects that are hashable and also identifies
        this object uniquely within the presence of a larger SQL expression
        or statement, for the purposes of caching the resulting query.

        The cache key should be based on the SQL compiled structure that would
        ultimately be produced.   That is, two structures that are composed in
        exactly the same way should produce the same cache key; any difference
        in the structures that would affect the SQL string or the type handlers
        should result in a different cache key.

        If a structure cannot produce a useful cache key, the NO_CACHE
        symbol should be added to the anon_map and the method should
        return None.

        """
    cls = self.__class__
    id_, found = anon_map.get_anon(self)
    if found:
        return (id_, cls)
    dispatcher: Union[Literal[CacheConst.NO_CACHE], _CacheKeyTraversalDispatchType]
    try:
        dispatcher = cls.__dict__['_generated_cache_key_traversal']
    except KeyError:
        dispatcher = cls._generate_cache_attrs()
    if dispatcher is NO_CACHE:
        anon_map[NO_CACHE] = True
        return None
    result: Tuple[Any, ...] = (id_, cls)
    for attrname, obj, meth in dispatcher(self, _cache_key_traversal_visitor):
        if obj is not None:
            if meth is STATIC_CACHE_KEY:
                sck = obj._static_cache_key
                if sck is NO_CACHE:
                    anon_map[NO_CACHE] = True
                    return None
                result += (attrname, sck)
            elif meth is ANON_NAME:
                elements = util.preloaded.sql_elements
                if isinstance(obj, elements._anonymous_label):
                    obj = obj.apply_map(anon_map)
                result += (attrname, obj)
            elif meth is CALL_GEN_CACHE_KEY:
                result += (attrname, obj._gen_cache_key(anon_map, bindparams))
            elif obj:
                if meth is CACHE_IN_PLACE:
                    result += (attrname, obj)
                elif meth is PROPAGATE_ATTRS:
                    result += (attrname, obj['compile_state_plugin'], obj['plugin_subject']._gen_cache_key(anon_map, bindparams) if obj['plugin_subject'] else None)
                elif meth is InternalTraversal.dp_annotations_key:
                    if self._gen_static_annotations_cache_key:
                        result += self._annotations_cache_key
                    else:
                        result += self._gen_annotations_cache_key(anon_map)
                elif meth is InternalTraversal.dp_clauseelement_list or meth is InternalTraversal.dp_clauseelement_tuple or meth is InternalTraversal.dp_memoized_select_entities:
                    result += (attrname, tuple([elem._gen_cache_key(anon_map, bindparams) for elem in obj]))
                else:
                    result += meth(attrname, obj, self, anon_map, bindparams)
    return result

def __hash__(self) -> Optional[int]:
    """CacheKey itself is not hashable - hash the .key portion"""
    return None

def _is_literal(element: Any) -> bool:
    """Return whether or not the element is a "literal" in the context
    of a SQL expression construct.

    """
    return not isinstance(element, (Visitable, schema.SchemaEventTarget)) and (not hasattr(element, '__clause_element__'))

def _deep_is_literal(element):
    """Return whether or not the element is a "literal" in the context
    of a SQL expression construct.

    does a deeper more esoteric check than _is_literal.   is used
    for lambda elements that have to distinguish values that would
    be bound vs. not without any context.

    """
    if isinstance(element, collections_abc.Sequence) and (not isinstance(element, str)):
        for elem in element:
            if not _deep_is_literal(elem):
                return False
        else:
            return True
    return not isinstance(element, (Visitable, schema.SchemaEventTarget, HasCacheKey, Options, util.langhelpers.symbol)) and (not hasattr(element, '__clause_element__')) and (not isinstance(element, type) or not issubclass(element, HasCacheKey))

def _literal_coercion(self, element, **kw):
    """coerce the given value to :class:`._truncated_label`.

        Existing :class:`._truncated_label` and
        :class:`._anonymous_label` objects are passed
        unchanged.
        """
    if isinstance(element, elements._truncated_label):
        return element
    else:
        return elements._truncated_label(element)

@property
def positional_parameters(self) -> Tuple[Any, ...]:
    """Tuple of positional parameters, for statements that were compiled
        using a positional paramstyle.

        """
    if self.positiontup is None:
        raise exc.InvalidRequestError('statement does not use a positional paramstyle')
    return tuple((self.parameters[key] for key in self.positiontup))

@property
def sql_compiler(self) -> SQLCompiler:
    """Return a Compiled that is capable of processing SQL expressions.

        If this compiler is one, it would likely just return 'self'.

        """
    raise NotImplementedError()

def __str__(self) -> str:
    """Return the string text of the generated SQL or DDL."""
    if self.state is CompilerState.STRING_APPLIED:
        return self.string
    else:
        return ''

def __init__(self, dialect: Dialect, statement: Optional[ClauseElement], cache_key: Optional[CacheKey]=None, column_keys: Optional[Sequence[str]]=None, for_executemany: bool=False, linting: Linting=NO_LINTING, _supporting_against: Optional[SQLCompiler]=None, **kwargs: Any):
    """Construct a new :class:`.SQLCompiler` object.

        :param dialect: :class:`.Dialect` to be used

        :param statement: :class:`_expression.ClauseElement` to be compiled

        :param column_keys:  a list of column names to be compiled into an
         INSERT or UPDATE statement.

        :param for_executemany: whether INSERT / UPDATE statements should
         expect that they are to be invoked in an "executemany" style,
         which may impact how the statement will be expected to return the
         values of defaults and autoincrement / sequences and similar.
         Depending on the backend and driver in use, support for retrieving
         these values may be disabled which means SQL expressions may
         be rendered inline, RETURNING may not be rendered, etc.

        :param kwargs: additional keyword arguments to be consumed by the
         superclass.

        """
    self.column_keys = column_keys
    self.cache_key = cache_key
    if cache_key:
        cksm = {b.key: b for b in cache_key[1]}
        ckbm = {b: [b] for b in cache_key[1]}
        self._cache_key_bind_match = (ckbm, cksm)
    self.for_executemany = for_executemany
    self.linting = linting
    self.binds = {}
    self.bind_names = util.column_dict()
    self.stack = []
    self._result_columns = []
    self.positional = dialect.positional
    if self.positional:
        self._numeric_binds = nb = dialect.paramstyle.startswith('numeric')
        if nb:
            self._numeric_binds_identifier_char = '$' if dialect.paramstyle == 'numeric_dollar' else ':'
        self.compilation_bindtemplate = _pyformat_template
    else:
        self.compilation_bindtemplate = BIND_TEMPLATES[dialect.paramstyle]
    self.ctes = None
    self.label_length = dialect.label_length or dialect.max_identifier_length
    self.anon_map = prefix_anon_map()
    self.truncated_names: Dict[Tuple[str, str], str] = {}
    self._truncated_counters: Dict[str, int] = {}
    if not cache_key:
        self._collect_params = True
        self._collected_params = util.EMPTY_DICT
    else:
        self._collect_params = False
    Compiled.__init__(self, dialect, statement, **kwargs)
    if self.isinsert or self.isupdate or self.isdelete:
        if TYPE_CHECKING:
            assert isinstance(statement, UpdateBase)
        if self.isinsert or self.isupdate:
            if TYPE_CHECKING:
                assert isinstance(statement, ValuesBase)
            if statement._inline:
                self.inline = True
            elif self.for_executemany and (not self.isinsert or (self.dialect.insert_executemany_returning and statement._return_defaults)):
                self.inline = True
    self.bindtemplate = BIND_TEMPLATES[dialect.paramstyle]
    if _supporting_against:
        self.__dict__.update({k: v for k, v in _supporting_against.__dict__.items() if k not in {'state', 'dialect', 'preparer', 'positional', '_numeric_binds', 'compilation_bindtemplate', 'bindtemplate'}})
    if self.state is CompilerState.STRING_APPLIED:
        if self.positional:
            if self._numeric_binds:
                self._process_numeric()
            else:
                self._process_positional()
        if self._render_postcompile:
            parameters = self.construct_params(escape_names=False, _no_postcompile=True)
            self._process_parameters_for_postcompile(parameters, _populate_self=True)

@util.ro_memoized_property
def effective_returning(self) -> Optional[Sequence[ColumnElement[Any]]]:
    """The effective "returning" columns for INSERT, UPDATE or DELETE.

        This is either the so-called "implicit returning" columns which are
        calculated by the compiler on the fly, or those present based on what's
        present in ``self.statement._returning`` (expanded into individual
        columns using the ``._all_selected_columns`` attribute) i.e. those set
        explicitly using the :meth:`.UpdateBase.returning` method.

        .. versionadded:: 2.0

        """
    if self.implicit_returning:
        return self.implicit_returning
    elif self.statement is not None and is_dml(self.statement):
        return [c for c in self.statement._all_selected_columns if is_column_element(c)]
    else:
        return None

@util.memoized_instancemethod
def _init_cte_state(self) -> MutableMapping[CTE, str]:
    """Initialize collections related to CTEs only if
        a CTE is located, to save on the overhead of
        these collections otherwise.

        """
    ctes: MutableMapping[CTE, str] = util.OrderedDict()
    self.ctes = ctes
    self.ctes_by_level_name = {}
    self.level_name_by_cte = {}
    self.ctes_recursive = False
    return ctes

@contextlib.contextmanager
def _nested_result(self):
    """special API to support the use case of 'nested result sets'"""
    result_columns, ordered_columns = (self._result_columns, self._ordered_columns)
    self._result_columns, self._ordered_columns = ([], False)
    try:
        if self.stack:
            entry = self.stack[-1]
            entry['need_result_map_for_nested'] = True
        else:
            entry = None
        yield (self._result_columns, self._ordered_columns)
    finally:
        if entry:
            entry.pop('need_result_map_for_nested')
        self._result_columns, self._ordered_columns = (result_columns, ordered_columns)

@property
def params(self):
    """Return the bind param dictionary embedded into this
        compiled object, for those values that are present.

        .. seealso::

            :ref:`faq_sql_expression_string` - includes a usage example for
            debugging use cases.

        """
    return self.construct_params(_check=False)

def _process_parameters_for_postcompile(self, parameters: _MutableCoreSingleExecuteParams, _populate_self: bool=False) -> ExpandedState:
    """handle special post compile parameters.

        These include:

        * "expanding" parameters -typically IN tuples that are rendered
          on a per-parameter basis for an otherwise fixed SQL statement string.

        * literal_binds compiled with the literal_execute flag.  Used for
          things like SQL Server "TOP N" where the driver does not accommodate
          N as a bound parameter.

        """
    expanded_parameters = {}
    new_positiontup: Optional[List[str]]
    pre_expanded_string = self._pre_expanded_string
    if pre_expanded_string is None:
        pre_expanded_string = self.string
    if self.positional:
        new_positiontup = []
        pre_expanded_positiontup = self._pre_expanded_positiontup
        if pre_expanded_positiontup is None:
            pre_expanded_positiontup = self.positiontup
    else:
        new_positiontup = pre_expanded_positiontup = None
    processors = self._bind_processors
    single_processors = cast('Mapping[str, _BindProcessorType[Any]]', processors)
    tuple_processors = cast('Mapping[str, Sequence[_BindProcessorType[Any]]]', processors)
    new_processors: Dict[str, _BindProcessorType[Any]] = {}
    replacement_expressions: Dict[str, Any] = {}
    to_update_sets: Dict[str, Any] = {}
    numeric_positiontup: Optional[List[str]] = None
    if self.positional and pre_expanded_positiontup is not None:
        names: Iterable[str] = pre_expanded_positiontup
        if self._numeric_binds:
            numeric_positiontup = []
    else:
        names = self.bind_names.values()
    ebn = self.escaped_bind_names
    for name in names:
        escaped_name = ebn.get(name, name) if ebn else name
        parameter = self.binds[name]
        if parameter in self.literal_execute_params:
            if escaped_name not in replacement_expressions:
                replacement_expressions[escaped_name] = self.render_literal_bindparam(parameter, render_literal_value=parameters.pop(escaped_name))
            continue
        if parameter in self.post_compile_params:
            if escaped_name in replacement_expressions:
                to_update = to_update_sets[escaped_name]
                values = None
            else:
                values = parameters.pop(name)
                leep_res = self._literal_execute_expanding_parameter(escaped_name, parameter, values)
                to_update, replacement_expr = leep_res
                to_update_sets[escaped_name] = to_update
                replacement_expressions[escaped_name] = replacement_expr
            if not parameter.literal_execute:
                parameters.update(to_update)
                if parameter.type._is_tuple_type:
                    assert values is not None
                    new_processors.update((('%s_%s_%s' % (name, i, j), tuple_processors[name][j - 1]) for i, tuple_element in enumerate(values, 1) for j, _ in enumerate(tuple_element, 1) if name in tuple_processors and tuple_processors[name][j - 1] is not None))
                else:
                    new_processors.update(((key, single_processors[name]) for key, _ in to_update if name in single_processors))
                if numeric_positiontup is not None:
                    numeric_positiontup.extend((name for name, _ in to_update))
                elif new_positiontup is not None:
                    new_positiontup.extend((name for name, _ in to_update))
                expanded_parameters[name] = [expand_key for expand_key, _ in to_update]
        elif new_positiontup is not None:
            new_positiontup.append(name)

    def process_expanding(m):
        key = m.group(1)
        expr = replacement_expressions[key]
        if m.group(2):
            tok = m.group(2).split('~~')
            be_left, be_right = (tok[1], tok[3])
            expr = ', '.join(('%s%s%s' % (be_left, exp, be_right) for exp in expr.split(', ')))
        return expr
    statement = re.sub(self._post_compile_pattern, process_expanding, pre_expanded_string)
    if numeric_positiontup is not None:
        assert new_positiontup is not None
        param_pos = {key: f'{self._numeric_binds_identifier_char}{num}' for num, key in enumerate(numeric_positiontup, self.next_numeric_pos)}
        statement = self._pyformat_pattern.sub(lambda m: param_pos[m.group(1)], statement)
        new_positiontup.extend(numeric_positiontup)
    expanded_state = ExpandedState(statement, parameters, new_processors, new_positiontup, expanded_parameters)
    if _populate_self:
        self._pre_expanded_string = pre_expanded_string
        self._pre_expanded_positiontup = pre_expanded_positiontup
        self.string = expanded_state.statement
        self.positiontup = list(expanded_state.positiontup or ()) if self.positional else None
        self._post_compile_expanded_state = expanded_state
    return expanded_state

def render_literal_value(self, value: Any, type_: sqltypes.TypeEngine[Any]) -> str:
    """Render the value of a bind parameter as a quoted literal.

        This is used for statement sections that do not accept bind parameters
        on the target driver/database.

        This should be implemented by subclasses using the quoting services
        of the DBAPI.

        """
    if value is None and (not type_.should_evaluate_none):
        return self.process(elements.Null._instance())
    processor = type_._cached_literal_processor(self.dialect)
    if processor:
        try:
            return processor(value)
        except Exception as e:
            raise exc.CompileError(f'Could not render literal value "{sql_util._repr_single_value(value)}" with datatype {type_}; see parent stack trace for more detail.') from e
    else:
        raise exc.CompileError(f'No literal value renderer is available for literal value "{sql_util._repr_single_value(value)}" with datatype {type_}')

def update_post_criteria_clause(self, update_stmt: Update, **kw: Any) -> Optional[str]:
    """provide a hook to override generation after the WHERE criteria
        in an UPDATE statement

        .. versionadded:: 2.1

        """
    if update_stmt._post_criteria_clause is not None:
        return self.process(update_stmt._post_criteria_clause, **kw)
    else:
        return None

def delete_post_criteria_clause(self, delete_stmt: Delete, **kw: Any) -> Optional[str]:
    """provide a hook to override generation after the WHERE criteria
        in a DELETE statement

        .. versionadded:: 2.1

        """
    if delete_stmt._post_criteria_clause is not None:
        return self.process(delete_stmt._post_criteria_clause, **kw)
    else:
        return None

def define_constraint_remote_table(self, constraint, table, preparer):
    """Format the remote table clause of a CREATE CONSTRAINT clause."""
    return preparer.format_table(table)

def _unescape_identifier(self, value: str) -> str:
    """Canonicalize an escaped identifier.

        Subclasses should override this to provide database-dependent
        unescaping behavior that reverses _escape_identifier.
        """
    return value.replace(self.escape_to_quote, self.escape_quote)

def _requires_quotes_illegal_chars(self, value):
    """Return True if the given identifier requires quoting, but
        not taking case convention into account."""
    return not self.legal_characters.match(str(value))

def quote(self, ident: str) -> str:
    """Conditionally quote an identifier.

        The identifier is quoted if it is a reserved word, contains
        quote-necessary characters, or is an instance of
        :class:`.quoted_name` which includes ``quote`` set to ``True``.

        Subclasses can override this to provide database-dependent
        quoting behavior for identifier names.

        :param ident: string identifier
        """
    force = getattr(ident, 'quote', None)
    if force is None:
        if ident in self._strings:
            return self._strings[ident]
        else:
            if self._requires_quotes(ident):
                self._strings[ident] = self.quote_identifier(ident)
            else:
                self._strings[ident] = ident
            return self._strings[ident]
    elif force:
        return self.quote_identifier(ident)
    else:
        return ident

def get(lastrowid, parameters):
    """given cursor.lastrowid value and the parameters used for INSERT,
            return a "row" that represents the primary key, either by
            using the "lastrowid" or by extracting values from the parameters
            that were sent along with the INSERT.

            """
    if lastrowid_processor is not None:
        lastrowid = lastrowid_processor(lastrowid)
    if lastrowid is None:
        return row_fn((getter(parameters) for getter, col in getters))
    else:
        return row_fn(((autoinc_getter(lastrowid, parameters) if autoinc_getter is not None else lastrowid) if col is autoinc_col else getter(parameters) for getter, col in getters))

def _get_crud_params(compiler: SQLCompiler, stmt: ValuesBase, compile_state: DMLState, toplevel: bool, **kw: Any) -> _CrudParams:
    """create a set of tuples representing column/string pairs for use
    in an INSERT or UPDATE statement.

    Also generates the Compiled object's postfetch, prefetch, and
    returning column collections, used for default handling and ultimately
    populating the CursorResult's prefetch_cols() and postfetch_cols()
    collections.

    """
    compiler.postfetch = []
    compiler.insert_prefetch = []
    compiler.update_prefetch = []
    compiler.implicit_returning = []
    visiting_cte = kw.get('visiting_cte', None)
    if visiting_cte is not None:
        kw.pop('accumulate_bind_names', None)
    assert 'accumulate_bind_names' not in kw, "Don't know how to handle insert within insert without a CTE"
    bindmarkers: MutableMapping[ColumnElement[Any], DMLTargetCopy[Any]] = {}
    kw['bindmarkers'] = bindmarkers
    _column_as_key, _getattr_col_key, _col_bind_name = _key_getters_for_crud_column(compiler, stmt, compile_state)
    compiler._get_bind_name_for_col = _col_bind_name
    if stmt._returning and stmt._return_defaults:
        raise exc.CompileError("Can't compile statement that includes returning() and return_defaults() simultaneously")
    if compile_state.isdelete:
        _setup_delete_return_defaults(compiler, stmt, compile_state, (), _getattr_col_key, _column_as_key, _col_bind_name, (), (), toplevel, kw)
        return _CrudParams([], [])
    if compiler.column_keys is None and compile_state._no_parameters:
        return _CrudParams([(c, compiler.preparer.format_column(c), _create_bind_param(compiler, c, None, required=True), (c.key,)) for c in stmt.table.columns if not c._omit_from_statements], [])
    stmt_parameter_tuples: Optional[List[Tuple[Union[str, ColumnClause[Any]], Any]]]
    spd: Optional[MutableMapping[_DMLColumnElement, Any]]
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        mp = compile_state._multi_parameters
        assert mp is not None
        spd = mp[0]
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    elif compile_state._dict_parameters:
        spd = compile_state._dict_parameters
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    else:
        stmt_parameter_tuples = spd_str_key = None
    if compiler.column_keys is None:
        parameters = {}
    elif stmt_parameter_tuples:
        assert spd_str_key is not None
        parameters = {_column_as_key(key): REQUIRED for key in compiler.column_keys if key not in spd_str_key}
    else:
        parameters = {_column_as_key(key): REQUIRED for key in compiler.column_keys}
    values: List[_CrudParamElementStr] = []
    if stmt_parameter_tuples is not None:
        _get_stmt_parameter_tuples_params(compiler, compile_state, parameters, stmt_parameter_tuples, _column_as_key, values, kw)
    check_columns: Dict[str, ColumnClause[Any]] = {}
    if dml.isupdate(compile_state) and compile_state.is_multitable:
        _get_update_multitable_params(compiler, stmt, compile_state, stmt_parameter_tuples, check_columns, _col_bind_name, _getattr_col_key, values, kw)
    if _compile_state_isinsert(compile_state) and stmt._select_names:
        assert not compile_state._has_multi_parameters
        _scan_insert_from_select_cols(compiler, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
        use_insertmanyvalues = False
        use_sentinel_columns = None
    else:
        use_insertmanyvalues, use_sentinel_columns = _scan_cols(compiler, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
    if parameters and stmt_parameter_tuples:
        check = set(parameters).intersection((_column_as_key(k) for k, v in stmt_parameter_tuples)).difference(check_columns)
        if check:
            if dml.isupdate(compile_state):
                tables_mentioned = set((c.table for c, v in stmt_parameter_tuples if isinstance(c, ColumnClause) and c.table is not None)).difference([compile_state.dml_table])
                multi_not_in_from = tables_mentioned.difference(compile_state._extra_froms)
                if tables_mentioned and (not compile_state.is_multitable or not compiler.render_table_with_column_in_update_from):
                    if not compiler.render_table_with_column_in_update_from:
                        preamble = 'Backend does not support additional tables in the SET clause'
                    else:
                        preamble = 'Statement is not a multi-table UPDATE statement'
                    raise exc.CompileError(f"""{preamble}; cannot include columns from table(s) {', '.join((f"'{t.description}'" for t in tables_mentioned))} in SET clause""")
                elif multi_not_in_from:
                    assert compiler.render_table_with_column_in_update_from
                    raise exc.CompileError(f"""Multi-table UPDATE statement does not include table(s) {', '.join((f"'{t.description}'" for t in multi_not_in_from))}""")
            raise exc.CompileError('Unconsumed column names: %s' % ', '.join(('%s' % (c,) for c in check)))
    is_default_metavalue_only = False
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        assert not stmt._select_names
        multi_extended_values = _extend_values_for_multiparams(compiler, stmt, compile_state, cast('Sequence[_CrudParamElementStr]', values), cast('Callable[..., str]', _column_as_key), kw)
        if bindmarkers:
            _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, values, kw)
            for m_v in multi_extended_values:
                _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, m_v, kw)
        return _CrudParams(values, multi_extended_values)
    elif not values and compiler.for_executemany and compiler.dialect.supports_default_metavalue:
        values = [(_as_dml_column(stmt.table.columns[0]), compiler.preparer.format_column(stmt.table.columns[0]), compiler.dialect.default_metavalue_token, ())]
        is_default_metavalue_only = True
    if bindmarkers:
        _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, values, kw)
    return _CrudParams(values, [], is_default_metavalue_only=is_default_metavalue_only, use_insertmanyvalues=use_insertmanyvalues, use_sentinel_columns=use_sentinel_columns)

def _append_param_insert_pk_returning(compiler, stmt, c, values, kw):
    """Create a primary key expression in the INSERT statement where
    we want to populate result.inserted_primary_key and RETURNING
    is available.

    """
    if c.default is not None:
        if c.default.is_sequence:
            if compiler.dialect.supports_sequences and (not c.default.optional or not compiler.dialect.sequences_optional):
                accumulated_bind_names: Set[str] = set()
                values.append((c, compiler.preparer.format_column(c), compiler.process(c.default, accumulate_bind_names=accumulated_bind_names, **kw), accumulated_bind_names))
            compiler.implicit_returning.append(c)
        elif c.default.is_clause_element:
            accumulated_bind_names = set()
            values.append((c, compiler.preparer.format_column(c), compiler.process(c.default.arg.self_group(), accumulate_bind_names=accumulated_bind_names, **kw), accumulated_bind_names))
            compiler.implicit_returning.append(c)
        else:
            values.append((c, compiler.preparer.format_column(c), _create_insert_prefetch_bind_param(compiler, c, **kw), (c.key,)))
    elif c is stmt.table._autoincrement_column or c.server_default is not None:
        compiler.implicit_returning.append(c)
    elif not c.nullable:
        _warn_pk_with_no_anticipated_value(c)

def _get_returning_modifiers(compiler, stmt, compile_state, toplevel):
    """determines RETURNING strategy, if any, for the statement.

    This is where it's determined what we need to fetch from the
    INSERT or UPDATE statement after it's invoked.

    """
    dialect = compiler.dialect
    need_pks = toplevel and _compile_state_isinsert(compile_state) and (not stmt._inline) and (not compiler.for_executemany or (dialect.insert_executemany_returning and stmt._return_defaults)) and (not stmt._returning) and (not compile_state._has_multi_parameters)
    postfetch_lastrowid = need_pks and dialect.postfetch_lastrowid and (stmt.table._autoincrement_column is not None)
    implicit_returning = need_pks and dialect.insert_returning and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and ((not postfetch_lastrowid or dialect.favor_returning_over_lastrowid) or compile_state._has_multi_parameters or stmt._return_defaults)
    if implicit_returning:
        postfetch_lastrowid = False
    if _compile_state_isinsert(compile_state):
        should_implicit_return_defaults = implicit_returning and stmt._return_defaults
        explicit_returning = should_implicit_return_defaults or stmt._returning or stmt._supplemental_returning
        use_insertmanyvalues = toplevel and compiler.for_executemany and dialect.use_insertmanyvalues and (explicit_returning or (dialect.use_insertmanyvalues_wo_returning and stmt._post_values_clause is None))
        use_sentinel_columns = None
        if use_insertmanyvalues and explicit_returning and stmt._sort_by_parameter_order:
            use_sentinel_columns = compiler._get_sentinel_column_for_table(stmt.table)
    elif compile_state.isupdate:
        should_implicit_return_defaults = stmt._return_defaults and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and dialect.update_returning
        use_insertmanyvalues = False
        use_sentinel_columns = None
    elif compile_state.isdelete:
        should_implicit_return_defaults = stmt._return_defaults and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and dialect.delete_returning
        use_insertmanyvalues = False
        use_sentinel_columns = None
    else:
        should_implicit_return_defaults = False
        use_insertmanyvalues = False
        use_sentinel_columns = None
    if should_implicit_return_defaults:
        if not stmt._return_defaults_columns:
            implicit_return_defaults = set(stmt.table.c)
        else:
            implicit_return_defaults = set(stmt._return_defaults_columns)
    else:
        implicit_return_defaults = None
    return (need_pks, implicit_returning or should_implicit_return_defaults, implicit_return_defaults, postfetch_lastrowid, use_insertmanyvalues, use_sentinel_columns)

def _compiler(self, dialect, **kw):
    """Return a compiler appropriate for this ClauseElement, given a
        Dialect."""
    return dialect.ddl_compiler(dialect, self, **kw)

@contextlib.contextmanager
def with_ddl_events(self, target, **kw):
    """helper context manager that will apply appropriate DDL events
        to a CREATE or DROP operation."""
    raise NotImplementedError()

@util.ro_memoized_property
def exported_columns(self) -> ReadOnlyColumnCollection[Optional[str], ColumnElement[Any]]:
    """Return the RETURNING columns as a column collection for this
        statement.

        .. versionadded:: 1.4

        """
    return WriteableColumnCollection(((c.key, c) for c in self._all_selected_columns if is_column_element(c))).as_readonly()

@property
def whereclause(self) -> Optional[ColumnElement[Any]]:
    """Return the completed WHERE clause for this :class:`.DMLWhereBase`
        statement.

        This assembles the current collection of WHERE criteria
        into a single :class:`_expression.BooleanClauseList` construct.


        .. versionadded:: 1.4

        """
    return BooleanClauseList._construct_for_whereclause(self._where_criteria)

def _compiler(self, dialect: Dialect, **kw: Any) -> Compiled:
    """Return a compiler appropriate for this ClauseElement, given a
        Dialect."""
    if TYPE_CHECKING:
        assert isinstance(self, ClauseElement)
    return dialect.statement_compiler(dialect, self, **kw)

def _execute_on_scalar(self, connection: Connection, distilled_params: _CoreMultiExecuteParams, execution_options: CoreExecuteOptionsParameter) -> Any:
    """an additional hook for subclasses to provide a different
        implementation for connection.scalar() vs. connection.execute().

        .. versionadded:: 2.0

        """
    return self._execute_on_connection(connection, distilled_params, execution_options).scalar()

def params(self, __optionaldict: Optional[Mapping[str, Any]]=None, /, **kwargs: Any) -> Self:
    """Return a copy with :func:`_expression.bindparam` elements
        replaced.

        Returns a copy of this ClauseElement with
        :func:`_expression.bindparam`
        elements replaced with values taken from the given dictionary::

          >>> clause = column("x") + bindparam("foo")
          >>> print(clause.compile().params)
          {'foo':None}
          >>> print(clause.params({"foo": 7}).compile().params)
          {'foo':7}

        """
    return self._replace_params(False, __optionaldict, kwargs)

@property
def expression(self) -> ColumnElement[Any]:
    """Return a column expression.

        Part of the inspection interface; returns self.

        """
    return self

@util.memoized_property
def proxy_set(self) -> FrozenSet[ColumnElement[Any]]:
    """set of all columns we are proxying

        as of 2.0 this is explicitly deannotated columns.  previously it was
        effectively deannotated columns but wasn't enforced.  annotated
        columns should basically not go into sets if at all possible because
        their hashing behavior is very non-performant.

        """
    return frozenset([self._deannotate()]).union(itertools.chain(*[c.proxy_set for c in self._proxies]))

def _uncached_proxy_list(self) -> List[ColumnElement[Any]]:
    """An 'uncached' version of proxy set.

        This list includes annotated columns which perform very poorly in
        set operations.

        """
    return [self] + list(itertools.chain(*[c._uncached_proxy_list() for c in self._proxies]))

def shares_lineage(self, othercolumn: ColumnElement[Any]) -> bool:
    """Return True if the given :class:`_expression.ColumnElement`
        has a common ancestor to this :class:`_expression.ColumnElement`."""
    return bool(self.proxy_set.intersection(othercolumn.proxy_set))

def _compare_name_for_result(self, other: ColumnElement[Any]) -> bool:
    """Return True if the given column element compares to this one
        when targeting within a result row."""
    return hasattr(other, 'name') and hasattr(self, 'name') and (other.name == self.name)

@HasMemoized.memoized_attribute
def _expression_label(self) -> Optional[str]:
    """a suggested label to use in the case that the column has no name,
        which should be used if possible as the explicit 'AS <label>'
        where this expression would normally have an anon label.

        this is essentially mostly what _proxy_key does except it returns
        None if the column has a normal name that can be used.

        """
    if getattr(self, 'name', None) is not None:
        return None
    elif self._annotations and 'proxy_key' in self._annotations:
        return cast(str, self._annotations['proxy_key'])
    else:
        return None

def _make_proxy(self, selectable: FromClause, *, primary_key: ColumnSet, foreign_keys: Set[KeyedColumnElement[Any]], name: Optional[str]=None, key: Optional[str]=None, name_is_truncatable: bool=False, compound_select_cols: Optional[Sequence[ColumnElement[Any]]]=None, **kw: Any) -> typing_Tuple[str, ColumnClause[_T]]:
    """Create a new :class:`_expression.ColumnElement` representing this
        :class:`_expression.ColumnElement` as it appears in the select list of
        a descending selectable.

        """
    if name is None:
        name = self._anon_name_label
        if key is None:
            key = self._proxy_key
    else:
        key = name
    assert key is not None
    co: ColumnClause[_T] = ColumnClause(coercions.expect(roles.TruncatedLabelRole, name) if name_is_truncatable else name, type_=getattr(self, 'type', None), _selectable=selectable)
    co._propagate_attrs = selectable._propagate_attrs
    if compound_select_cols:
        co._proxies = list(compound_select_cols)
    else:
        co._proxies = [self]
    if selectable._is_clone_of is not None:
        co._is_clone_of = selectable._is_clone_of.columns.get(key)
    return (key, co)

def label(self, name: Optional[str]) -> Label[_T]:
    """Produce a column label, i.e. ``<columnname> AS <name>``.

        This is a shortcut to the :func:`_expression.label` function.

        If 'name' is ``None``, an anonymous label name will be generated.

        """
    return Label(name, self, self.type)

def _dedupe_anon_label_idx(self, idx: int) -> str:
    """label to apply to a column that is anon labeled, but repeated
        in the SELECT, so that we have to make an "extra anon" label that
        disambiguates it from the previous appearance.

        these labels come out like "foo_bar_id__1" and have double underscores
        in them.

        """
    label = getattr(self, 'name', None)
    if label is None:
        return self._dedupe_anon_tq_label_idx(idx)
    else:
        return self._anon_label(label, add_hash=idx)

@property
def effective_value(self) -> Optional[_T]:
    """Return the value of this bound parameter,
        taking into account if the ``callable`` parameter
        was set.

        The ``callable`` value will be evaluated
        and returned if present, else ``value``.

        """
    if self.callable:
        return self.callable()
    else:
        return self.value

def __init__(self, template: Template):
    """Construct a :class:`_expression.TString` from a Python 3.14+
        template string.

        :param template: a Python 3.14+ template string (t-string) that
         contains SQL fragments and Python expressions to be interpolated.

        """
    self.parts: List[ClauseElement] = []
    if not isinstance(template, Template):
        raise exc.ArgumentError("pep-750 Tstring (e.g. t'...') expected")
    for part in template:
        if isinstance(part, str):
            self.parts.append(TextClause(part))
        else:
            assert hasattr(part, 'value')
            self.parts.append(coercions.expect(roles.TStringElementRole, part.value))

@classmethod
def and_(cls, initial_clause: Union[Literal[True], _ColumnExpressionArgument[bool], _NoArg]=_NoArg.NO_ARG, *clauses: _ColumnExpressionArgument[bool]) -> ColumnElement[bool]:
    """Produce a conjunction of expressions joined by ``AND``.

        See :func:`_sql.and_` for full documentation.
        """
