    column_kwargs = {}
    for dialect_name in self.dialect_options:
        dialect_options = self.dialect_options[dialect_name]._non_defaults
        for dialect_option_key, dialect_option_value in dialect_options.items():
            column_kwargs[dialect_name + '_' + dialect_option_key] = dialect_option_value
    server_default = self.server_default
    server_onupdate = self.server_onupdate
    if isinstance(server_default, (Computed, Identity)):
        args.append(server_default._copy(**kw))
        server_default = server_onupdate = None
    type_ = self.type
    if isinstance(type_, SchemaEventTarget):
        type_ = type_.copy(**kw)
    c = self._constructor(*args, name=self.name, type_=type_, key=self.key, primary_key=self.primary_key, unique=self.unique, system=self.system, index=self.index, autoincrement=self.autoincrement, default=self.default, server_default=server_default, onupdate=self.onupdate, server_onupdate=server_onupdate, doc=self.doc, comment=self.comment, _omit_from_statements=self._omit_from_statements, insert_sentinel=self._insert_sentinel, **column_kwargs)
    c.nullable = self.nullable
    c._user_defined_nullable = self._user_defined_nullable
    return self._schema_item_copy(c)

def _merge(self, other: Column[Any], *, omit_defaults: bool=False) -> None:
    """merge the elements of this column onto "other"

        this is used by ORM pep-593 merge and will likely need a lot
        of fixes.


        """
    if self.primary_key:
        other.primary_key = True
    if self.autoincrement != 'auto' and other.autoincrement == 'auto':
        other.autoincrement = self.autoincrement
    if self.system:
        other.system = self.system
    if self.info:
        other.info.update(self.info)
    type_ = self.type
    if not type_._isnull and other.type._isnull:
        if isinstance(type_, SchemaEventTarget):
            type_ = type_.copy()
        other.type = type_
        if isinstance(type_, SchemaEventTarget):
            type_._set_parent_with_dispatch(other)
        for impl in type_._variant_mapping.values():
            if isinstance(impl, SchemaEventTarget):
                impl._set_parent_with_dispatch(other)
    if self._user_defined_nullable is not NULL_UNSPECIFIED and other._user_defined_nullable is NULL_UNSPECIFIED:
        other.nullable = self.nullable
        other._user_defined_nullable = self._user_defined_nullable
    if not omit_defaults and self.default is not None and (other.default is None):
        new_default = self.default._copy()
        new_default._set_parent(other)
    if self.server_default and other.server_default is None:
        new_server_default = self.server_default
        if isinstance(new_server_default, FetchedValue):
            new_server_default = new_server_default._copy()
            new_server_default._set_parent(other)
        else:
            other.server_default = new_server_default
    if self.server_onupdate and other.server_onupdate is None:
        new_server_onupdate = self.server_onupdate
        new_server_onupdate = new_server_onupdate._copy()
        new_server_onupdate._set_parent(other)
    if self.onupdate and other.onupdate is None:
        new_onupdate = self.onupdate._copy()
        new_onupdate._set_parent(other)
    if self.index in (True, False) and other.index is None:
        other.index = self.index
    if self.unique in (True, False) and other.unique is None:
        other.unique = self.unique
    if self.doc and other.doc is None:
        other.doc = self.doc
    if self.comment and other.comment is None:
        other.comment = self.comment
    for const in self.constraints:
        if not const._type_bound:
            new_const = const._copy()
            new_const._set_parent(other)
    for fk in self.foreign_keys:
        if not fk.constraint:
            new_fk = fk._copy()
            new_fk._set_parent(other)

def _make_proxy(self, selectable: FromClause, primary_key: ColumnSet, foreign_keys: Set[KeyedColumnElement[Any]], name: Optional[str]=None, key: Optional[str]=None, name_is_truncatable: bool=False, compound_select_cols: Optional[_typing_Sequence[ColumnElement[Any]]]=None, **kw: Any) -> Tuple[str, ColumnClause[_T]]:
    """Create a *proxy* for this column.

        This is a copy of this ``Column`` referenced by a different parent
        (such as an alias or select statement).  The column should
        be used only in select scenarios, as its full DDL/default
        information is not transferred.

        """
    fk = [ForeignKey(col if col is not None else f._colspec, _unresolvable=col is None, _constraint=f.constraint) for f, col in [(fk, fk._resolve_column(raiseerr=False)) for fk in self.foreign_keys]]
    if name is None and self.name is None:
        raise exc.InvalidRequestError("Cannot initialize a sub-selectable with this Column object until its 'name' has been assigned.")
    try:
        c = self._constructor(coercions.expect(roles.TruncatedLabelRole, name if name else self.name) if name_is_truncatable else name or self.name, self.type, *fk, key=key if key else name if name else self.key, primary_key=self.primary_key, nullable=self.nullable, _proxies=list(compound_select_cols) if compound_select_cols else [self])
    except TypeError as err:
        raise TypeError('Could not create a copy of this %r object.  Ensure the class includes a _constructor() attribute or method which accepts the standard Column constructor arguments, or references the Column class itself.' % self.__class__) from err
    c.table = selectable
    c._propagate_attrs = selectable._propagate_attrs
    if selectable._is_clone_of is not None:
        c._is_clone_of = selectable._is_clone_of.columns.get(c.key)
    if self.primary_key:
        primary_key.add(c)
    if fk:
        foreign_keys.update(fk)
    return (c.key, c)

def _get_colspec(self, schema: Optional[Union[str, Literal[SchemaConst.RETAIN_SCHEMA, SchemaConst.BLANK_SCHEMA]]]=None, table_name: Optional[str]=None, _is_copy: bool=False) -> str:
    """Return a string based 'column specification' for this
        :class:`_schema.ForeignKey`.

        This is usually the equivalent of the string-based "tablename.colname"
        argument first passed to the object's constructor.

        """
    _colspec, effective_table_column = self._resolve_colspec_argument()
    if schema not in (None, RETAIN_SCHEMA):
        _schema, tname, colname = self._column_tokens
        if table_name is not None:
            tname = table_name
        if schema is BLANK_SCHEMA:
            return '%s.%s' % (tname, colname)
        else:
            return '%s.%s.%s' % (schema, tname, colname)
    elif table_name:
        schema, tname, colname = self._column_tokens
        if schema:
            return '%s.%s.%s' % (schema, table_name, colname)
        else:
            return '%s.%s' % (table_name, colname)
    elif effective_table_column is not None:
        if effective_table_column.table is None:
            if _is_copy:
                raise exc.InvalidRequestError(f"Can't copy ForeignKey object which refers to non-table bound Column {effective_table_column!r}")
            else:
                return effective_table_column.key
        return '%s.%s' % (effective_table_column.table.fullname, effective_table_column.key)
    else:
        assert isinstance(_colspec, str)
        return _colspec

