        return process
    else:
        return self.impl_instance.result_processor(dialect, coltype)

def find_left_clause_that_matches_given(clauses: Sequence[FromClause], join_from: FromClause) -> List[int]:
    """Given a list of FROM clauses and a selectable,
    return the indexes from the list of
    clauses which is derived from the selectable.

    """
    selectables = list(_from_objects(join_from))
    liberal_idx = []
    for i, f in enumerate(clauses):
        for s in selectables:
            if f.is_derived_from(s):
                liberal_idx.append(i)
                break
    if len(liberal_idx) > 1:
        conservative_idx = []
        for idx in liberal_idx:
            f = clauses[idx]
            for s in selectables:
                if set(surface_selectables(f)).intersection(surface_selectables(s)):
                    conservative_idx.append(idx)
                    break
        if conservative_idx:
            return conservative_idx
    return liberal_idx

def find_left_clause_to_join_from(clauses: Sequence[FromClause], join_to: _JoinTargetElement, onclause: Optional[ColumnElement[Any]]) -> List[int]:
    """Given a list of FROM clauses, a selectable,
    and optional ON clause, return a list of integer indexes from the
    clauses list indicating the clauses that can be joined from.

    The presence of an "onclause" indicates that at least one clause can
    definitely be joined from; if the list of clauses is of length one
    and the onclause is given, returns that index.   If the list of clauses
    is more than length one, and the onclause is given, attempts to locate
    which clauses contain the same columns.

    """
    idx = []
    selectables = set(_from_objects(join_to))
    if len(clauses) > 1 and onclause is not None:
        resolve_ambiguity = True
        cols_in_onclause = _find_columns(onclause)
    else:
        resolve_ambiguity = False
        cols_in_onclause = None
    for i, f in enumerate(clauses):
        for s in selectables.difference([f]):
            if resolve_ambiguity:
                assert cols_in_onclause is not None
                if set(f.c).union(s.c).issuperset(cols_in_onclause):
                    idx.append(i)
                    break
            elif onclause is not None or Join._can_join(f, s):
                idx.append(i)
                break
    if len(idx) > 1:
        toremove = set(chain(*[_expand_cloned(f._hide_froms) for f in clauses]))
        idx = [i for i in idx if clauses[i] not in toremove]
    if not idx and onclause is not None:
        return list(range(len(clauses)))
    else:
        return idx

def unwrap_order_by(clause: Any) -> Any:
    """Break up an 'order by' expression into individual column-expressions,
    without DESC/ASC/NULLS FIRST/NULLS LAST"""
    cols = util.column_set()
    result = []
    stack = deque([clause])
    while stack:
        t = stack.popleft()
        if isinstance(t, ColumnElement) and (not isinstance(t, UnaryExpression) or not operators.is_ordering_modifier(t.modifier)):
            if isinstance(t, Label) and (not isinstance(t.element, ScalarSelect)):
                t = t.element
                if isinstance(t, Grouping):
                    t = t.element
                stack.append(t)
                continue
            elif isinstance(t, _label_reference):
                t = t.element
                stack.append(t)
                continue
            if isinstance(t, _textual_label_reference):
                continue
            if t not in cols:
                cols.add(t)
                result.append(t)
        else:
            for c in t.get_children():
                stack.append(c)
    return result

def clause_is_present(clause, search):
    """Given a target clause and a second to search within, return True
    if the target is plainly present in the search without any
    subqueries or aliases involved.

    Basically descends through Joins.

    """
    for elem in surface_selectables(search):
        if clause == elem:
            return True
    else:
        return False

def adapt_criterion_to_null(crit: _CE, nulls: Collection[Any]) -> _CE:
    """given criterion containing bind params, convert selected elements
    to IS NULL.

    """

    def visit_binary(binary):
        if isinstance(binary.left, BindParameter) and binary.left._identifying_key in nulls:
            binary.left = binary.right
            binary.right = Null()
            binary.operator = operators.is_
            binary.negate = operators.is_not
        elif isinstance(binary.right, BindParameter) and binary.right._identifying_key in nulls:
            binary.right = Null()
            binary.operator = operators.is_
            binary.negate = operators.is_not
    return visitors.cloned_traverse(crit, {}, {'binary': visit_binary})

def reduce_columns(columns: _SelectIterable, *clauses: Optional[ClauseElement], **kw: bool) -> Collection[Union[ColumnElement[Any], AbstractTextClause]]:
    """given a list of columns, return a 'reduced' set based on natural
    equivalents.

    the set is reduced to the smallest list of columns which have no natural
    equivalent present in the list.  A "natural equivalent" means that two
    columns will ultimately represent the same value because they are related
    by a foreign key.

    \\*clauses is an optional list of join clauses which will be traversed
    to further identify columns that are "equivalent".

    \\**kw may specify 'ignore_nonexistent_tables' to ignore foreign keys
    whose tables are not yet configured, or columns that aren't yet present.

    This function is primarily used to determine the most minimal "primary
    key" from a selectable, by reducing the set of primary key columns present
    in the selectable to just those that are not repeated.

    """
    ignore_nonexistent_tables = kw.pop('ignore_nonexistent_tables', False)
    only_synonyms = kw.pop('only_synonyms', False)
    column_set = util.OrderedSet(columns)
    cset_no_text: util.OrderedSet[ColumnElement[Any]] = column_set.difference((c for c in column_set if is_text_clause(c)))
    omit = util.column_set()
    for col in cset_no_text:
        for fk in chain(*[c.foreign_keys for c in col.proxy_set]):
            for c in cset_no_text:
                if c is col:
                    continue
                try:
                    fk_col = fk.column
                except exc.NoReferencedColumnError:
                    if ignore_nonexistent_tables:
                        continue
                    else:
                        raise
                except exc.NoReferencedTableError:
                    if ignore_nonexistent_tables:
                        continue
                    else:
                        raise
                if fk_col.shares_lineage(c) and (not only_synonyms or c.name == col.name):
                    omit.add(col)
                    break
    if clauses:

        def visit_binary(binary):
            if binary.operator == operators.eq:
                cols = util.column_set(chain(*[c.proxy_set for c in cset_no_text.difference(omit)]))
                if binary.left in cols and binary.right in cols:
                    for c in reversed(cset_no_text):
                        if c.shares_lineage(binary.right) and (not only_synonyms or c.name == binary.left.name):
                            omit.add(c)
                            break
        for clause in clauses:
            if clause is not None:
                visitors.traverse(clause, {}, {'binary': visit_binary})
    return column_set.difference(omit)

def _offset_or_limit_clause(element: _LimitOffsetType, name: Optional[str]=None, type_: Optional[_TypeEngineArgument[int]]=None) -> ColumnElement[int]:
    """Convert the given value to an "offset or limit" clause.

    This handles incoming integers and converts to an expression; if
    an expression is already given, it is passed through.

    """
    return coercions.expect(roles.LimitOffsetRole, element, name=name, type_=type_)

def _offset_or_limit_clause_asint_if_possible(clause: _LimitOffsetType) -> _LimitOffsetType:
    """Return the offset or limit clause as a simple integer if possible,
    else return the clause.

    """
    if clause is None:
        return None
    if hasattr(clause, '_limit_offset_value'):
        value = clause._limit_offset_value
        return util.asint(value)
    else:
        return clause

def replacement_traverse(obj: Optional[ExternallyTraversible], opts: Mapping[str, Any], replace: _TraverseTransformCallableType[Any]) -> Optional[ExternallyTraversible]:
    """Clone the given expression structure, allowing element
    replacement by a given replacement function.

    This function is very similar to the :func:`.visitors.cloned_traverse`
    function, except instead of being passed a dictionary of visitors, all
    elements are unconditionally passed into the given replace function.
    The replace function then has the option to return an entirely new object
    which will replace the one given.  If it returns ``None``, then the object
    is kept in place.

    The difference in usage between :func:`.visitors.cloned_traverse` and
    :func:`.visitors.replacement_traverse` is that in the former case, an
    already-cloned object is passed to the visitor function, and the visitor
    function can then manipulate the internal state of the object.
    In the case of the latter, the visitor function should only return an
    entirely different object, or do nothing.

    The use case for :func:`.visitors.replacement_traverse` is that of
    replacing a FROM clause inside of a SQL structure with a different one,
    as is a common use case within the ORM.

    """
    cloned = {}
    stop_on = {id(x) for x in opts.get('stop_on', [])}

    def deferred_copy_internals(obj: ExternallyTraversible) -> ExternallyTraversible:
        return replacement_traverse(obj, opts, replace)

    def clone(elem: ExternallyTraversible, **kw: Any) -> ExternallyTraversible:
        if id(elem) in stop_on or 'no_replacement_traverse' in elem._annotations:
            return elem
        else:
            newelem = replace(elem)
            if newelem is not None:
                stop_on.add(id(newelem))
                return newelem
            else:
                id_elem = id(elem)
                if id_elem not in cloned:
                    if 'replace' in kw:
                        newelem = kw['replace'](elem)
                        if newelem is not None:
                            cloned[id_elem] = newelem
                            return newelem
                    cloned[id_elem] = newelem = elem._clone(**kw)
                    newelem._copy_internals(clone=clone, **kw)
                return cloned[id_elem]
    if obj is not None:
        obj = clone(obj, deferred_copy_internals=deferred_copy_internals, **opts)
    clone = None
    return obj

def dispatch(self, visit_symbol: InternalTraversal) -> Callable[..., Any]:
    """Given a method from :class:`.HasTraversalDispatch`, return the
        corresponding method on a subclass.

        """
    name = _dispatch_lookup[visit_symbol]
    return getattr(self, name, None)

def iterate(self, obj: Optional[ExternallyTraversible]) -> Iterator[ExternallyTraversible]:
    """Traverse the given expression structure, returning an iterator
        of all elements.

        """
    return iterate(obj, self.__traverse_options__)

def _compiler_dispatch(self: Visitable, visitor: Any, **kw: Any) -> str:
    """Look for an attribute named "visit_<visit_name>" on the
            visitor, and call it with the same kw params.

            """
    try:
        meth = getter(visitor)
    except AttributeError as err:
        return visitor.visit_unsupported_compilation(self, err, **kw)
    else:
        return meth(self, **kw)

def collate(expression: _ColumnExpressionArgument[str], collation: str) -> BinaryExpression[str]:
    """Return the clause ``expression COLLATE collation``.

    e.g.::

        collate(mycolumn, "utf8_bin")

    produces:

    .. sourcecode:: sql

        mycolumn COLLATE utf8_bin

    The collation expression is also quoted if it is a case sensitive
    identifier, e.g. contains uppercase characters.

    """
    if isinstance(expression, operators.ColumnOperators):
        return expression.collate(collation)
    else:
        return CollationClause._create_collation_expression(expression, collation)

def bitwise_not(expr: _ColumnExpressionArgument[_T]) -> UnaryExpression[_T]:
    """Produce a unary bitwise NOT clause, typically via the ``~`` operator.

    Not to be confused with boolean negation :func:`_sql.not_`.

    .. versionadded:: 2.0.2

    .. seealso::

        :ref:`operators_bitwise`


    """
    if isinstance(expr, operators.ColumnOperators):
        return expr.bitwise_not()
    else:
        return UnaryExpression._create_bitwise_not(expr)

def cte(selectable: HasCTE, name: Optional[str]=None, recursive: bool=False) -> CTE:
    """Return a new :class:`_expression.CTE`,
    or Common Table Expression instance.

    Please see :meth:`_expression.HasCTE.cte` for detail on CTE usage.

    """
    return coercions.expect(roles.HasCTERole, selectable).cte(name=name, recursive=recursive)

def _is_compiled() -> bool:
    """Utility function to indicate if this module is compiled or not."""
    return cython.compiled

def expect_warnings(*messages, **kw):
    """Context manager which expects one or more warnings.

    With no arguments, squelches all SAWarning emitted via
    sqlalchemy.util.warn and sqlalchemy.util.warn_limited.   Otherwise
    pass string expressions that will match selected warnings via regex;
    all non-matching warnings are sent through.

    The expect version **asserts** that the warnings were in fact seen.

    Note that the test suite sets SAWarning warnings to raise exceptions.

    """
    return _expect_warnings_sqla_only(sa_exc.SAWarning, messages, **kw)

@contextlib.contextmanager
def expect_warnings_on(db, *messages, **kw):
    """Context manager which expects one or more warnings on specific
    dialects.

    The expect version **asserts** that the warnings were in fact seen.

    """
    spec = db_spec(db)
    if isinstance(db, str) and (not spec(config._current)):
        yield
    else:
        with expect_warnings(*messages, **kw):
            yield

def emits_warning(*messages):
    """Decorator form of expect_warnings().

    Note that emits_warning does **not** assert that the warnings
    were in fact seen.

    """

    @decorator
    def decorate(fn, *args, **kw):
        with expect_warnings(*messages, assert_=False):
            return fn(*args, **kw)
    return decorate

def emits_warning_on(db, *messages):
    """Mark a test as emitting a warning on a specific dialect.

    With no arguments, squelches all SAWarning failures.  Or pass one or more
    strings; these will be matched to the root of the warning description by
    warnings.filterwarnings().

    Note that emits_warning_on does **not** assert that the warnings
    were in fact seen.

    """

    @decorator
    def decorate(fn, *args, **kw):
        with expect_warnings_on(db, *messages, assert_=False):
            return fn(*args, **kw)
    return decorate

def _expect_warnings_sqla_only(exc_cls, messages, regex=True, search_msg=False, assert_=True):
    """SQLAlchemy internal use only _expect_warnings().

    Alembic is using _expect_warnings() directly, and should be updated
    to use this new interface.

    """
    return _expect_warnings(exc_cls, messages, regex=regex, search_msg=search_msg, assert_=assert_, raise_on_any_unexpected=True)

def is_not(a, b, msg=None):
    """Assert a is not b, with repr messaging on failure."""
    assert a is not b, msg or '%r is %r' % (a, b)

def not_in(a, b, msg=None):
    """Assert a in not b, with repr messaging on failure."""
    assert a not in b, msg or '%r is in %r' % (a, b)

def assert_unordered_result(self, result, cls, *expected):
    """As assert_result, but the order of objects is not considered.

        The algorithm is very expensive but not a big deal for the small
        numbers of rows that the test suite manipulates.
        """

    class immutabledict(dict):

        def __hash__(self):
            return id(self)
    found = util.IdentitySet(result)
    expected = {immutabledict(e) for e in expected}
    for wrong in filterfalse(lambda o: isinstance(o, cls), found):
        fail('Unexpected type "%s", expected "%s"' % (type(wrong).__name__, cls.__name__))
    if len(found) != len(expected):
        fail('Unexpected object count "%s", expected "%s"' % (len(found), len(expected)))
    NOVALUE = object()

    def _compare_item(obj, spec):
        for key, value in spec.items():
            if isinstance(value, tuple):
                try:
                    self.assert_unordered_result(getattr(obj, key), value[0], *value[1])
                except AssertionError:
                    return False
            elif getattr(obj, key, NOVALUE) != value:
                return False
        return True
    for expected_item in expected:
        for found_item in found:
            if _compare_item(found_item, expected_item):
                found.remove(found_item)
                break
        else:
            fail('Expected %s instance with attributes %s not found.' % (cls.__name__, repr(expected_item)))
    return True

def _received_statement(self, execute_observed):
    """reconstruct the statement and params in terms
        of a target dialect, which for CompiledSQL is just DefaultDialect."""
    context = execute_observed.context
    compare_dialect = self._compile_dialect(execute_observed)
    cache_key = None
    extracted_parameters = None
    if 'schema_translate_map' in context.execution_options:
        map_ = context.execution_options['schema_translate_map']
    else:
        map_ = None
    if isinstance(execute_observed.clauseelement, BaseDDLElement):
        compiled = execute_observed.clauseelement.compile(dialect=compare_dialect, schema_translate_map=map_)
    else:
        compiled = execute_observed.clauseelement.compile(cache_key=cache_key, dialect=compare_dialect, column_keys=context.compiled.column_keys, for_executemany=context.compiled.for_executemany, schema_translate_map=map_)
    _received_statement = re.sub('[\\n\\t]', '', str(compiled))
    parameters = execute_observed.parameters
    if not parameters:
        _received_parameters = [compiled.construct_params(extracted_parameters=extracted_parameters)]
    else:
        _received_parameters = [compiled.construct_params(m, extracted_parameters=extracted_parameters) for m in parameters]
    return (_received_statement, _received_parameters)

def _assume_async(fn, *args, **kwargs):
    """Run a function in an asyncio loop unconditionally.

    This function is used for provisioning features like
    testing a database connection for server info.

    Note that for blocking IO database drivers, this means they block the
    event loop.

    """
    if not ENABLE_ASYNCIO:
        return fn(*args, **kwargs)
    return _async_util.run_in_greenlet(fn, *args, **kwargs)

def _maybe_async_provisioning(fn, *args, **kwargs):
    """Run a function in an asyncio loop if any current drivers might need it.

    This function is used for provisioning features that take
    place outside of a specific database driver being selected, so if the
    current driver that happens to be used for the provisioning operation
    is an async driver, it will run in asyncio and not fail.

    Note that for blocking IO database drivers, this means they block the
    event loop.

    """
    if not ENABLE_ASYNCIO:
        return fn(*args, **kwargs)
    if config.any_async:
        return _async_util.run_in_greenlet(fn, *args, **kwargs)
    else:
        return fn(*args, **kwargs)

def _maybe_async(fn, *args, **kwargs):
    """Run a function in an asyncio loop if the current selected driver is
    async.

    This function is used for test setup/teardown and tests themselves
    where the current DB driver is known.


    """
    if not ENABLE_ASYNCIO:
        return fn(*args, **kwargs)
    is_async = config._current.is_async
    if is_async:
        return _async_util.run_in_greenlet(fn, *args, **kwargs)
    else:
        return fn(*args, **kwargs)

def _maybe_async_wrapper(fn):
    """Apply the _maybe_async function to an existing function and return
    as a wrapped callable, supporting generator functions as well.

    This is currently used for pytest fixtures that support generator use.

    """
    if inspect.isgeneratorfunction(fn):
        _stop = object()

        def call_next(gen):
            try:
                return next(gen)
            except StopIteration:
                return _stop

        @wraps(fn)
        def wrap_fixture(*args, **kwargs):
            gen = fn(*args, **kwargs)
            while True:
                value = _maybe_async(call_next, gen)
                if value is _stop:
                    break
                yield value
    else:

        @wraps(fn)
        def wrap_fixture(*args, **kwargs):
            return _maybe_async(fn, *args, **kwargs)
    return wrap_fixture

def variation(argname_or_fn, cases=None):
    """a helper around testing.combinations that provides a single namespace
    that can be used as a switch.

    e.g.::

        @testing.variation("querytyp", ["select", "subquery", "legacy_query"])
        @testing.variation("lazy", ["select", "raise", "raise_on_sql"])
        def test_thing(self, querytyp, lazy, decl_base):
            class Thing(decl_base):
                __tablename__ = "thing"

                # use name directly
                rel = relationship("Rel", lazy=lazy.name)

            # use as a switch
            if querytyp.select:
                stmt = select(Thing)
            elif querytyp.subquery:
                stmt = select(Thing).subquery()
            elif querytyp.legacy_query:
