def __eq__(self, other):
    """'Deep, sparse compare.

        Deeply compare two entities, following the non-None attributes of the
        non-persisted object, if possible.

        """
    if other is self:
        return True
    elif not self.__class__ == other.__class__:
        return False
    if id(self) in _recursion_stack:
        return True
    _recursion_stack.add(id(self))
    try:
        try:
            self_key = sa.orm.attributes.instance_state(self).key
        except sa.orm.exc.NO_STATE:
            self_key = None
        if other is None:
            a = self
            b = other
        elif self_key is not None:
            a = other
            b = self
        else:
            a = self
            b = other
        for attr in list(a.__dict__):
            if attr.startswith('_'):
                continue
            value = getattr(a, attr)
            if isinstance(value, WriteOnlyCollection):
                continue
            try:
                battr = getattr(b, attr)
            except (AttributeError, sa_exc.UnboundExecutionError):
                return False
            if hasattr(value, '__iter__') and (not isinstance(value, str)):
                if hasattr(value, '__getitem__') and (not hasattr(value, 'keys')):
                    if list(value) != list(battr):
                        return False
                elif set(value) != set(battr):
                    return False
            elif value is not None and value != battr:
                return False
        return True
    finally:
        _recursion_stack.remove(id(self))

def function_call_count(variance=0.05, times=1, warmup=0):
    """Assert a target for a test case's function call count.

    The main purpose of this assertion is to detect changes in
    callcounts for various functions - the actual number is not as important.
    Callcounts are stored in a file keyed to Python version and OS platform
    information.  This file is generated automatically for new tests,
    and versioned so that unexpected changes in callcounts will be detected.

    """
    from sqlalchemy.util import decorator

    @decorator
    def wrap(fn, *args, **kw):
        for warm in range(warmup):
            fn(*args, **kw)
        timerange = range(times)
        with count_functions(variance=variance):
            for time in timerange:
                rv = fn(*args, **kw)
            return rv
    return wrap

