def inspect_formatargspec(args: List[str], varargs: Optional[str]=None, varkw: Optional[str]=None, defaults: Optional[Sequence[Any]]=None, kwonlyargs: Optional[Sequence[str]]=(), kwonlydefaults: Optional[Mapping[str, Any]]={}, annotations: Mapping[str, Any]={}, formatarg: Callable[[str], str]=str, formatvarargs: Callable[[str], str]=lambda name: '*' + name, formatvarkw: Callable[[str], str]=lambda name: '**' + name, formatvalue: Callable[[Any], str]=lambda value: '=' + repr(value), formatreturns: Callable[[Any], str]=lambda text: ' -> ' + str(text), formatannotation: Callable[[Any], str]=_formatannotation) -> str:
    """Copy formatargspec from python 3.7 standard library.

    Python 3 has deprecated formatargspec and requested that Signature
    be used instead, however this requires a full reimplementation
    of formatargspec() in terms of creating Parameter objects and such.
    Instead of introducing all the object-creation overhead and having
    to reinvent from scratch, just copy their compatibility routine.

    Ultimately we would need to rewrite our "decorator" routine completely
    which is not really worth it right now, until all Python 2.x support
    is dropped.

    """
    kwonlydefaults = kwonlydefaults or {}
    annotations = annotations or {}

    def formatargandannotation(arg):
        result = formatarg(arg)
        if arg in annotations:
            result += ': ' + formatannotation(annotations[arg])
        return result
    specs = []
    if defaults:
        firstdefault = len(args) - len(defaults)
    else:
        firstdefault = -1
    for i, arg in enumerate(args):
        spec = formatargandannotation(arg)
        if defaults and i >= firstdefault:
            spec = spec + formatvalue(defaults[i - firstdefault])
        specs.append(spec)
    if varargs is not None:
        specs.append(formatvarargs(formatargandannotation(varargs)))
    elif kwonlyargs:
        specs.append('*')
    if kwonlyargs:
        for kwonlyarg in kwonlyargs:
            spec = formatargandannotation(kwonlyarg)
            if kwonlydefaults and kwonlyarg in kwonlydefaults:
                spec += formatvalue(kwonlydefaults[kwonlyarg])
            specs.append(spec)
    if varkw is not None:
        specs.append(formatvarkw(formatargandannotation(varkw)))
    result = '(' + ', '.join(specs) + ')'
    if 'return' in annotations:
        result += formatreturns(formatannotation(annotations['return']))
    return result

def dataclass_fields(cls: Type[Any]) -> Iterable[dataclasses.Field[Any]]:
    """Return a sequence of all dataclasses.Field objects associated
    with a class as an already processed dataclass.

    The class must **already be a dataclass** for Field objects to be returned.

    """
    if dataclasses.is_dataclass(cls):
        return dataclasses.fields(cls)
    else:
        return []

def local_dataclass_fields(cls: Type[Any]) -> Iterable[dataclasses.Field[Any]]:
    """Return a sequence of all dataclasses.Field objects associated with
    an already processed dataclass, excluding those that originate from a
    superclass.

    The class must **already be a dataclass** for Field objects to be returned.

    """
    if dataclasses.is_dataclass(cls):
        super_fields: Set[dataclasses.Field[Any]] = set()
        for sup in cls.__bases__:
            super_fields.update(dataclass_fields(sup))
        return [f for f in dataclasses.fields(cls) if f not in super_fields]
    else:
        return []

def deprecated_params(**specs: Tuple[str, str]) -> Callable[[_F], _F]:
    """Decorates a function to warn on use of certain parameters.

    e.g. ::

        @deprecated_params(
            weak_identity_map=(
                "2.0",
                "the :paramref:`.Session.weak_identity_map parameter "
                "is deprecated.",
            )
        )
        def some_function(**kwargs): ...

    """
    messages: Dict[str, str] = {}
    versions: Dict[str, str] = {}
    version_warnings: Dict[str, Type[exc.SADeprecationWarning]] = {}
    for param, (version, message) in specs.items():
        versions[param] = version
        messages[param] = _sanitize_restructured_text(message)
        version_warnings[param] = exc.SADeprecationWarning

    def decorate(fn: _F) -> _F:
        spec = compat.inspect_getfullargspec(fn)
        check_defaults: Union[Set[str], Tuple[()]]
        if spec.defaults is not None:
            defaults = dict(zip(spec.args[len(spec.args) - len(spec.defaults):], spec.defaults))
            check_defaults = set(defaults).intersection(messages)
            check_kw = set(messages).difference(defaults)
        elif spec.kwonlydefaults is not None:
            defaults = spec.kwonlydefaults
            check_defaults = set(defaults).intersection(messages)
            check_kw = set(messages).difference(defaults)
        else:
            check_defaults = ()
            check_kw = set(messages)
        check_any_kw = spec.varkw

        @decorator
        def warned(fn: _F, *args: Any, **kwargs: Any) -> _F:
            for m in check_defaults:
                if defaults[m] is None and kwargs[m] is not None or (defaults[m] is not None and kwargs[m] != defaults[m]):
                    _warn_with_version(messages[m], versions[m], version_warnings[m], stacklevel=3)
            if check_any_kw in messages and set(kwargs).difference(check_defaults):
                assert check_any_kw is not None
                _warn_with_version(messages[check_any_kw], versions[check_any_kw], version_warnings[check_any_kw], stacklevel=3)
            for m in check_kw:
                if m in kwargs:
                    _warn_with_version(messages[m], versions[m], version_warnings[m], stacklevel=3)
            return fn(*args, **kwargs)
        doc = fn.__doc__ if fn.__doc__ is not None else ''
        if doc:
            doc = inject_param_text(doc, {param: '.. deprecated:: %s %s' % ('1.4' if version == '2.0' else version, message or '') for param, (version, message) in specs.items()})
        decorated = warned(fn)
        decorated.__doc__ = doc
        return decorated
    return decorate

