    """apply alternate annotations to a class, with a callable to restore
    the pristine state of the former.
    This is used strictly to provide dataclasses on a mapped class, where
    in some cases where are making dataclass fields based on an attribute
    that is actually a python descriptor on a superclass which we called
    to get a value.
    if dataclasses were to give us a way to achieve this without swapping
    __annotations__, that would be much better.
    """
    delattr_ = object()
    is_pep649 = hasattr(cls, '__annotate__') and cls.__annotate__ is not None
    if is_pep649:
        memoized = {'__annotate__': getattr(cls, '__annotate__', delattr_)}
    else:
        memoized = {'__annotations__': getattr(cls, '__annotations__', delattr_)}
    cls.__annotations__ = new_annotations

    def restore():
        for k, v in memoized.items():
            if v is delattr_:
                delattr(cls, k)
            else:
                setattr(cls, k, v)
    return restore

def decode_slice(slc: slice) -> Tuple[Any, ...]:
    """decode a slice object as sent to __getitem__.

    takes into account the 2.5 __index__() method, basically.

    """
    ret: List[Any] = []
    for x in (slc.start, slc.stop, slc.step):
        if hasattr(x, '__index__'):
            x = x.__index__()
        ret.append(x)
    return tuple(ret)

def map_bits(fn: Callable[[int], Any], n: int) -> Iterator[Any]:
    """Call the given function given each nonzero bit from n."""
    while n:
        b = n & ~n + 1
        yield fn(b)
        n ^= b

def get_cls_kwargs(cls: type, *, _set: Optional[Set[str]]=None, raiseerr: bool=False) -> Optional[Set[str]]:
    """Return the full set of inherited kwargs for the given `cls`.

    Probes a class's __init__ method, collecting all named arguments.  If the
    __init__ defines a \\**kwargs catch-all, then the constructor is presumed
    to pass along unrecognized keywords to its base classes, and the
    collection process is repeated recursively on each of the bases.

    Uses a subset of inspect.getfullargspec() to cut down on method overhead,
    as this is used within the Core typing system to create copies of type
    objects which is a performance-sensitive operation.

    No anonymous tuple arguments please !

    """
    toplevel = _set is None
    if toplevel:
        _set = set()
    assert _set is not None
    ctr = cls.__dict__.get('__init__', False)
    has_init = ctr and isinstance(ctr, types.FunctionType) and isinstance(ctr.__code__, types.CodeType)
    if has_init:
        names, has_kw = _inspect_func_args(ctr)
        _set.update(names)
        if not has_kw and (not toplevel):
            if raiseerr:
                raise TypeError(f"given cls {cls} doesn't have an __init__ method")
            else:
                return None
    else:
        has_kw = False
    if not has_init or has_kw:
        for c in cls.__bases__:
            if get_cls_kwargs(c, _set=_set) is None:
                break
    _set.discard('self')
    return _set

def get_callable_argspec(fn: Callable[..., Any], no_self: bool=False, _is_init: bool=False) -> compat.FullArgSpec:
    """Return the argument signature for any callable.

    All pure-Python callables are accepted, including
    functions, methods, classes, objects with __call__;
    builtins and other edge cases like functools.partial() objects
    raise a TypeError.

    """
    if inspect.isbuiltin(fn):
        raise TypeError("Can't inspect builtin: %s" % fn)
    elif inspect.isfunction(fn) or (hasattr(fn, '__code__') and (not inspect.isclass(fn)) and (not inspect.ismethod(fn))):
        if _is_init and no_self:
            spec = compat.inspect_getfullargspec(fn)
            return compat.FullArgSpec(spec.args[1:], spec.varargs, spec.varkw, spec.defaults, spec.kwonlyargs, spec.kwonlydefaults, spec.annotations)
        else:
            return compat.inspect_getfullargspec(fn)
    elif inspect.ismethod(fn):
        if no_self and (_is_init or fn.__self__):
            spec = compat.inspect_getfullargspec(fn.__func__)
            return compat.FullArgSpec(spec.args[1:], spec.varargs, spec.varkw, spec.defaults, spec.kwonlyargs, spec.kwonlydefaults, spec.annotations)
        else:
            return compat.inspect_getfullargspec(fn.__func__)
    elif inspect.isclass(fn):
        return get_callable_argspec(fn.__init__, no_self=no_self, _is_init=True)
    elif hasattr(fn, '__func__'):
        return compat.inspect_getfullargspec(fn.__func__)
    elif hasattr(fn, '__call__'):
        if inspect.ismethod(fn.__call__):
            return get_callable_argspec(fn.__call__, no_self=no_self)
        else:
            raise TypeError("Can't inspect callable: %s" % fn)
    else:
        raise TypeError("Can't inspect callable: %s" % fn)

def format_argspec_init(method, grouped=True):
    """format_argspec_plus with considerations for typical __init__ methods

    Wraps format_argspec_plus with error handling strategies for typical
    __init__ cases:

    .. sourcecode:: text

      object.__init__ -> (self)
      other unreflectable (usually C) -> (self, *args, **kwargs)

    """
    if method is object.__init__:
        grouped_args = '(self)'
        args = '(self)' if grouped else 'self'
        proxied = '()' if grouped else ''
    else:
        try:
            return format_argspec_plus(method, grouped=grouped)
        except TypeError:
            grouped_args = '(self, *args, **kwargs)'
            args = grouped_args if grouped else 'self, *args, **kwargs'
            proxied = '(*args, **kwargs)' if grouped else '*args, **kwargs'
    return dict(self_arg='self', grouped_args=grouped_args, apply_pos=args, apply_kw=args, apply_pos_proxied=proxied, apply_kw_proxied=proxied)

def getargspec_init(method):
    """inspect.getargspec with considerations for typical __init__ methods

    Wraps inspect.getargspec with error handling for typical __init__ cases:

    .. sourcecode:: text

      object.__init__ -> (self)
      other unreflectable (usually C) -> (self, *args, **kwargs)

    """
    try:
        return compat.inspect_getfullargspec(method)
    except TypeError:
        if method is object.__init__:
            return (['self'], None, None, None)
        else:
            return (['self'], 'args', 'kwargs', None)

def unbound_method_to_callable(func_or_cls):
    """Adjust the incoming callable such that a 'self' argument is not
    required.

    """
    if isinstance(func_or_cls, types.MethodType) and (not func_or_cls.__self__):
        return func_or_cls.__func__
    else:
        return func_or_cls

