def only_once(fn: Callable[..., _T], retry_on_exception: bool) -> Callable[..., Optional[_T]]:
    """Decorate the given function to be a no-op after it is called exactly
    once."""
    once = [fn]

    def go(*arg: Any, **kw: Any) -> Optional[_T]:
        strong_fn = fn
        if once:
            once_fn = once.pop()
            try:
                return once_fn(*arg, **kw)
            except:
                if retry_on_exception:
                    once.insert(0, once_fn)
                raise
        return None
    return go

def wrap_callable(wrapper, fn):
    """Augment functools.update_wrapper() to work with objects with
    a ``__call__()`` method.

    :param fn:
      object with __call__ method

    """
    if hasattr(fn, '__name__'):
        return update_wrapper(wrapper, fn)
    else:
        _f = wrapper
        _f.__name__ = fn.__class__.__name__
        if hasattr(fn, '__module__'):
            _f.__module__ = fn.__module__
        if hasattr(fn.__call__, '__doc__') and fn.__call__.__doc__:
            _f.__doc__ = fn.__call__.__doc__
        elif fn.__doc__:
            _f.__doc__ = fn.__doc__
        return _f

def repr_tuple_names(names: List[str]) -> Optional[str]:
    """Trims a list of strings from the middle and return a string of up to
    four elements. Strings greater than 11 characters will be truncated"""
    if len(names) == 0:
        return None
    flag = len(names) <= 4
    names = names[0:4] if flag else names[0:3] + names[-1:]
    res = ['%s..' % name[:11] if len(name) > 11 else name for name in names]
    if flag:
        return ', '.join(res)
    else:
        return '%s, ..., %s' % (', '.join(res[0:3]), res[-1])

def import_prefix(self, path: str) -> None:
    """Resolve all the modules in the registry that start with the
        specified path.
        """
    for module in self.module_registry:
        if self.prefix:
            key = module.split(self.prefix)[-1].replace('.', '_')
        else:
            key = module
        if (not path or module.startswith(path)) and key not in self.__dict__:
            __import__(module, globals(), locals())
            self.__dict__[key] = globals()[key] = sys.modules[module]

def empty(self) -> bool:
    """Return True if the queue is empty, False otherwise (not
        reliable!)."""
    with self.mutex:
        return self._empty()

def full(self) -> bool:
    """Return True if the queue is full, False otherwise (not
        reliable!)."""
    with self.mutex:
        return self._full()

def put(self, item: _T, block: bool=True, timeout: Optional[float]=None) -> None:
    """Put an item into the queue.

        If optional args `block` is True and `timeout` is None (the
        default), block if necessary until a free slot is
        available. If `timeout` is a positive number, it blocks at
        most `timeout` seconds and raises the ``Full`` exception if no
        free slot was available within that time.  Otherwise (`block`
        is false), put an item on the queue if a free slot is
        immediately available, else raise the ``Full`` exception
        (`timeout` is ignored in that case).
        """
    with self.not_full:
        if not block:
            if self._full():
                raise Full
        elif timeout is None:
            while self._full():
                self.not_full.wait()
        else:
            if timeout < 0:
                raise ValueError("'timeout' must be a positive number")
            endtime = _time() + timeout
            while self._full():
                remaining = endtime - _time()
                if remaining <= 0.0:
                    raise Full
                self.not_full.wait(remaining)
        self._put(item)
        self.not_empty.notify()

def put_nowait(self, item: _T) -> None:
    """Put an item into the queue without blocking.

        Only enqueue the item if a free slot is immediately available.
        Otherwise raise the ``Full`` exception.
        """
    return self.put(item, False)

def get(self, block: bool=True, timeout: Optional[float]=None) -> _T:
    """Remove and return an item from the queue.

        If optional args `block` is True and `timeout` is None (the
        default), block if necessary until an item is available. If
        `timeout` is a positive number, it blocks at most `timeout`
        seconds and raises the ``Empty`` exception if no item was
        available within that time.  Otherwise (`block` is false),
        return an item if one is immediately available, else raise the
        ``Empty`` exception (`timeout` is ignored in that case).

        """
    with self.not_empty:
        if not block:
            if self._empty():
                raise Empty
        elif timeout is None:
            while self._empty():
                self.not_empty.wait()
        else:
            if timeout < 0:
                raise ValueError("'timeout' must be a positive number")
            endtime = _time() + timeout
            while self._empty():
                remaining = endtime - _time()
                if remaining <= 0.0:
                    raise Empty
                self.not_empty.wait(remaining)
        item = self._get()
        self.not_full.notify()
        return item

def get_nowait(self) -> _T:
    """Remove and return an item from the queue without blocking.

        Only get an item if one is immediately available. Otherwise
        raise the ``Empty`` exception.
        """
    return self.get(False)

def _run_console_script(self, path: str, options: Dict[str, Any]) -> None:
    """Run a Python console application from within the process.

        Used for black, zimports

        """
    is_posix = os.name == 'posix'
    entrypoint_name = options['entrypoint']
    for entry in compat.importlib_metadata_get('console_scripts'):
        if entry.name == entrypoint_name:
            impl = entry
            break
    else:
        raise Exception(f'Could not find entrypoint console_scripts.{entrypoint_name}')
    cmdline_options_str = options.get('options', '')
    cmdline_options_list = shlex.split(cmdline_options_str, posix=is_posix) + [path]
    kw: Dict[str, Any] = {}
    if self.suppress_output:
        kw['stdout'] = kw['stderr'] = subprocess.DEVNULL
    subprocess.run([sys.executable, '-c', 'import %s; %s.%s()' % (impl.module, impl.module, impl.attr)] + cmdline_options_list, cwd=str(self.source_root), **kw)

def de_stringify_annotation(cls: Type[Any], annotation: _AnnotationScanType, originating_module: str, locals_: Mapping[str, Any], *, str_cleanup_fn: Optional[Callable[[str, str], str]]=None, include_generic: bool=False, _already_seen: Optional[Set[Any]]=None) -> Type[Any]:
    """Resolve annotations that may be string based into real objects.

    This is particularly important if a module defines "from __future__ import
    annotations", as everything inside of __annotations__ is a string. We want
    to at least have generic containers like ``Mapped``, ``Union``, ``List``,
    etc.

    """
    original_annotation = annotation
    if is_fwd_ref(annotation):
        annotation = annotation.__forward_arg__
    if isinstance(annotation, str):
        if str_cleanup_fn:
            annotation = str_cleanup_fn(annotation, originating_module)
        annotation = eval_expression(annotation, originating_module, locals_=locals_, in_class=cls)
    if include_generic and is_generic(annotation) and (not is_literal(annotation)):
        if _already_seen is None:
            _already_seen = set()
        if annotation in _already_seen:
            return original_annotation
        else:
            _already_seen.add(annotation)
        elements = tuple((de_stringify_annotation(cls, elem, originating_module, locals_, str_cleanup_fn=str_cleanup_fn, include_generic=include_generic, _already_seen=_already_seen) for elem in annotation.__args__))
        return _copy_generic_annotation_with(annotation, elements)
    return annotation

