    if is_generic(type_) and get_origin(type_) in (dict, set, list, collections_abc.MutableSet, collections_abc.MutableMapping, collections_abc.MutableSequence, collections_abc.Mapping, collections_abc.Sequence) and (not re.match('typing.(?:Dict|List|Set|.*Mapping|.*Sequence|.*Set)', repr(type_))):
