        return type_

def _de_optionalize_fwd_ref_union_types(type_: ForwardRef, return_has_none: bool) -> Union[_AnnotationScanType, bool]:
    """return the non-optional type for Optional[], Union[None, ...], x|None,
    etc. without de-stringifying forward refs.

    unfortunately this seems to require lots of hardcoded heuristics

    """
    annotation = type_.__forward_arg__
    mm = re.match('^(.+?)\\[(.+)\\]$', annotation)
    if mm:
        g1 = mm.group(1).split('.')[-1]
        if g1 == 'Optional':
            return True if return_has_none else ForwardRef(mm.group(2))
        elif g1 == 'Union':
            if '[' in mm.group(2):
                elements: list[str] = []
                current: list[str] = []
                ignore_comma = 0
                for char in mm.group(2):
                    if char == '[':
                        ignore_comma += 1
                    elif char == ']':
                        ignore_comma -= 1
                    elif ignore_comma == 0 and char == ',':
                        elements.append(''.join(current).strip())
                        current.clear()
                        continue
                    current.append(char)
            else:
                elements = re.split(',\\s*', mm.group(2))
            parts = [ForwardRef(elem) for elem in elements if elem != 'None']
            if return_has_none:
                return len(elements) != len(parts)
            else:
                return make_union_type(*parts) if parts else Never
        else:
            return False if return_has_none else type_
    pipe_tokens = re.split('\\s*\\|\\s*', annotation)
    has_none = 'None' in pipe_tokens
    if return_has_none:
        return has_none
    if has_none:
        anno_str = '|'.join((p for p in pipe_tokens if p != 'None'))
        return ForwardRef(anno_str) if anno_str else Never
    return type_

